->>''''157''''\n AND c.successors=jsonb_build_object(''''157'''',local_invoice_fingerprint(),''''158'''',fa3_draft_fingerprint(),''''159'''',b2b_invoice_fingerprint(),''''160'''',b2b_credit_fingerprint(),''''161'''',credit_source_upgrade_fingerprint(),''''162'''',financial_return_fingerprint())\n AND jsonb_array_length(c.replaced_functions)=8\n AND c.original014_indexes=c.original#>''''{160,original014_indexes}''''\n AND c.original014_indexes=(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indexrelid IN(''''public.document_order_mode''''::regclass,''''public.document_return_mode''''::regclass)),false);\nEND'') IS DISTINCT FROM convert_from(decode('''',''hex''),''UTF8'') THEN RETURN false;END IF;\n   entry219:=jsonb_set(entry219,''{1}'',to_jsonb(convert_from(decode('''',''hex''),''UTF8'')),false);\n  END IF;\n  items219:=items219||jsonb_build_array(entry219);\n END LOOP;\n financial162219:=jsonb_set(financial162219,''{functions}'',items219,false);\n predecessors214:=jsonb_set(predecessors214,''{fingerprints,162}'',to_jsonb(md5(financial162219::text)),false);\n\n -- Full current buyer body is independently code-bound by complete C22 before dispatch.\n SELECT prosrc INTO STRICT buyer_source251 FROM pg_proc WHERE oid=''public.buyer_address_guards()''::regprocedure;\n IF (public.pim_dictionary_function_metadata(''public.buyer_address_guards()''::regprocedure)-''definition'') IS DISTINCT FROM ''{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"argument_modes\":null,\"argument_names\":null,\"arguments\":\"\",\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"cost\":100,\"defaults\":null,\"kind\":\"f\",\"language\":\"plpgsql\",\"leakproof\":false,\"owner\":\"postgres\",\"parallel\":\"u\",\"result\":\"boolean\",\"returns_set\":false,\"rows\":0,\"security_definer\":true,\"signature\":\"buyer_address_guards()\",\"strict\":false,\"volatility\":\"s\"}''::jsonb THEN RETURN false;END IF;\n SELECT jsonb_build_object(\n ''tables'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''kind'',c.relkind,''rls'',c.relrowsecurity,''force_rls'',c.relforcerowsecurity,''owner'',pg_get_userbyid(c.relowner),''acl'',(SELECT jsonb_agg(jsonb_build_object(''grantee'',CASE WHEN x.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x.grantee) END,''grantor'',pg_get_userbyid(x.grantor),''privilege'',x.privilege_type,''grantable'',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) x)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''buyer_address_'') AND c.relkind IN(''r'',''p'')),\n ''columns'',(SELECT jsonb_agg(jsonb_build_object(''table'',c.relname,''number'',a.attnum,''name'',a.attname,''type'',format_type(a.atttypid,a.atttypmod),''not_null'',a.attnotnull,''identity'',a.attidentity,''generated'',a.attgenerated,''default'',pg_get_expr(d.adbin,d.adrelid),''collation'',(SELECT collname FROM pg_collation WHERE oid=a.attcollation)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''buyer_address_'') AND a.attnum>0 AND NOT a.attisdropped),\n ''constraints'',(SELECT jsonb_agg(jsonb_build_object(''table'',t.relname,''name'',c.conname,''def'',pg_get_constraintdef(c.oid,true),''validated'',c.convalidated) ORDER BY t.relname,c.conname) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid WHERE t.relnamespace=''public''::regnamespace AND starts_with(t.relname,''buyer_address_'')),\n ''indexes'',(SELECT jsonb_agg(jsonb_build_object(''table'',t.relname,''name'',idx.relname,''def'',pg_get_indexdef(i.indexrelid),''valid'',i.indisvalid,''ready'',i.indisready) ORDER BY t.relname,idx.relname) FROM pg_index i JOIN pg_class t ON 