"config":["search_path=pg_catalog, public","TimeZone=UTC"],"definition":"CREATE OR REPLACE FUNCTION public.buyer_address_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE seal buyer_address_manifest%ROWTYPE; basis record; basis_oid oid;owner_name text;buyer_meta251 jsonb;buyer_entry251 jsonb;buyer_items251 jsonb;buyer_source251 text;buyer_fp251 text;packing_gate214 jsonb;predecessors214 jsonb;financial214 jsonb;tables214 jsonb;functions214 jsonb;family214 text;financial162219 jsonb;entry219 jsonb;items219 jsonb;source219 text;\nBEGIN\n IF public.partial_sale204_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n IF to_regclass(''public.buyer_address_manifest'') IS NULL\n  OR to_regclass(''public.buyer_address_state'') IS NULL OR to_regclass(''public.buyer_address_previews'') IS NULL\n  OR to_regclass(''public.buyer_address_receipts'') IS NULL\n  OR(SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''buyer_address_'') AND relkind IN(''r'',''p''))\n   IS DISTINCT FROM ARRAY[''buyer_address_manifest'',''buyer_address_previews'',''buyer_address_receipts'',''buyer_address_state'']::text[]\n  OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''buyer_address_'') AND relkind IN(''v'',''m'',''S'',''f''))\n  OR(SELECT count(*) FROM public.buyer_address_manifest)<>1 THEN RETURN false;END IF;\n SELECT * INTO seal FROM public.buyer_address_manifest;\n -- Exact Source189 representation inverse, never a current IAM substitute.\n SELECT to_jsonb(g) INTO STRICT packing_gate214 FROM (\nWITH expected AS (SELECT * FROM jsonb_to_recordset(''[{\"identity\":\"public.packing_required_field_valid(jsonb,jsonb,jsonb,jsonb,jsonb)\",\"body_sha256\":\"c2782c0a82efed2eb49e97858d963e6e175e40fd8919440a48d2f719ca87c922\",\"returns\":\"boolean\"