e,''name'',t.tgname,''def'',pg_get_triggerdef(t.oid),''enabled'',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(starts_with(t.tgname,''buyer_address_'') OR(c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''buyer_address_'')))),\n ''policies'',(SELECT jsonb_agg(jsonb_build_object(''table'',c.relname,''name'',p.polname,''command'',p.polcmd,''permissive'',p.polpermissive,''roles'',(SELECT jsonb_agg(CASE WHEN r=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r),''using'',pg_get_expr(p.polqual,p.polrelid),''check'',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY c.relname,p.polname) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''buyer_address_'')),\n ''functions'',(SELECT jsonb_agg(jsonb_build_object(''name'',p.proname,''args'',pg_get_function_identity_arguments(p.oid),''def'',CASE WHEN p.oid IN(''public.financial_return_upgrade_valid()''::regprocedure,''public.buyer_address_guards()''::regprocedure) THEN pg_get_functiondef(p.oid) ELSE public.partial_sale204_predecessor_definition(p.oid) END,''owner'',pg_get_userbyid(p.proowner),''acl'',(SELECT jsonb_agg(jsonb_build_object(''grantee'',CASE WHEN x.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x.grantee) END,''grantor'',pg_get_userbyid(x.grantor),''privilege'',x.privilege_type,''grantable'',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) x),''app_execute'',has_function_privilege(''dyna_app'',p.oid,''EXECUTE'')) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND starts_with(p.proname,''buyer_address_'')),\n ''app_role'',(SELECT jsonb_build_object(''superuser'',r.rolsuper,''inherit'',r.rolinherit,''bypass_rls'',r.rolbypassrls,''create_role'',r.rolcreaterole,''create_db'',r.rolcreatedb,''login'',r.rolcanlogin) FROM pg_roles r WHERE rolname=''dyna_app''),\n ''app_acl'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''select'',has_table_privilege(''dyna_app'',c.oid,''SELECT''),''insert'',has_table_privilege(''dyna_app'',c.oid,''INSERT''),''update'',has_table_privilege(''dyna_app'',c.oid,''UPDATE''),''delete'',has_table_privilege(''dyna_app'',c.oid,''DELETE'')) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''buyer_address_'') AND c.relkind IN(''r'',''p''))\n ) INTO buyer_meta251;\n IF buyer_meta251 IS NULL OR (SELECT count(*) FROM jsonb_array_elements(buyer_meta251->''functions'') f WHERE (f->>''name'',f->>''args'')=(''buyer_address_guards'',''''))<>1 THEN RETURN false;END IF;\n buyer_items251:=''[]''::jsonb;\n FOR buyer_entry251 IN SELECT value FROM jsonb_array_elements(buyer_meta251->''functions'') LOOP\n  IF (buyer_entry251->>''name'',buyer_entry251->>''args'')=(''buyer_address_guards'','''') THEN\n   IF (buyer_entry251-''def'') IS DISTINCT FROM ''{\"acl\":[{\"grantable\":false,\"grantee\":\"postgres\",\"grantor\":\"postgres\",\"privilege\":\"EXECUTE\"}],\"app_execute\":false,\"args\":\"\",\"name\":\"buyer_address_guards\",\"owner\":\"postgres\"}''::jsonb\n   OR replace(buyer_entry251->>''def'',buyer_source251,''\nDECLARE seal buyer_address_manifest%ROWTYPE; basis record; basis_oid oid;owner_name text;\nBEGIN\n IF to_regclass(''''public.buyer_address_manifest'''') IS NULL\n  OR to_regclass(''''public.buyer_address_state'''') IS NULL OR to_regclass(''''public.buyer_address_previews'''') IS NULL\n  OR to_regclass(''''public.buyer_address_receipts'''') IS NULL\n  OR(SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace=''''public''''::regnamespace AND starts_with(relname,''''buyer_address_'''') AND relkind IN(''''r'''',''''p''''))\n   IS DISTINCT FROM ARRAY[''''buyer_address_manifest'''',''''buyer_address_previews'''',''''buyer_address_receipts'''',''''buyer_address_state'''']::text[]\n  OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''''public''''::regnamespace AND starts_with(relname,''''buyer_address_'''') AND relkind IN(''''v'''',''''m'''',''''S'''',''''f''''))\n  OR(SELECT count(*) FROM public.buyer_address_manifest)<>1 THEN RETURN false;END IF;\n SELECT * INTO seal FROM public.buyer_address_manifest;\n IF seal.profile IS DISTINCT FROM ''''delivery-sidecar-managed/v1''''\n  OR seal.fingerprint IS DISTINCT FROM public.buyer_address_fingerprint()\n  OR seal.predecessor_certificates IS DISTINCT FROM public.buyer_address_predecessors() THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM public.migrations WHERE name=''''166_buyer_address_sidecar'''') THEN RETURN true;END IF;\n -- Metadata-only bootstrap limited to this exact owner TX. No global flag.\n basis_oid:=to_regclass(''''pg_temp.buyer_address_install_basis'''');IF basis_oid IS NULL THEN RETURN false;END IF;\n SELECT pg_get_userbyid(relowner) INTO owner_name FROM pg_class WHERE oid=''''public.buyer_address_manifest''''::regclass;\n IF current_user IS DISTINCT FROM owner_name OR session_user IS DISTINCT FROM owner_name\n  OR(SELECT relowner FROM pg_class WHERE oid=basis_oid) IS DISTINCT FROM(SELECT relowner FROM pg_class WHERE oid=''''public.buyer_address_manifest''''::regclass)\n  THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_temp.buyer_address_install_basis)<>1 THEN RETURN false;END IF;\n SELECT * INTO basis FROM pg_temp.buyer_address_install_basis;\n RETURN(basis.root_xid,basis.start_at,basis.backend_pid,basis.owner_name)\n  IS NOT DISTINCT FROM(pg_current_xact_id()::text,transaction_timestamp(),pg_backend_pid(),session_user::text)\n  AND basis.predecessors IS NOT DISTINCT FROM seal.predecessor_certificates;\nEND '') IS DISTINCT FROM convert_from(decode('''',''hex''),''UTF8'') THEN RETURN false;END IF;\n   buyer_entry251:=jsonb_set(buyer_entry251,''{def}'',to_jsonb(convert_from(decode('''',''hex''),''UTF8'')),false);\n  END IF;\n  buyer_items251:=buyer_items251||jsonb_build_array(buyer_entry251);\n END LOOP;\n buyer_meta251:=jsonb_set(buyer_meta251,''{functions}'',buyer_items251,false);\n buyer_fp251:=encode(sha256(convert_to(buyer_meta251::text,''UTF8'')),''hex'');\n IF seal.profile IS DISTINCT FROM ''delivery-sidecar-managed/v1''\n  OR seal.fingerprint IS DISTINCT FROM buyer_fp251\n  OR seal.predecessor_certificates IS DISTINCT FROM predecessors214 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM public.migrations WHERE name=''166_buyer_address_sidecar'') THEN RETURN true;END IF;\n -- Metadata-only bootstrap limited to this exact owner TX. No global flag.\n basis_oid:=to_regclass(''pg_temp.buyer_address_install_basis'');IF basis_oid IS NULL THEN RETURN false;END IF;\n SELECT pg_get_userbyid(relowner) INTO owner_name FROM pg_class WHERE oid=''public.buyer_address_manifest''::regclass;\n IF current_user IS DISTINCT FROM owner_name OR session_user IS DISTINCT FROM owner_name\n  OR(SELECT relowner FROM pg_class WHERE oid=basis_oid) IS DISTINCT FROM(SELECT relowner FROM pg_class WHERE oid=''public.buyer_address_manifest''::regclass)\n  THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_temp.buyer_address_install_basis)<>1 THEN RETURN false;END IF;\n SELECT * INTO basis FROM pg_temp.buyer_address_install_basis;\n RETURN(basis.root_xid,basis.start_at,basis.backend_pid,basis.owner_name)\n  IS NOT DISTINCT FROM(pg_current_xact_id()::text,transaction_timestamp(),pg_backend_pid(),session_user::text)\n  AND basis.predecessors IS NOT DISTINCT FROM seal.predecessor_certificates;\nEND ","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"definition":"CREATE OR REPLACE FUNCTION public.buyer_address_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE seal buyer_address_manifest%ROWTYPE; basis record; basis_oid oid;owner_name text;buyer_meta251 jsonb;buyer_entry251 jsonb;buyer_items251 jsonb;buyer_source251 text;buyer_fp251 text;packing_gate214 jsonb;predecessors214 jsonb;financial214 jsonb;tables214 jsonb;functions214 jsonb;family214 text;financial162219 jsonb;entry219 jsonb;items219 jsonb;source219 text;\nBEGIN\n IF public.order_merge_delivery209_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n IF public.partial_sale204_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n IF to_regclass(''public.buyer_address_manifest'') IS NULL\n  OR to_regclass(''public.buyer_address_state'') IS NULL OR to_regclass(''public.buyer_address_previews'') IS NULL\n  OR to_regclass(''public.buyer_address_receipts'') IS NULL\n  OR(SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''buyer_address_'') AND relkind IN(''r'',''p''))\n   IS DISTINCT FROM ARRAY[''buyer_address_manifest'',''buyer_address_previews'',''buyer_address_receipts'',''buyer_address_state'']::text[]\n  OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''buyer_address_'') AND relkind IN(''v'',''m'',''S'',''f''))\n  OR(SELECT count(*) FROM public.buyer_address_manifest)<>1 THEN RETURN false;END IF;\n SELECT * INTO seal FROM public.buyer_address_manifest;\n -- Exact Source189 representation inverse, never a current IAM substitute.\n SELECT to_jsonb(g) INTO STRICT packing_gate214 FROM (\nWITH expected AS (SELECT * FROM jsonb_to_recordset(''[{\"identity\":\"public.packing_required_field_valid(jsonb,jsonb,jsonb,jsonb,jsonb)\",\"body_sha256\":\"c2782c0a82efed2eb49e97858d963e6e175e40fd8919440a48d2f719ca87c922\",\"returns\":\"boolean\",\"volatility\":\"i\",\"app_execute\":true,\"argument_names\":[\"field_def\",\"field_value\",\"value_revision\",\"field_options\",\"field_file\"]},{\"identity\":\"public.packing_required_fields_snapshot(uuid)\",\"body_sha256\":\"5ad086377c6693e35831c8e5c879475898ab0124d07ebff58f4f1b7c3611f2cd\",\"returns\":\"jsonb\",\"volatility\":\"v\",\"app_execute\":true,\"argument_names\":[\"p_order\"]},{\"identity\":\"public.packing_required_fields_require(uuid)\",\"body_sha256\":\"b74c6e60e55cf08067e27295c437002c87b485c271713520c057dd6f886771c0\",\"returns\":\"void\",\"volatility\":\"v\",\"app_execute\":true,\"argument_names\":[\"p_order\"]},{\"identity\":\"public.packing_required_fields_guard()\",\"body_sha256\":\"291fd1bea4761821c1ecfec33d911cc293b45fddce7ed43c6757ae9330887e2f\",\"returns\":\"trigger\",\"volatility\":\"v\",\"app_execute\":false,\"argument_names\":null}]''::jsonb) e(identity text,body_sha256 text,returns text,volatility text,app_execute boolean,argument_names text[])),\n routines AS (SELECT e.*,p.*,pg_get_userbyid(p.proowner) owner FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.identity))\n SELECT count(*)::int n,count(oid)::int present,coalesce(bool_and(oid IS NOT NULL AND owner=session_user AND prokind=''f'' AND NOT prosecdef AND NOT proisstrict AND NOT proretset AND proparallel=''u''\n AND proargnames IS NOT DISTINCT FROM argument_names AND pronargdefaults=0 AND provariadic=0 AND proargmodes IS NULL AND proallargtypes IS NULL AND prosupport=0 AND probin IS NULL AND prosqlbody IS NULL AND NOT proleakproof AND procost=100 AND prorows=0\n AND provolatile=volatility::\"char\" AND prorettype::regtype::text=returns AND prolang=(SELECT oid FROM pg_language WHERE lanname=''plpgsql'')\n AND proconfig=ARRAY[''search_path=pg_catalog, public'']::text[] AND encode(sha256(convert_to(prosrc,''UTF8'')),''hex'')=body_sha256\n AND (SELECT jsonb_agg(jsonb_build_object(''role'',CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,''privilege'',a.privilege_type,''grantable'',a.is_grantable,''grantor'',pg_get_userbyid(a.grantor)) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee)) FROM aclexplode(CASE WHEN cardinality(coalesce(proacl,acldefault(''f'',proowner)))=0 THEN NULL::aclitem[] ELSE coalesce(proacl,acldefault(''f'',proowner)) END) a)\n =CASE WHEN app_execute THEN jsonb_build_array(jsonb_build_object(''role'',''dyna_app'',''privilege'',''EXECUTE'',''grantable'',false,''grantor'',session_user),jsonb_build_object(''role'',session_user,''privilege'',''EXECUTE'',''grantable'',false,''grantor'',session_user)) ELSE jsonb_build_array(jsonb_build_object(''role'',session_user,''privilege'',''EXECUTE'',''grantable'',false,''grantor'',session_user)) END),false) routines_valid,\n (SELECT count(t.oid)=3 AND bool_and(t.tgenabled=''O'' AND NOT t.tgisinternal AND t.tgparentid=0 AND NOT t.tgdeferrable AND NOT t.tginitdeferred AND t.tgqual IS NULL AND octet_length(t.tgargs)=0\n AND t.tgfoid=to_regprocedure(''public.packing_required_fields_guard()'') AND t.tgtype=own_trigger.kind\n AND (SELECT coalesce(array_agg(a.attname::text ORDER BY a.attnum),''{}''::text[]) FROM pg_attribute a WHERE a.attrelid=t.tgrelid AND a.attnum=ANY(t.tgattr::smallint[]))=own_trigger.columns)\n FROM (VALUES(''packing_required_fields_status'',''public.orders'',19,ARRAY[''status'']::text[]),(''packing_required_fields_preview'',''public.packing_previews'',7,''{}''::text[]),(''packing_required_fields_receipt'',''public.packing_receipts'',7,''{}''::text[])) own_trigger(name,relation,kind,columns)\n LEFT JOIN pg_trigger t ON t.tgname=own_trigger.name AND t.tgrelid=to_regclass(own_trigger.relation)) triggers_valid FROM routines\n ) g;\n IF packing_gate214->>''n'' IS DISTINCT FROM ''4'' OR packing_gate214->>''present'' IS DISTINCT FROM ''4''\n OR packing_gate214->''routines_valid'' IS DISTINCT FROM ''true''::jsonb\n OR packing_gate214->''triggers_valid'' IS DISTINCT FROM ''true''::jsonb THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM (VALUES\n(''158'',''public.fa3_draft_fingerprint()'',''98e864adebce59dc7da7f1e46cecddcf5028bc1de05db5dea1e0d0800ca56a30''),\n(''159'',''public.b2b_invoice_fingerprint