DER BY n.nspname,c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND(starts_with(t.tgname,''manual_inventory_off_'') OR(c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''manual_inventory_off_'')))),\n ''policies'',(SELECT jsonb_agg(jsonb_build_object(''table'',c.relname,''name'',p.polname,''command'',p.polcmd,''permissive'',p.polpermissive,''roles'',(SELECT jsonb_agg(CASE WHEN r=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(r) END ORDER BY CASE WHEN r=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(r) END) FROM unnest(p.polroles) r),''using'',pg_get_expr(p.polqual,p.polrelid),''check'',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY c.relname,p.polname) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''manual_inventory_off_'')),\n ''functions'',(SELECT jsonb_agg(jsonb_build_object(''name'',p.proname,''args'',pg_get_function_identity_arguments(p.oid),''def'',pg_get_functiondef(p.oid),''owner'',pg_get_userbyid(p.proowner),''acl'',(SELECT jsonb_agg(jsonb_build_object(''grantee'',CASE WHEN x.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x.grantee) END,''grantor'',pg_get_userbyid(x.grantor),''privilege'',x.privilege_type,''grantable'',x.is_grantable) ORDER BY x.grantee=0,pg_get_userbyid(x.grantee),pg_get_userbyid(x.grantor),x.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) x),''app_execute'',has_function_privilege(''dyna_app'',p.oid,''EXECUTE'')) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND starts_with(p.proname,''manual_inventory_off_'')),\n ''app_role'',(SELECT jsonb_build_object(''superuser'',r.rolsuper,''inherit'',r.rolinherit,''bypass_rls'',r.rolbypassrls,''create_role'',r.rolcreaterole,''create_db'',r.rolcreatedb,''login'',r.rolcanlogin) FROM pg_roles r WHERE rolname=''dyna_app''),\n ''app_acl'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''select'',has_table_privilege(''dyna_app'',c.oid,''SELECT''),''insert'',has_table_privilege(''dyna_app'',c.oid,''INSERT''),''update'',has_table_privilege(''dyna_app'',c.oid,''UPDATE''),''delete'',has_table_privilege(''dyna_app'',c.oid,''DELETE'')) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND starts_with(c.relname,''manual_inventory_off_'') AND c.relkind IN(''r'',''p''))\n ) INTO manual_meta267;\n IF manual_meta267 IS NULL\n OR (SELECT count(*) FROM jsonb_array_elements(manual_meta267->''functions'') f WHERE (f->>''name'',f->>''args'')=(''manual_inventory_off_valid'',''''))<>1\n OR (SELECT count(*) FROM jsonb_array_elements(manual_meta267->''functions'') f WHERE (f->>''name'',f->>''args'')=(''manual_inventory_off_projection_valid'',''''))<>1 THEN RETURN false;END IF;\n manual_items267:=''[]''::jsonb;\n FOR manual_entry267 IN SELECT value FROM jsonb_array_elements(manual_meta267->''functions'') LOOP\n  IF (manual_entry267->>''name'',manual_entry267->>''args'') IN((''manual_inventory_off_projected_definition'',''fn oid''),(''manual_inventory_off_fingerprint'','''')) THEN\n   manual_entry267:=jsonb_set(manual_entry267,''{def}'',to_jsonb(public.partial_sale204_predecessor_definition(CASE manual_entry267->>''name'' WHEN ''manual_inventory_off_fingerprint'' THEN ''public.manual_inventory_off_fingerprint()''::regprocedure ELSE ''public.manual_inventory_off_projected_definition(oid)''::regprocedure END)),false);\n  ELSIF (manual_entry267->>''name'',manual_entry267->>''args'')=(''manual_inventory_off_valid'','''') THEN\n   SELECT prosrc INTO STRICT manual_source267 FROM pg_proc WHERE oid=''public.manual_inventory_off_valid()''::regprocedure;\n   IF (CASE WHEN ((SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname=''pim_dictionary_function_metadata'')=1 AND EXISTS(SELECT FROM pg_proc q WHERE q.oid=to_regprocedure(''public.pim_dictionary_function_metadata(oid)'') AND q.prosrc=''\n SELECT jsonb_build_object(''''signature'''',p.oid::regprocedure::text,''''definition'''',pg_get_functiondef(p.oid),''''owner'''',pg_get_userbyid(p.proowner),''''language'''',l.lanname,\n ''''volatility'''',p.provolatile,''''strict'''',p.proisstrict,''''leakproof'''',p.proleakproof,''''security_definer'''',p.prosecdef,''''parallel'''',p.proparallel,''''kind'''',p.prokind,''''returns_set'''',p.proretset,\n ''''arguments'''',pg_get_function_identity_arguments(p.oid),''''result'''',pg_get_function_result(p.oid),''''argument_modes'''',p.proargmodes,''''argument_names'''',p.proargnames,\n ''''defaults'''',pg_get_expr(p.proargdefaults,0),''''configuration'''',p.proconfig,''''cost'''',p.procost,''''rows'''',p.prorows,\n ''''acl'''',public.pim_dictionary_acl_metadata(coalesce(p.proacl,acldefault(''''f'''',p.proowner)))) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=function_oid\n'' AND q.proallargtypes IS NULL AND q.protrftypes IS NULL AND q.prosqlbody IS NULL) AND (SELECT jsonb_build_object(''owner'',pg_get_userbyid(q.proowner),''language'',l.lanname,''kind'',q.prokind,''cost'',q.procost,''rows'',q.prorows,''security_definer'',q.prosecdef,''leakproof'',q.proleakproof,''strict'',q.proisstrict,''returns_set'',q.proretset,''volatility'',q.provolatile,''parallel'',q.proparallel,''support'',CASE WHEN q.prosupport=0 THEN NULL ELSE q.prosupport::regprocedure::text END,''variadic'',CASE WHEN q.provariadic=0 THEN NULL ELSE format_type(q.provariadic,NULL) END,''argument_names'',q.proargnames,''argument_modes'',q.proargmodes,''arguments'',pg_get_function_arguments(q.oid),''result'',pg_get_function_result(q.oid),''defaults'',pg_get_expr(q.proargdefaults,0),''binary'',q.probin,''config'',q.proconfig,''acl_null'',q.proacl IS NULL,''acl'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''grantor'',pg_get_userbyid(a.grantor),''grantee'',CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,''privilege'',a.privilege_type,''grantable'',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),''[]''::jsonb) FROM aclexplode(CASE WHEN cardinality(coalesce(q.proacl,acldefault(''f'',q.proowner)))=0 THEN NULL::aclitem[] ELSE coalesce(q.proacl,acldefault(''f'',q.proowner)) END) a)) FROM pg_proc q JOIN pg_namespace n ON n.oid=q.pronamespace JOIN pg_language l ON l.oid=q.prolang WHERE q.oid=to_regprocedure(''public.pim_dictionary_function_metadata(oid)'') AND n.nspname=''public'') IS NOT DISTINCT FROM ''{\"owner\":\"postgres\",\"language\":\"sql\",\"kind\":\"f\",\"cost\":100,\"rows\":0,\"security_definer\":false,\"leakproof\":false,\"strict\":false,\"returns_set\":false,\"volatility\":\"s\",\"parallel\":\"u\",\"support\":null,\"variadic\":null,\"argument_names\":[\"function_oid\"],\"argument_modes\":null,\"arguments\":\"function_oid oid\",\"result\":\"jsonb\",\"defaults\":null,\"binary\":null,\"config\":[\"search_path=pg_catalog, public\"],\"acl_null\":false,\"acl\":[{\"grantor\":\"postgres\",\"grantee\":\"postgres\",\"privilege\":\"EXECUTE\",\"grantable\":false}]}''::jsonb) AND ((SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname=''pim_dictionary_acl_metadata'')=1 AND EXISTS(SELECT FROM pg_proc q WHERE q.oid=to_regprocedure(''public.pim_dictionary_acl_metadata(aclitem[])'') AND q.prosrc=''\n SELECT coalesce(jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''''PUBLIC'''' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)\n ORDER BY pg_get_userbyid(a.grantor)::text,CASE WHEN a.grantee=0 THEN ''''PUBLIC'''' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,a.is_grantable),''''[]''''::jsonb) FROM aclexplode(items) a\n'' AND q.proallargtypes IS NULL AND q.protrftypes IS NULL AND q.prosqlbody IS NULL) AND (SELECT jsonb_build_object(''owner'',pg_get_userbyid(q.proowner),''language'',l.lanname,''