 manual_inventory_off_original152_fingerprint()\n OR cert->''''predecessor_catalog_functions'''' IS DISTINCT FROM manual_inventory_off_catalog_functions(true)\n OR cert->>''''successor_fingerprint'''' IS DISTINCT FROM catalog_stock_control_fingerprint()\n OR cert->>''''own_fingerprint'''' IS DISTINCT FROM manual_inventory_off_fingerprint()\n OR NOT manual_inventory_off_projection_valid()\n OR cert->>''''original160_fingerprint'''' IS DISTINCT FROM b2b_credit_fingerprint() THEN RETURN false;END IF;\n FOR n,v IN SELECT key,value FROM jsonb_each(cert->''''successor_functions'''') LOOP\n SELECT prosrc INTO actual FROM pg_proc WHERE oid=(''''public.''''||n||CASE n WHEN ''''catalog_stock_control_effect_prepare'''' THEN ''''(uuid,uuid,jsonb)'''' WHEN ''''catalog_stock_control_effect_validate'''' THEN ''''(uuid)'''' ELSE ''''()'''' END)::regprocedure;\n IF actual IS DISTINCT FROM v->>''''body'''' THEN RETURN false;END IF;END LOOP;\n IF EXISTS(SELECT FROM migrations WHERE name=''''169_manual_inventory_off'''') THEN RETURN true;END IF;\n IF current_user=ownrole AND session_user=ownrole AND to_regclass(''''pg_temp.manual_inventory_off_install_basis'''') IS NOT NULL THEN\n SELECT EXISTS(SELECT FROM pg_temp.manual_inventory_off_install_basis b WHERE b.owner_name=ownrole AND b.root_xid=pg_current_xact_id()::text AND b.start_at=transaction_timestamp() AND b.backend_pid=pg_backend_pid()\n AND b.original152_manifest=cert->''''original152_manifest'''' AND b.changed_functions=cert->''''predecessor_functions'''') INTO bootstrap;END IF;RETURN bootstrap;\nEXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN RETURN false;END'') IS DISTINCT FROM convert_from(decode('''',''hex''),''UTF8'') THEN RETURN false;END IF;\n   manual_entry267:=jsonb_set(manual_entry267,''{def}'',to_jsonb(convert_from(decode('''',''hex''),''UTF8'')),false);\n  ELSIF (manual_entry267->>''name'',manual_entry267->>''args'')=(''manual_inventory_off_projection_valid'','''') THEN\n   SELECT public.order_merge_delivery209_predecessor_source(oid, merge_delivery209_local_frame) INTO STRICT manual_source267 FROM pg_proc WHERE oid=''public.manual_inventory_off_projection_valid()''::regprocedure;\n   IF (CASE WHEN ((SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname=''pim_dictionary_function_metadata'')=1 AND EXISTS(SELECT FROM pg_proc q WHERE q.oid=to_regprocedure(''public.pim_dictionary_function_metadata(oid)'') AND public.order_merge_delivery209_predecessor_source(q.oid, merge_delivery209_local_frame)=''\n SELECT jsonb_build_object(''''signature'''',p.oid::regprocedure::text,''''definition'''',pg_get_functiondef(p.oid),''''owner'''',pg_get_userbyid(p.proowner),''''language'''',l.lanname,\n ''''volatility'''',p.provolatile,''''strict'''',p.proisstrict,''''leakproof'''',p.proleakproof,''''security_definer'''',p.prosecdef,''''parallel'''',p.proparallel,''''kind'''',p.prokind,''''returns_set'''',p.proretset,\n ''''arguments'''',pg_get_function_identity_arguments(p.oid),''''result'''',pg_get_function_result(p.oid),''''argument_modes'''',p.proargmodes,''''argument_names'''',p.proargnames,\n ''''defaults'''',pg_get_expr(p.proargdefaults,0),''''configuration'''',p.proconfig,''''cost'''',p.procost,''''rows'''',p.prorows,\n ''''acl'''',public.pim_dictionary_acl_metadata(coalesce(p.proacl,acldefault(''''f'''',p.proowner)))) FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=function_oid\n'' AND q.proallargtypes IS NULL AND q.protrftypes IS NULL AND q.prosqlbody IS NULL) AND (SELECT jsonb_build_object(''owner'',pg_get_userbyid(q.proowner),''language'',l.lanname,''kind'',q.prokind,''cost'',q.procost,''rows'',q.prorows,''security_definer'',q.prosecdef,''leakproof'',q.proleakproof,''strict'',q.proisstrict,''returns_set'',q.proretset,''volatility'',q.provolatile,''parallel'',q.proparallel,''support'',CASE WHEN q.prosupport=0 THEN NULL ELSE q.prosupport::regprocedure::text END,''variadic'',CASE WHEN q.provariadic=0 THEN NULL ELSE 