ata_after#>''{operative,functions}'') WHERE value->>''name''=''operative_delivery_valid'' AND value->>''args''='''')<>1 THEN RETURN false;END IF;\n items189:=''[]'';\n FOR entry189 IN SELECT value FROM jsonb_array_elements(operative189->''functions'') LOOP\n  IF entry189->>''name''=''operative_delivery_valid'' AND entry189->>''args''='''' THEN\n   SELECT value INTO STRICT old_entry189 FROM jsonb_array_elements(c.metadata_after#>''{operative,functions}'') WHERE value->>''name''=''operative_delivery_valid'' AND value->>''args''='''';\n   IF (entry189-''def'') IS DISTINCT FROM (old_entry189-''def'')\n   OR position(leaf_sha IN entry189->>''def'')=0\n   OR replace(entry189->>''def'',leaf_sha,''cd77c1cd4b1b4be9d8fbfb1b225299508f9724cc552cb045f5ba710cc84fd666'') IS DISTINCT FROM old_entry189->>''def'' THEN RETURN false;END IF;\n   entry189:=old_entry189;\n  END IF;items189:=items189||jsonb_build_array(entry189);\n END LOOP;operative189:=jsonb_set(operative189,''{functions}'',items189);\n PERFORM public.wave_print177_project_operative(operative189,c.operative_before,c.functions_before);\n RETURN public.wave_print177_history_nested172_valid() IS TRUE AND public.wave_print177_history_operative_delivery_valid() IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND\n$old204$;\n ELSE RAISE EXCEPTION ''204 exact scoped signature required'' USING ERRCODE=''55000'';\n END CASE;\n SELECT jsonb_build_object(''owner'',pg_get_userbyid(q.proowner),''language'',l.lanname,''kind'',q.prokind,''cost'',q.procost,''rows'',q.prorows,''security_definer'',q.prosecdef,''leakproof'',q.proleakproof,''strict'',q.proisstrict,''returns_set'',q.proretset,''volatility'',q.provolatile,''parallel'',q.proparallel,''support'',CASE WHEN q.prosupport=0 THEN NULL ELSE q.prosupport::regprocedure::text END,''variadic'',CASE WHEN q.provariadic=0 THEN NULL ELSE format_type(q.provariadic,NULL) END,''argument_names'',q.proargnames,''argument_modes'',q.proargmodes,''arguments'',pg_get_function_arguments(q.oid),''result'',pg_get_function_result(q.oid),''defaults'',pg_get_expr(q.proargdefaults,0),''binary'',q.probin,''config'',q.proconfig,''acl_null'',q.proacl IS NULL,''acl'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''grantor'',pg_get_userbyid(a.grantor),''grantee'',CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,''privilege'',a.privilege_type,''grantable'',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),''[]''::jsonb) FROM aclexplode(CASE WHEN cardinality(coalesce(q.proacl,acldefault(''f'',q.proowner)))=0 THEN NULL::aclitem[] ELSE coalesce(q.proacl,acldefault(''f'',q.proowner)) END) a)) INTO actual FROM pg_proc q JOIN pg_namespace n ON n.oid=q.pronamespace JOIN pg_language l ON l.oid=q.prolang WHERE q.oid=fn AND n.nspname=''public'';\n IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION ''204 exact scoped header and ACL required'' USING ERRCODE=''55000'';END IF;\n RETURN replace(public.order_merge_delivery209_predecessor_definition(fn, merge_delivery209_local_frame),public.order_merge_delivery209_predecessor_source(p.oid, merge_delivery209_local_frame),original);\nEND","binary":null,"config":["search_path=pg_catalog, public"],"definition":"CREATE OR REPLACE FUNCTION public.partial_sale204_predecessor_definition(fn oid)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$DECLARE merge_delivery209_local_frame jsonb; p pg_proc;original text;expected jsonb;actual jsonb;BEGIN\n IF fn=ANY(ARRAY[''public.buyer_address_preview_guard()''::regprocedure,''public.buyer_address_state_guard()''::regprocedure,''public.buyer_address_guards()''::regprocedure,''public.buyer_address_fingerprint()''::regprocedure,''public.manual_inventory_off_valid()''::regprocedure,''public.manual_inventory_off_projection_valid()''::regprocedure,''public.partial_sale204_predecessor_definition(oid)''::regprocedure,''public.ordinary187_valid()''::regprocedure,''public.partial_sale204_valid()''::regprocedure,''public.catalog_header205_valid()''::regprocedure,''public.pim_dictionary_valid()''::regprocedure,''public.nested172_valid()''::regprocedure,''public.parcel_physical_wz_valid()''::regprocedure,''public.operative_delivery_valid()''::regprocedure,''public.wave_print177_valid()''::regprocedure,''public.cooperation171_valid()''::regprocedure,''public.packed_label_print_guards()''::regprocedure]::oid[]) THEN merge_delivery209_local_frame:=public.order_merge_delivery209_checked_projection_map(fn); ELSE merge_delivery209_local_frame:=NULL;END IF;\n IF fn NOT IN(''public.local_invoice_frame(uuid,uuid,integer,jsonb,text)''::regprocedure,''public.local_invoice_fingerprint()''::regprocedure,''public.fa3_draft_fingerprint()''::regprocedure,''public.b2b_invoice_fingerprint()''::regprocedure,''public.manual_inventory_off_projected_definition(oid)''::regprocedure,''public.manual_inventory_off_fingerprint()''::regprocedure,''public.manual_inventory_off_valid()''::regprocedure,''public.manual_inventory_off_projection_valid()''::regprocedure,''public.pim_dictionary_valid()''::regprocedure,''public.cooperation171_valid()''::regprocedure,''public.parcel_physical_wz_valid()''::regprocedure,''public.operative_delivery_valid()''::regprocedure,''public.nested172_valid()''::regprocedure,''public.packed_label_print_guards()''::regprocedure,''public.financial_return_upgrade_valid()''::regprocedure,''public.buyer_address_guards()''::regprocedure,''public.wave_print177_history_operative_delivery_valid()''::regprocedure,''public.ordinary181_history_operative_valid(jsonb)''::regprocedure,''public.ordinary181_financial_valid(jsonb)''::regprocedure,''public.ordinary181_buyer_guards(jsonb)''::regprocedure,''public.financial_return_fingerprint()''::regprocedure,''public.buyer_address_fingerprint()''::regprocedure,''public.wave_print177_valid()''::regprocedure) THEN RETURN public.order_merge_delivery209_predecessor_definition(fn, merge_delivery209_local_frame);END IF;\n SELECT * INTO STRICT p FROM pg_proc WHERE oid=fn;\n IF p.proallargtypes IS NOT NULL OR p.protrftypes IS NOT NULL OR p.prosqlbody IS NOT NULL OR (SELECT count(*) FROM pg_proc q WHERE q.pronamespace=''public''::regnamespace AND q.proname=p.proname)<>1 THEN RAISE EXCEPTION ''204 exact scoped descriptor required'' USING ERRCODE=''55000'';END IF;\n CASE fn\n WHEN ''public.local_invoice_frame(uuid,uuid,integer,jsonb,text)''::regprocedure THEN\n IF public.order_merge_delivery209_predecessor_source(p.oid, merge_delivery209_local_frame) IS NULL OR octet_length(public.order_merge_delivery209_predecessor_source(p.oid, merge_delivery209_local_frame)) IS DISTINCT FROM 7334 OR public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_local_frame) IS DISTINCT FROM ''9a6a81cf52e2c090855a1cde8ec4d13b2f5f7d808e0cce61b1b15835bb00f493'' THEN RAISE EXCEPTION ''204 changed body drift'' USING ERRCODE=''55000'';END IF;\n expected:=''{\"owner\":\"postgres\",\"language\":\"plpgsql\",\"kind\":\"f\",\"cost\":100,\"rows\":0,\"security_definer\":true,\"leakproof\":false,\"strict\":false,\"returns_set\":false,\"volatility\":\"v\",\"parallel\":\"u\",\"support\":null,\"variadic\":null,\"argument_names\":[\"oid\",\"sid\",\"shipping_vat\",\"bill_to\",\"sale_date\"],\"argument_modes\":null,\"arguments\":\"oid uuid, sid uuid, shipping_vat integer, bill_to jsonb, sale_date text\",\"result\":\"jsonb\",\"defaults\":null,\"binary\":null,\"config\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"acl_null\":false,\"acl\":[{\"grantor\":\"postgres\",\"grantee\":\"postgres\",\"privilege\":\"EXECUTE\",\"grantable\":false}]}''::jsonb;\n original:=$old204$\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;o orders%ROWTYPE;s local_invoice_series%ROWTYPE;i record;lines jsonb:=''[]'';gross bigint;net bigint;sumgross bigint:=0;sumnet bigint:=0;issuedate date:=(clock_timestamp() AT TIME ZONE ''UTC'')::date;buyer_address jsonb;taxes jsonb;vat bigint;BEGIN\n SELECT * INTO o FROM orders WHERE(tenant_id,id)=(t,oid) FOR UPDATE;\n IF o.id IS NULL THEN RAISE EXCEPTION ''Nie znaleziono własnego zamówienia'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO s FROM local_invoice_series WHERE(tenant_id,id)=(t,sid) FOR UPDATE;\n IF s.id IS NULL THEN RAISE EXCEPTION ''Nie znaleziono własnej serii faktur'' USING ERRCODE=''P0002'';END IF;\n IF o.fulfillment_kind IS DISTINCT FROM ''sale'' OR o.status NOT IN(''shipped'',''delivered'')\n OR EXISTS(SELECT 1 FROM order_merge_claims mc WHERE(mc.tenant_id,mc.source_order_id)=(t,oid))\n OR EXISTS(SELECT 1 FROM return_cases rc WHERE(rc.tenant_id,rc.order_id)=(t,oid))\n OR EXISTS(SELECT 1 FROM documents d WHERE(d.tenant_id,d.order_id,d.kind)=(t,oid,''correction'')) THEN RAISE EXCEPTION ''Zamówienie nie jest obsługiwaną sprzedażą dla faktury'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT 1 FROM invoice_plans ip WHERE(ip.tenant_id,ip.order_id)=(t,oid) AND ip.kind=''invoice'' AND ip.mode=''external'' AND ip.state NOT IN(''preview'',''cancelled'')) OR EXISTS(SELECT 1 FROM odoo_invoice_exports ox WHERE(ox.tenant_id,ox.order_id)=(t,oid) AND ox.mode=''external'' AND ox.state NOT IN(''preview'',''cancelled'')) OR EXISTS(SELECT 1 FROM documents dx WHERE(dx.tenant_id,dx.order_id,dx.kind)=(t,oid,''invoice'') AND dx.mode=''external'') THEN RAISE EXCEPTION ''Zamówienie ma zewnętrzną fakturę lub zatwierdzony plan'' USING ERRCODE=''23514'';END IF;\n IF o.source=''b2b'' OR EXISTS(SELECT 1 FROM b2b_dropship_orders b WHERE(b.tenant_id,b.customer_order_id)=(t,oid) OR(b.supplier_tenant_id,b.supplier_order_id)=(t,oid)) THEN RAISE EXCEPTION ''Faktura B2B wymaga osobnego potwierdzenia bill-to'' USING ERRCODE=''23514'';END IF;\n IF o.currency<>''PLN'' OR shipping_vat IS NULL OR shipping_vat NOT IN(0,5,8,23) OR o.shipping_cost<0 OR o.total<0 THEN RAISE EXCEPTION ''Niepoprawne pieniądze faktury'' USING ERRCODE=''23514'';END IF;\n IF (jsonb_typeof(bill_to)=''object'' AND bill_to-ARRAY[''kind'',''name'',''street'',''postal_code'',''city'',''country'']=''{}'' AND bill_to->>''kind''=''consumer''\n AND local_invoice_text(bill_to->''name'',1,200) AND local_invoice_text(bill_to->''street'',1,200) AND local_invoice_text(bill_to->''postal_code'',1,30) AND local_invoice_text(bill_to->''city'',1,100) AND bill_to->>''country''=''PL'') IS NOT TRUE\n OR o.address->>''country'' IS DISTINCT FROM ''PL'' OR sale_date IS NULL OR sale_date!~''^[0-9]{4}-[0-9]{2}-[0-9]{2}$'' THEN RAISE EXCEPTION ''Obsługujemy wyłącznie pełne dane konsumenta i sprzedaż krajową PL'' USING ERRCODE=''22023'';END IF;\n IF sale_date::date>issuedate OR sale_date::date<(o.created_at AT TIME ZONE ''UTC'')::date THEN RAISE EXCEPTION ''Potwierdź rzeczywistą datę sprzedaży między zamówieniem a wystawieniem'' USING ERRCODE=''22023'';END IF;\n buyer_address:=bill_to-ARRAY[''kind'',''name''];\n IF(SELECT count(*) FROM order_items WHERE(tenant_id,order_id)=(t,oid)) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION ''Niepełne pozycje faktury'' USING ERRCODE=''23514'';END IF;\n PERFORM id FROM order_items WHERE(tenant_id,order_id)=(t,oid) ORDER BY id FOR SHARE;\n FOR i IN SELECT * FROM order_items WHERE(tenant_id,order_id)=(t,oid) ORDER BY id LOOP\n IF i.quantity<=0 OR i.price<0 OR i.vat NOT IN(0,5,8,23) OR i.line_total IS NULL OR i.line_total<0 OR i.line_total::bigint-i.price::bigint*i.quantity::bigint>=i.quantity::bigint THEN RAISE EXCEPTION ''Historyczna pozycja ma niespójne kwoty'' USING ERRCODE=''23514'';END IF;\n gross:=i.line_total;vat:=floor((2::numeric*gross*i.vat+(100+i.vat))/(2*(100+i.vat)))::bigint;net:=gross-vat;\n lines:=lines||jsonb_build_array(jsonb_build_object(''kind'',''item'',''item_id'',i.id,''product_id'',i.product_id,''sku'',i.sku,''name'',i.name,''quantity'',i.quantity,''unit'',''szt.'',''unit_gross_minor'',i.price::text,''discount_gross_minor'',greatest(i.price::bigint*i.quantity::bigint-gross,0)::text,''rounding_gross_minor'',greatest(gross-i.price::bigint*i.quantity::bigint,0)::text,''vat_rate'',i.vat,''gross_minor'',gross::text,''net_minor'',net::text,''vat_minor'',(gross-net)::text));\n sumgross:=sumgross+gross;sumnet:=sumnet+net;\n END LOOP;\n gross:=o.shipping_cost;vat:=floor((2::numeric*gross*shipping_vat+(100+shipping_vat))/(2*(100+shipping_vat)))::bigint;net:=gross-vat;\n lines:=lines||jsonb_build_array(jsonb_build_object(''kind'',''shipping'',''item_id'',NULL,''product_id'',NULL,''sku'','''',''name'',''Dostawa'',''quantity'',1,''unit'',''usł.'',''unit_gross_minor'',gross::text,''discount_gross_minor'',''0'',''rounding_gross_minor'',''0'',''vat_rate'',shipping_vat,''gross_minor'',gross::text,''net_minor'',net::text,''vat_minor'',(gross-net)::text));\n sumgross:=sumgross+gross;sumnet:=sumnet+net;\n IF sumgross IS DISTINCT FROM o.total::bigint THEN RAISE EXCEPTION ''Pozycje faktury nie sumują się do zamówienia'' USING ERRCODE=''23514'';END IF;\n SELECT jsonb_agg(jsonb_build_object(''vat_rate'',rate,''gross_minor'',g::text,''net_minor'',n::text,''vat_minor'',v::text) ORDER BY rate) INTO taxes FROM(SELECT (val->>''vat_rate'')::integer rate,sum((val->>''gross_minor'')::bigint) g,sum((val->>''net_minor'')::bigint) n,sum((val->>''vat_minor'')::bigint) v FROM jsonb_array_elements(lines) a(val) GROUP BY (val->>''vat_rate'')::integer) totals;\n RETURN jsonb_build_object(''order'',jsonb_build_object(''id'',o.id,''number'',o.number,''version'',o.version::text,''status'',o.status,''currency'',o.currency,''total_minor'',o.total::text,''shipping_cost_minor'',o.shipping_cost::text,''payment_mode'',o.payment_mode),\n ''seller'',s.definition->''seller'',''buyer'',jsonb_build_object(''kind'',''consumer'',''tax_id'','''',''name'',bill_to->>''name'',''email'',o.email,''address'',buyer_address),\n ''series'',jsonb_build_object(''id'',s.id,''name'',s.name,''prefix'',s.prefix,''payment_terms_days'',s.definition->''payment_terms_days'',''payment_instructions'',s.definition->''payment_instructions'',''notes'',s.definition->''notes