blob_id=NEW.blob_id;\\n  IF NEW.offset_bytes<>n OR n+NEW.byte_count>b.max_bytes THEN RAISE EXCEPTION ''''Raw part is not contiguous/bounded'''' USING ERRCODE=''''23514'''';END IF;\\n ELSE\\n  j:=NEW.batch_text::jsonb;IF jsonb_typeof(j) IS DISTINCT FROM ''''object'''' OR j->>''''schema'''' IS DISTINCT FROM ''''large-core-import-parser-batch/v1'''' OR j->''''provisional'''' IS DISTINCT FROM ''''true''''::jsonb OR jsonb_typeof(j->''''index'''') IS DISTINCT FROM ''''number'''' OR (j->>''''index'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (j->>''''index'''')::integer IS DISTINCT FROM NEW.index OR j->>''''id'''' IS DISTINCT FROM NEW.id OR jsonb_typeof(j->''''normalized_bytes'''') IS DISTINCT FROM ''''number'''' OR (j->>''''normalized_bytes'''') !~ ''''^[1-9][0-9]*$'''' OR (j->>''''normalized_bytes'''')::bigint NOT BETWEEN 1 AND 2097152 OR jsonb_typeof(j->''''records'''') IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''Parser batch differs'''' USING ERRCODE=''''23514'''';END IF;\\n  IF (SELECT count(*) FROM jsonb_object_keys(j))<>6 OR EXISTS(SELECT 1 FROM jsonb_object_keys(j) x WHERE x<>ALL(ARRAY[''''schema'''',''''provisional'''',''''index'''',''''id'''',''''normalized_bytes'''',''''records''''])) OR jsonb_array_length(j->''''records'''') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION ''''Invalid parser batch shape'''' USING ERRCODE=''''23514'''';END IF;\\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE jsonb_typeof(r) IS DISTINCT FROM ''''object'''' OR jsonb_typeof(r->''''span'''') IS DISTINCT FROM ''''object'''' OR jsonb_typeof(r->''''data'''') IS DISTINCT FROM ''''object'''') THEN RAISE EXCEPTION ''''Parser record requires span and data'''' USING ERRCODE=''''23514'''';END IF;\\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE (SELECT count(*) FROM jsonb_object_keys(r))<>2 OR NOT (r ?& ARRAY[''''span'''',''''data'''']) OR (SELECT count(*) FROM jsonb_object_keys(r->''''span''''))<>6 OR NOT (r->''''span'''' ?& ARRAY[''''ordinal'''',''''byte_start'''',''''byte_end'''',''''line_start'''',''''line_end'''',''''raw_sha256'''']) OR jsonb_typeof(r->''''span''''->''''ordinal'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''byte_start'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''byte_end'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''line_start'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''line_end'''') IS DISTINCT FROM ''''number'''' OR jsonb_typeof(r->''''span''''->''''raw_sha256'''') IS DISTINCT FROM ''''string'''' OR (r#>>''''{span,raw_sha256}'''') !~ ''''^[a-f0-9]{64}$'''') THEN RAISE EXCEPTION ''''Invalid parser span shape'''' USING ERRCODE=''''23514'''';END IF;\\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(j->''''records'''') r WHERE (r#>>''''{span,ordinal}'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (r#>>''''{span,byte_start}'''') !~ ''''^(0|[1-9][0-9]*)$'''' OR (r#>>''''{span,byte_end}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,line_start}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,line_end}'''') !~ ''''^[1-9][0-9]*$'''' OR (r#>>''''{span,byte_start}'''')::bigint>=(r#>>''''{span,byte_end}'''')::bigint OR (r#>>''''{span,byte_end}'''')::bigint>30000000 OR (r#>>''''{span,line_start}'''')::bigint>(r#>>''''{span,line_end}'''')::bigint) THEN RAISE EXCEPTION ''''Parser span must use bounded integer positions'''' USING ERRCODE=''''23514'''';END IF;\\n END IF;RETURN NEW;\\nEND $function$\\n\",\"volatility\":\"v\",\"body_sha256\":\"77510cea0885ecdda464224dfcccfeb657c79def3cdf6fab58537764c5a68aaa\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\"],\"argument_modes\":null,\"argument_names\":null,\"security_definer\":false},{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"trigger\",\"strict\":false,\"defaults\":null,\"language\":\"plpgsql\",\"parallel\":\"u\",\"arguments\":\"