 p.oid=to_regprocedure(''public.ordinary187_approve(text,text,text)'') AND (SELECT count(*) FROM pg_proc sibling WHERE sibling.pronamespace=p.pronamespace AND sibling.proname=p.proname)=1 AND encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex'')=''488178531c4bc3c18e5e7e9c81bb541d63493471bf4417afb3610a39944f3afc'' AND pg_get_function_identity_arguments(p.oid)=''release_sha text, native_sha text, profile_sha text'' AND pg_get_function_result(p.oid)=''jsonb'' AND l.lanname=''plpgsql'' AND pg_get_userbyid(p.proowner)=''postgres'' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel=''u'' AND p.prokind=''f'' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile=''v'' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM ARRAY[''release_sha'',''native_sha'',''profile_sha'']::text[] AND p.proconfig=ARRAY[''search_path=pg_catalog, public'',''TimeZone=UTC'']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a)=''[[\"postgres\",\"postgres\",\"EXECUTE\",false]]''::jsonb AND p.provariadic=0 AND p.prosupport=0 AND p.probin IS NULL AND p.prosqlbody IS NULL AND p.proallargtypes IS NULL AND p.protrftypes IS NULL) THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.ordinary187_private_valid()'') AND (SELECT count(*) FROM pg_proc sibling WHERE sibling.pronamespace=p.pronamespace AND sibling.proname=p.proname)=1 AND encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex'')=''0a0ded2656c3f771c08f7ff9080166f5db3a5cd2151dd7930e1a9ea66a5530b1'' AND pg_get_function_identity_arguments(p.oid)='''' AND pg_get_fun