rch_path TO ''''pg_catalog'''', ''''public''''\\n SET \\\"TimeZone\\\" TO ''''UTC''''\\nAS $function$\\nDECLARE j public.large_import_jobs173%ROWTYPE; old_review public.large_import_core_reviews173%ROWTYPE;\\n state jsonb; r jsonb; b jsonb; c jsonb; page jsonb; resolution jsonb; row_json jsonb; native_row jsonb;\\n canonical_scope text; projection jsonb; projected_batches jsonb:=''''[]''''::jsonb; actual_rows jsonb; request_text text; rows_text text;\\n p public.catalog_file_import_previews%ROWTYPE; nr public.catalog_file_import_rows%ROWTYPE;\\n n integer:=0; page_no integer; count_rows integer; total_rows integer:=0;\\n lock_key bigint; ref jsonb; ids uuid[]:=ARRAY[]::uuid[]; batches integer[]:=ARRAY[]::integer[];\\n links jsonb:=''''[]''''::jsonb; target uuid; old_revision bigint;\\nBEGIN\\n IF TG_OP<>''''INSERT'''' THEN RAISE EXCEPTION ''''CoreReview history is append only'''' USING ERRCODE=''''23514''''; END IF;\\n -- SECURITY DEFINER is solely for trigger-local reads/private predicates; no callable app EXECUTE grants.\\n -- This role/tenant evidence is not a genuine current Actor/session/IAM substitute.\\n IF NOT (current_setting(''''role'''',true)=''''dyna_app'''' OR current_setting(''''role'''',true)=''''none'''' AND session_user=''''dyna_app'''')\\n OR nullif(current_setting(''''app.tenant_id'''',true),'''''''')::uuid IS DISTINCT FROM NEW.tenant_id\\n THEN RAISE EXCEPTION ''''CoreReview requires native app role and tenant'''' USING ERRCODE=''''42501''''; END IF;\\n lock_key:=hashtextextended(''''large-import173:''''||NEW.tenant_id::text||'''':''''||NEW.job_id::text,0);\\n IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.locktype=''''advisory''''\\n AND l.pid=pg_backend_pid() AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())\\n AND l.mode=''''ExclusiveLock'''' AND l.granted IS TRUE AND l.objsubid=1\\n AND l.classid::bigint=((lock_key>>32)&4294967295::bigint) AND l.objid::bigint=(lock_key&4294967295::bigint))\\n THEN RAISE EXCEPTION ''''CoreReview requires exact owned Job advisory key'''' USING ERRCODE=''''23514''''; END IF;\\n SELECT * INTO STRICT j FROM public.large_import_jobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.job_id FOR UPDATE;\\n IF j.actor_id IS DISTINCT FROM NEW.actor_id OR j.api_key_id IS DISTINCT FROM NEW.api_key_id\\n OR j.revision IS DISTINCT FROM NEW.job_revision OR j.lease_fence IS DISTINCT FROM NEW.lease_fence\\n OR j.lease_token IS NULL OR j.leased_at IS NULL\\n THEN RAISE EXCEPTION ''''CoreReview current Job owner/revision/fence differs'''' USING ERRCODE=''''23514''''; END IF;\\n -- lease_token comparison against the private caller token is additionally enforced by the same-client adapter.\\n -- No token is stored in immutable review evidence; actor/API-key presence is not authenticated authority.\\n state:=j.state_text::jsonb; r:=NEW.review_text::jsonb;\\n IF public.large_import_core_review173_keys(r,ARRAY[''''schema'''',''''revision'''',''''source_plan_hash'''',''''raw'''',''''parsing_spec'''',''''batches'''',''''aggregate_scope_hash'''',''''approved_scope_hash'''']) IS DISTINCT FROM true\\n OR r->>''''schema'''' IS DISTINCT FROM ''''large-import-core-review/v1''''\\n OR jsonb_typeof(r->''''revision'''') IS DISTINCT FROM ''''number'''' OR (r->>''''revision'''') !~ ''''^(0|[1-9][0-9]*)$''''\\n OR (r->>''''revision'''')::numeric IS DISTINCT FROM NEW.revision::numeric\\n OR r->>''''source_plan_hash'''' IS DISTINCT FROM j.plan_hash OR public.large_import_core_review173_ref(r->''''raw'''') IS DISTINCT FROM true OR r->''''raw'''' IS DISTINCT FROM state->''''raw''''\\n OR r->''''parsing_spec'''' IS DISTINCT FROM state->''''parsing_spec'''' OR state->''''approved'''' IS DISTINCT FROM ''''true''''::jsonb\\n OR jsonb_typeof(r->''''batches'''') IS DISTINCT FROM ''''array''''\\n OR jsonb_array_length(r->''''batches'''') IS DISTINCT FROM jsonb_array_length(state->''''core'''') OR jsonb_array_length(r->''''batches'''')=0\\n OR r->>''''aggregate_scope_hash'''' IS DISTINCT FROM NEW.aggregate_scope_hash\\n OR r->''''approved_scope_hash'''' IS DISTINCT FROM coalesce(to_jsonb(NEW.approved_scope_hash),''''null''''::jsonb)\\n OR jsonb_array_length(NEW.request_texts) IS DISTINCT FROM jsonb_array_length(r->''''batches'''')\\n OR jsonb_array_length(NEW.row_texts) IS DISTINCT FROM jsonb_array_length(r->''''batches'''')\\n THEN RAISE EXCEPTION ''''CoreReview closed envelope/Job scope differs'''' USING ERRCODE=''''23514''''; END IF;\\n FOR b IN SELECT value FROM jsonb_array_elements(r->''''batches'''') LOOP\\n  c:=state->''''core''''->n;\\n  IF public.large_import_core_review173_keys(b,ARRAY[''''index'''',''''preview_id'''',''''scope_hash'''',''''preview_key'''',''''execute_key'''',''''request_hash'''',''''rows_hash'''',''''resolution'''',''''eligibility'''',''''preview'''']) IS DISTINCT FROM true\\n  OR b->''''index'''' IS DISTINCT FROM to_jsonb(n)\\n  OR b->>''''preview_id'''' IS DISTINCT FROM c#>>''''{preview,ack,head,id}''''\\n  OR b->>''''scope_hash'''' IS DISTINCT FROM c#>>''''{preview,ack,head,scope_hash}''''\\n  OR b->>''''preview_key'''' IS DISTINCT FROM c->>''''previewKey'''' OR b->>''''execute_key'''' IS DISTINCT FROM c->>''''executeKey''''\\n  OR jsonb_typeof(b->''''request_hash'''') IS DISTINCT FROM ''''string'''' OR (b->>''''request_hash'''') !~ ''''^[a-f0-9]{64}$''''\\n  OR jsonb_typeof(b->''''rows_hash'''') IS DISTINCT FROM ''''string'''' OR (b->>''''rows_hash'''') !~ ''''^[a-f0-9]{64}$''''\\n  OR public.large_import_core_review173_keys(b#>''''{preview,ack}'''',ARRAY[''''head'''',''''witness'''',''''reused'''']) IS DISTINCT FROM true\\n  OR public.large_import_core_review173_ref(b#>''''{preview,ack,witness}'''') IS DISTINCT FROM true\\n  OR jsonb_typeof(b#>''''{preview,ack,reused}'''') IS DISTINCT FROM ''''boolean''''\\n  OR public.large_import_core_review173_keys(b->''''preview'''',ARRAY[''''ack'''',''''pages'''']) IS DISTINCT FROM true\\n  OR b#>''''{preview,ack}'''' IS DISTINCT FROM c#>''''{preview,ack}''''\\n  OR jsonb_typeof(b#>''''{preview,pages}'''') IS DISTINCT FROM ''''array''''\\n  OR jsonb_array_length(b#>''''{preview,pages}'''') NOT BETWEEN 1 AND 5\\n  OR jsonb_typeof(b->''''resolution'''') IS DISTINCT FROM ''''array''''\\n  THEN RAISE EXCEPTION ''''CoreReview batch/native keys differ'''' USING ERRCODE=''''23514''''; END IF;\\n  IF jsonb_typeof(NEW.request_texts->n) IS DISTINCT FROM ''''string'''' OR jsonb_typeof(NEW.row_texts->n) IS DISTINCT FROM ''''string''''\\n  THEN RAISE EXCEPTION ''''CoreReview exact digest texts are required'''' USING ERRCODE=''''23514''''; END IF;\\n  request_text:=NEW.request_texts->>n; rows_text:=NEW.row_texts->>n;\\n  IF encode(sha256(convert_to(request_text,''''UTF8'''')),''''hex'''') IS DISTINCT FROM b->>''''request_hash''''\\n  OR request_text::jsonb IS DISTINCT FROM c->''''request''''\\n  OR encode(sha256(convert_to(rows_text,''''UTF8'''')),''''hex'''') IS DISTINCT FROM b->>''''rows_hash''''\\n  THEN RAISE EXCEPTION ''''CoreReview exact text digests differ'''' USING ERRCODE=''''23514''''; END IF;\\n  SELECT * INTO STRICT p FROM public.catalog_file_import_previews WHERE tenant_id=NEW.tenant_id AND id=(b->>''''preview_id'''')::uuid;\\n  IF p.actor_id IS DISTINCT FROM NEW.actor_id OR p.client_key IS DISTINCT FROM (b->>''''preview_key'''')::uuid\\n  OR p.scope_hash IS DISTINCT FROM b->>''''scope_hash'''' OR p.ready IS DISTINCT FROM true\\n  OR p.config IS DISTINCT FROM ((c->''''request'''')-ARRAY[''''content'''',''''client_key''''])\\n  OR p.source IS DISTINCT FROM (CASE WHEN NEW.api_key_id IS NULL THEN ''''manual'''' ELSE ''''api'''' END)\\n  OR (b#>''''{preview,ack,head}'''') IS DISTINCT FROM jsonb_build_object(''''id'''',p.id,''''actor_id'''',p.actor_id,''''scope_hash'''',p.scope_hash,\\n    ''''total'''',p.total,''''created'''',p.created,''''updated'''',p.updated,''''unchanged'''',p.unchanged,''''invalid'''',p.invalid,''''ready'''',p.ready,\\n    ''''created_at'''',b#>''''{preview,ack,head,created_at}'''',''''config'''',p.config,''''active_product_rules'''',jsonb_array_length(p.rules_snapshot))\\n  -- The existing HTTP pg Date projection is millisecond precision; preserve native UTC timestamp separately.\\n  OR jsonb_typeof(b#>''''{preview,ack,head,created_at}'''') IS DISTINCT FROM ''''string''''\\n  OR (b#>>''''{preview,ack,head,created_at}'''')::timestamptz IS DISTINCT FROM date_trunc(''''milliseconds'''',p.created_at)\\n  OR (SELECT count(*) FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id)<>p.total\\n  THEN RAISE EXCEPTION ''''CoreReview actual native preview differs'''' USING ERRCODE=''''23514''''; END IF;\\n  SELECT jsonb_agg((to_jsonb(x)-ARRAY[''''tenant_id'''',''''preview_id'''',''''byte_count''''])||jsonb_build_object(''''changes'''',x.input) ORDER BY x.index)\\n  INTO actual_rows FROM public.catalog_file_import_rows x WHERE x.tenant_id=NEW.tenant_id AND x.preview_id=p.id;\\n  IF rows_text::jsonb IS DISTINCT FROM actual_rows\\n  OR (SELECT jsonb_agg(rr.v ORDER BY pg.page_ord,rr.ord)\\n    FROM jsonb_array_elements(c#>''''{preview,pages}'''') WITH ORDINALITY pg(page_value,page_ord)\\n    CROSS JOIN LATERAL jsonb_array_elements(pg.page_value->''''rows'''') WITH ORDINALITY rr(v,ord)) IS DISTINCT FROM actual_rows\\n  THEN RAISE EXCEPTION ''''CoreReview digest text/full saved rows differ from native producer'''' USING ERRCODE=''''23514''''; END IF;\\n  page_no:=0;count_rows:=0;\\n  FOR page IN SELECT value FROM jsonb_array_elements(b#>''''{preview,pages}'''') LOOP\\n   IF public.large_import_core_review173_keys(page,ARRAY[''''head'''',''''rows'''',''''next'''',''''witness'''']) IS DISTINCT FROM true\\n   OR page->''''head'''' IS DISTINCT FROM b#>''''{preview,ack,head}'''' OR public.large_import_core_review173_ref(page->''''witness'''') IS DISTINCT FROM true\\n   OR jsonb_typeof(page->''''rows'''') IS DISTINCT FROM ''''array'''' OR jsonb_array_length(page->''''rows'''') NOT BETWEEN 1 AND 100\\n   THEN RAISE EXCEPTION ''''CoreReview closed page differs'''' USING ERRCODE=''''23514''''; END IF;\\n   FOR row_json IN SELECT value FROM jsonb_array_elements(page->''''rows'''') LOOP\\n    SELECT * INTO STRICT nr FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id AND index=count_rows;\\n    native_row:=(to_jsonb(nr)-ARRAY[''''tenant_id'''',''''preview_id'''',''''byte_count''''])||jsonb_build_object(''''changes'''',nr.input);\\n    resolution:=b->''''resolution''''->count_rows;\\n    IF row_json IS DISTINCT FROM native_row OR nr.errors IS DISTINCT FROM ''''[]''''::jsonb OR nr.operation NOT IN (''''create'''',''''update'''',''''unchanged'''')\\n    OR nr.identity_value IS DISTINCT FROM c->''''identities''''->>count_rows\\n    OR public.large_import_core_review173_keys(resolution,ARRAY[''''ordinal'''',''''product_id'''',''''operation'''']) IS DISTINCT FROM true\\n    OR resolution->''''ordinal'''' IS DISTINCT FROM to_jsonb(total_rows) OR nr.product_id IS NULL\\n    OR jsonb_typeof(resolution->''''product_id'''') IS DISTINCT FROM ''''string''''\\n    OR (resolution->>''''product_id'''') !~* ''''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''''\\n    OR (resolution->>''''product_id'''')::uuid IS DISTINCT FROM nr.product_id\\n    OR resolution->>''''operation'''' IS DISTINCT FROM nr.operation OR nr.product_id=ANY(ids)\\n    OR (nr.after->>''''id'''')::uuid IS DISTINCT FROM nr.product_id OR jsonb_typeof(nr.after->''''components'''') IS DISTINCT FROM ''''array''''\\n    THEN RAISE EXCEPTION ''''CoreReview full native row/resolution differs'''' USING ERRCODE=''''23514''''; END IF;\\n    ids:=array_append(ids,nr.product_id);batches:=array_append(batches,n);\\n    IF nr.after->>''''parent_id'''' IS NOT NULL THEN links:=links||jsonb_build_array(jsonb_build_object(''''batch'''',n,''''id'''',(nr.after->>''''parent_id'''')::uuid)); END IF;\\n    FOR ref IN SELECT value FROM jsonb_array_elements(nr.after->''''components'''') LOOP\\n     IF jsonb_typeof(ref->''''product_id'''') IS DISTINCT FROM ''''string'''' OR (ref->>''''product_id'''') !~* ''''^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$''''\\n     THEN RAISE EXCEPTION ''''CoreReview native component UUID is required'''' USING ERRCODE=''''23514''''; END IF;\\n     links:=links||jsonb_build_array(jsonb_build_object(''''batch'''',n,''''id'''',(ref->>''''product_id'''')::uuid));\\n    END LOOP;\\n    count_rows:=count_rows+1;total_rows:=total_rows+1;\\n   END LOOP;\\n   IF page_no=jsonb_array_length(b#>''''{preview,pages}'''')-1 THEN\\n    IF page->''''next'''' IS DISTINCT FROM ''''null''''::jsonb THEN RAISE EXCEPTION ''''CoreReview final cursor differs'''' USING ERRCODE=''''23514''''; END IF;\\n   ELSIF page->''''next'''' IS DISTINCT FROM to_jsonb(count_rows::text) OR count_rows>=p.total\\n   THEN RAISE EXCEPTION ''''CoreReview intermediate cursor differs'''' USING ERRCODE=''''23514''''; END IF;\\n   page_no:=page_no+1;\\n  END LOOP;\\n  IF count_rows<>p.total OR count_rows<>jsonb_array_length(c->''''identities'''') OR count_rows<>jsonb_array_length(b->''''resolution'''')\\n  THEN RAISE EXCEPTION ''''CoreReview full batch count differs'''' USING ERRCODE=''''23514''''; END IF;\\n  IF public.large_import_core_review173_keys(b->''''eligibility'''',ARRAY[''''eligible'''',''''authority_revision'''',''''source_hash'''',''''sources'''',''''quota_witness'''']) IS DISTINCT FROM true\\n  OR jsonb_typeof(b#>''''{eligibility,eligible}'''') IS DISTINCT FROM ''''boolean''''\\n  OR jsonb_typeof(b#>''''{eligibility,authority_revision}'''') IS DISTINCT FROM ''''string'''' OR length(b#>>''''{eligibility,authority_revision}'''')=0\\n  OR jsonb_typeof(b#>''''{eligibility,source_hash}'''') IS DISTINCT FROM ''''string'''' OR (b#>>''''{eligibility,source_hash}'''') !~ ''''^[a-f0-9]{64}$''''\\n  OR jsonb_typeof(b#>''''{eligibility,sources}'''') IS DISTINCT FROM ''''array'''' OR jsonb_array_length(b#>''''{eligibility,sources}'''')=0\\n  OR public.large_import_core_review173_ref(b#>''''{eligibility,quota_witness}'''') IS DISTINCT FROM true\\n  THEN RAISE EXCEPTION ''''CoreReview eligibility witness shape differs'''' USING ERRCODE=''''23514''''; END IF;\\n  FOR ref IN SELECT value FROM jsonb_array_elements(b#>''''{eligibility,sources}'''') LOOP\\n   IF public.large_import_core_review173_ref(ref) IS DISTINCT FROM true THEN RAISE EXCEPTION ''''CoreReview source witness shape differs'''' USING ERRCODE=''''23514''''; END IF;\\n  END LOOP;\\n  projected_batches:=projected_batches||jsonb_build_array(jsonb_build_object(''''index'''',n,''''preview_id'''',b->''''preview_id'''',''''scope_hash'''',b->''''scope_hash'''',\\n    ''''preview_key'''',b->''''preview_key'''',''''execute_key'''',b->''''execute_key'''',''''request_hash'''',b->''''request_hash'''',''''rows_hash'''',b->''''rows_hash'''',''''resolution'''',b->''''resolution'''',\\n    ''''source_hash'''',b#>''''{eligibility,source_hash}'''',''''authority_revision'''',b#>''''{eligibility,authority_revision}''''));\\n  n:=n+1;\\n END LOOP;\\n IF total_rows<>(state#>>''''{manifest,records}'''')::integer THEN RAISE EXCEPTION ''''CoreReview whole record count differs'''' USING ERRCODE=''''23514''''; END IF;\\n FOR ref IN SELECT value FROM jsonb_array_elements(links) LOOP\\n  target:=(ref->>''''id'''')::uuid;\\n  IF target=ANY(ids) AND batches[array_position(ids,target)]<>(ref->>''''batch'''')::integer\\n  THEN RAISE EXCEPTION ''''CoreReview cross-batch dependency requires separate plan'''' USING ERRCODE=''''23514''''; END IF;\\n END LOOP;\\n projection:=jsonb_build_object(''''schema'''',r->''''schema'''',''''source_plan_hash'''',r->''''source_plan_hash'''',''''raw'''',r->''''raw'''',''''parsing_spec'''',r->''''parsing_spec'''',''''batches'''',projected_batches);\\n IF NEW.scope_text::jsonb IS DISTINCT FROM projection\\n THEN RAISE EXCEPTION ''''CoreReview exact scope text business projection differs'''' USING ERRCODE=''''23514''''; END IF;\\n -- Only exact scope projection reaches this native serializer. Full request/rows are NEVER passed.\\n canonical_scope:=public.large_import_core_scope173_text(projection);\\n IF NEW.scope_text IS DISTINCT FROM canonical_scope\\n OR NEW.aggregate_scope_hash IS DISTINCT FROM encode(sha256(convert_to(canonical_scope,''''UTF8'''')),''''hex'''')\\n THEN RAISE EXCEPTION ''''CoreReview scope native canonical bytes/hash differ'''' USING ERRCODE=''''23514''''; END IF;\\n IF NEW.approved_scope_hash IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->''''batches'''') b WHERE b#>''''{eligibility,eligible}'''' IS DISTINCT FROM ''''true''''::jsonb)\\n THEN RAISE EXCEPTION ''''CoreReview approval requires every eligibility witness true'''' USING ERRCODE=''''23514''''; END IF;\\n SELECT * INTO old_review FROM public.large_import_core_reviews173 WHERE tenant_id=NEW.tenant_id AND job_id=NEW.job_id ORDER BY revision DESC LIMIT 1;\\n IF FOUND THEN\\n  -- A lost-COMMIT retry is a byte-identical no-op, not a second historical INSERT.\\n  IF (NEW.actor_id,NEW.api_key_id,NEW.revision,NEW.review_text,NEW.review_sha256,NEW.aggregate_scope_hash,NEW.approved_scope_hash,NEW.scope_text,NEW.request_texts,NEW.row_texts)\\n    IS NOT DISTINCT FROM (old_review.actor_id,old_review.api_key_id,old_review.revision,old_review.review_text,old_review.review_sha256,old_review.aggregate_scope_hash,old_review.approved_scope_hash,old_review.scope_text,old_review.request_texts,old_review.row_texts)\\n  THEN RETURN NULL; END IF;\\n  old_revision:=old_review.revision;\\n ELSE\\n  old_revision:=-1;\\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->''''core'''') c WHERE c ? ''''execution'''')\\n  OR EXISTS(SELECT 1 FROM public.catalog_file_import_executions e WHERE e.tenant_id=NEW.tenant_id\\n    AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->''''batches'''') b WHERE e.preview_id=(b->>''''preview_id'''')::uuid))\\n  THEN RAISE EXCEPTION ''''Initial CoreReview cannot follow a product execution'''' USING ERRCODE=''''23514''''; END IF;\\n END IF;\\n IF NEW.revision<>old_revision+1 THEN RAISE EXCEPTION ''''CoreReview append revision differs'''' USING ERRCODE=''''23514''''; END IF;\\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->''''core'''') WITH ORDINALITY bc(v,i)\\n  WHERE NOT bc.v ? ''''execution'''' AND EXISTS(SELECT 1 FROM jsonb_array_elements(state->''''events'''') e WHERE e->>''''kind''''=''''core-execute-attempt'''' AND e->''''batch''''=to_jsonb((bc.i-1)::integer)))\\n THEN RAISE EXCEPTION ''''Unresolved original execution requires exact-key recovery'''' USING ERRCODE=''''23514''''; END IF;\\n -- Native canonical scope is enforced by the exact scoped serializer above. Native parity still requires Root PG gate.\\n -- Full request/rows retain TEXT SHA + native business equality + strict JS bytes, no native whole-tree number serializer.\\n -- Current Actor/session/IAM/source/quota admittance is still the genuine injected ports.admit / validateCoreBatch ABI;\\n -- no such standalone native173 ABI is implemented/certified. Candidate activation is therefore NOT_APPLY_READY.\\n -- A later composed current-admit/cert guard MUST close this external native-IAM trust boundary before activation.\\n -- Missing ABI refuses deterministically; mere presence is NOT a certified IAM/call-context proof.\\n -- Activation also requires owner-external certificate/preflight and a genuine same-transaction ports.admit.\\n IF to_regprocedure(''''public.large_import173_admit(uuid,uuid,uuid,text,text,boolean)'''') IS NULL\\n THEN RAISE EXCEPTION ''''CoreReview current native admission ABI is absent'''' USING ERRCODE=''''0A000''''; END IF;\\n RETURN NEW;\\nEND $function$\\n\",\"volatility\":\"v\",\"body_sha256\":\"27072195adc4f1f2581af15f2f9c24e495a4f967c59e3a9afc2a96cebd7eb0d0\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"argument_modes\":null,\"argument_names\":null,\"security_definer\":true},{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"boolean\",\"strict\":false,\"defaults\":null,\"language\":\"sql\",\"parallel\":\"u\",\"arguments\":\"v jsonb, names text[]\",\"leakproof\":false,\"signature\":\"large_import_core_review173_keys(jsonb,text[])\",\"definition\":\"CREATE OR REPLACE FUNCTION public.large_import_core_review173_keys(v jsonb, names text[])\\n RETURNS boolean\\n LANGUAGE sql\\n IMMUTABLE\\n SET search_path TO ''''pg_catalog''''\\nAS $function$\\n SELECT CASE WHEN jsonb_typeof(v)=''''object'''' THEN\\n   (SELECT count(*) FROM jsonb_object_keys(v))=cardinality(names) AND v ?& names\\n ELSE false END\\n$function$\\n\",\"volatility\":\"i\",\"body_sha256\":\"6d1374e0e4b405bb067f9f2bbb9a9ccff4e06642664a365262848b2f59adb6a5\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog\"],\"argument_modes\":null,\"argument_names\":[\"v\",\"names\"],\"security_definer\":false},{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"boolean\",\"strict\":false,\"defaults\":null,\"language\":\"sql\",\"parallel\":\"u\",\"arguments\":\"v jsonb\",\"leakproof\":false,\"signature\":\"large_import_core_review173_ref(jsonb)\",\"definition\":\"CREATE OR REPLACE FUNCTION public.large_import_core_review173_ref(v jsonb)\\n RETURNS boolean\\n LANGUAGE sql\\n IMMUTABLE\\n SET search_path TO ''''pg_catalog'''', ''''public''''\\nAS $function$\\n SELECT public.large_import_core_review173_keys(v,ARRAY[''''id'''',''''sha256'''',''''byte_count''''])\\n AND jsonb_typeof(v->''''id'''')=''''string'''' AND length(v->>''''id'''')>0\\n AND jsonb_typeof(v->''''sha256'''')=''''string'''' AND (v->>''''sha256'''')~''''^[a-f0-9]{64}$''''\\n AND jsonb_typeof(v->''''byte_count'''')=''''number'''' AND (v->>''''byte_count'''')~''''^(0|[1-9][0-9]*)$''''\\n AND (v->>''''byte_count'''')::numeric BETWEEN 0 AND 9007199254740991\\n$function$\\n\",\"volatility\":\"i\",\"body_sha256\":\"3aeca9a5e0b16349e1bb4d7db34cf1133d48bed1a3390e153819bacef771212d\",