urce_key IS DISTINCT FROM ''''blob:fs:directory:''''||encode(sha256(convert_to(x.payload_text::jsonb->>''''path'''',''''UTF8'''')),''''hex'''')\\n  OR x.byte_count IS DISTINCT FROM octet_length(x.payload_text)::bigint OR x.sha256 IS DISTINCT FROM encode(sha256(convert_to(x.payload_text,''''UTF8'''')),''''hex'''') THEN RAISE EXCEPTION ''''Absent reconciliation original directory allocation mismatch'''' USING ERRCODE=''''23514'''';END IF;\\n END LOOP;\\n IF (SELECT count(DISTINCT z.payload_text::jsonb->>''''path'''') FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q)<>5 THEN RAISE EXCEPTION ''''Absent reconciliation duplicate paths'''' USING ERRCODE=''''23514'''';END IF;\\n -- Conservative scope: this special prefix accepts no actor-owned blob/job/review metadata at all.\\n -- Child parts/batches/events cannot exist without their FK parents. General failed uploads use a different keeper.\\n IF EXISTS(SELECT 1 FROM public.large_import_blobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)\\n OR EXISTS(SELECT 1 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)\\n OR EXISTS(SELECT 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k) THEN RAISE EXCEPTION ''''Absent reconciliation has native upload/business metadata'''' USING ERRCODE=''''23514'''';END IF;\\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resources'''',resources0,''''expected_paths'''',to_jsonb(paths0));\\nEND $function$\\n\",\"volatility\":\"v\",\"body_sha256\":\"ee00c5cf55d44316abbd4daa134557f6191b2395859141fcb85d4ae3b1add54a\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"argument_modes\":null,\"argument_names\":[\"u\",\"t\",\"k\",\"r\",\"h\",\"q\",\"token\",\"client0\"],\"security_definer\":true},{\"acl\":[[\"postgres\",\"pos