OR b.outcome<>''''ready'''' OR old.payload_text::jsonb->''''receipt''''->>''''client_key'''' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''''Known-close original key conflict'''' USING ERRCODE=''''23505'''';END IF;\\n  RETURN jsonb_build_object(''''reused'''',true,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',old.payload_text::jsonb->''''receipt''''); -- no fresh cut or callback on exact old-key recovery\\n END IF;\\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \\\"C\\\"),''''[]''''::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\\n IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>''''state'''' NOT IN(''''settled'''',''''released'''')) THEN RAISE EXCEPTION ''''Known close has pending original allocations'''' USING ERRCODE=''''40001'''';END IF;\\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resources'''',snapshot0);\\nEND $function$\\n\",\"volatility\":\"v\",\"body_sha256\":\"d7dd88adb51e571a8e124bec7e5dae9f7e6bdef6796eafc326e7f70f65ce0948\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"argument_modes\":null,\"argument_names\":[\"u\",\"t\",\"k\",\"r\",\"h\",\"q\",\"token\",\"client0\"],\"security_definer\":true},{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"jsonb\",\"strict\":false,\"defaults\":null,\"language\":\"plpgsql\",\"parallel\":\"u\",\"arguments\":\"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text\",\"leakproof\":false,\"signature\":\"large_import_quota_owned_close_finish173(uuid,uuid,uuid,text,text,uuid,text,uuid,text)\",\"definition\":\"CREATE OR REPLACE FUNCTION public.large_import_quota_owned_c