atalog\\\\\\\\_stock\\\\\\\\_return\\\\\\\\_%'''''''' ESCAPE ''''''''\\\\\\\\'''''''' OR c.relname LIKE ''''''''catalog\\\\\\\\_stock\\\\\\\\_control\\\\\\\\_%'''''''' ESCAPE ''''''''\\\\\\\\'''''''' OR c.relname LIKE ''''''''b2b\\\\\\\\_invoice\\\\\\\\_%'''''''' ESCAPE ''''''''\\\\\\\\'''''''' OR c.relname LIKE ''''''''fa3\\\\\\\\_draft\\\\\\\\_%'''''''' ESCAPE ''''''''\\\\\\\\'''''''' OR c.relname LIKE ''''''''b2b\\\\\\\\_dropship\\\\\\\\_%'''''''' ESCAPE ''''''''\\\\\\\\'''''''' OR c.relname IN(''''''''local_invoice_series'''''''',''''''''local_invoice_series_commands'''''''',''''''''orders'''''''',''''''''order_items'''''''',''''''''order_merge_claims'''''''',''''''''return_cases'''''''',''''''''documents'''''''',''''''''invoice_plans'''''''',''''''''odoo_invoice_exports'''''''',''''''''users'''''''',''''''''sessions'''''''',''''''''memberships'''''''',''''''''api_keys'''''''',''''''''account_security'''''''',''''''''workspace_security_policies'''''''',''''''''tenants'''''''',''''''''return_items'''''''',''''''''stock_movements'''''''',''''''''stock_location_movements'''''''',''''''''wms_layer_movements'''''''',''''''''wms_cost_layers'''''''',''''''''wms_issue_fragments'''''''',''''''''wms_return_fragments'''''''',''''''''wms_operations'''''''')) AND c.relkind IN(''''''''r'''''''',''''''''p'''''''')),\\\\n ''''''''functions'''''''',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.provolatile,p.proisstrict,p.proleakproof,p.proparallel,p.prokind,p.proretset,p.prorettype,pg_get_function_identity_arguments(p.oid),pg_get_function_result(p.oid),p.proargmodes,p.proargnames,pg_get_expr(p.proargdefaults,0),(SELECT lanname FROM pg_language WHERE oid=p.prolang),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''''''''PUBLIC'''''''' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''''''''PUBLIC'''''''' ELSE pg