 STRICT c FROM public.large_import173_certificate WHERE singleton;\\n IF (SELECT count(*) FROM public.large_import173_certificate)<>1 THEN RETURN false;END IF;\\n p:=public.large_import173_metadata();\\n IF p IS DISTINCT FROM c.profile OR encode(sha256(convert_to(p::text,''''UTF8'''')),''''hex'''') IS DISTINCT FROM c.profile_sha256\\n OR public.large_import173_predecessor_map() IS DISTINCT FROM c.predecessor_map\\n OR encode(sha256(convert_to(c.predecessor_map::text,''''UTF8'''')),''''hex'''') IS DISTINCT FROM c.predecessor_sha256\\n OR c.module_sql_sha256 IS DISTINCT FROM ''''7fafb32748feabb30345c87509936c36730c748923012ca3f54b3e0cde175138'''' THEN RETURN false;END IF;\\n RETURN public.large_import173_parents_valid();\\nEXCEPTION WHEN OTHERS THEN RETURN false;\\nEND\\n$function$\\n\",\"volatility\":\"s\",\"body_sha256\":\"58b68b0436150efc777db963b95f82035c20d2f0f33cb24e189b167dded76560\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"argument_modes\":null,\"argument_names\":null,\"security_definer\":true},{\"acl\":[[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"boolean\",\"strict\":false,\"defaults\":null,\"language\":\"plpgsql\",\"parallel\":\"u\",\"arguments\":\"expected_profile_sha256 text\",\"leakproof\":false,\"signature\":\"large_import173_validate_recovered(text)\",\"definition\":\"CREATE OR REPLACE FUNCTION public.large_import173_validate_recovered(expected_profile_sha256 text)\\n RETURNS boolean\\n LANGUAGE plpgsql\\n STABLE SECURITY DEFINER\\n SET search_path TO ''''pg_catalog'''', ''''public''''\\n SET \\\"TimeZone\\\" TO ''''UTC''''\\nAS $function$\\nBEGIN\\n -- Detached restoration compares portable descriptors, roles and bodies; never claims restored OID equality.\\n PERFORM public.large_import173_require(expected_profile_sha256);RETURN true;\\nEXCEPTION WHEN OTHERS THEN RETURN false;\\nEND\\n$function$\\n\",\"volatility\":\"s\",