''public.print_job_guards()'''', ''''22a80b97d2dd6cbcee224440167e06bedf45a918aebdcb054781d2ef97002b88''''),\n  (''''public.product_rule_price_tags_guards()'''', ''''50e108f5c95e0b774984c034393c6e97d8266285094ee5e64b68d2c0173c11ff''''),\n  (''''public.product_rule_schedule_guards()'''', ''''d7e4b406c55d954900999f0c8382313a0d4c915aa8345c249dc1e7d9910df0f1''''),\n  (''''public.stocktake_adjustment_guards()'''', ''''09ed6c60812033a3b703a1f7881322da2c7231a142d090b2e06f32793f42cfaa''''),\n  (''''public.warehouse_automatic_wz_guards()'''', ''''f471bb00471a10f0c4469e440a539da6bf625664c0de6eef19669dce556b4ef7''''),\n  (''''public.warehouse_wz_issuer_guards()'''', ''''4ddf9eddeaf10271fe6d874da8865983512600a7710601811303864e9580a438'''') ) AS required(signature,body_sha256) LOOP\n  live_sha:=public.ordinary177_parent_hash(expected.signature);\n  IF live_sha IS DISTINCT FROM expected.body_sha256 THEN RETURN false;END IF;\n END LOOP;\n IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(public.pim_dictionary_predecessor_metadata()) names(key))\n IS DISTINCT FROM ARRAY[''''allegro_oauth_recovery_guards'''',''''b2b_credit_guards'''',''''b2b_invoice_guards'''',''''buyer_address_guards'''',''''catalog_stock_control_guards'''',''''catalog_stock_count_guards'''',''''catalog_stock_legacy_group_guards'''',''''catalog_stock_return_guards'''',''''competitor_observation_guards'''',''''credit_source_upgrade_valid'''',''''fa3_draft_guards'''',''''financial_return_guards'''',''''financial_return_upgrade_valid'''',''''label_print_guards'''',''''local_invoice_guards'''',''''manual_inventory_off_valid'''',''''operative_delivery_valid'''',''''packed_label_print_guards'''',''''parcel_physical_wz_valid'''',''''print_job_guards'''',''''product_rule_price_tags_guards'''',''''product_rule_schedule_guards'''',''''stocktake_adjustment_guards'''',''''warehouse_automatic_wz_guards'''',''''warehouse_wz_issuer_guards'''']::text[] THEN RETURN false;END IF;\n -- Source-pinned173 PIM copy executes the nested172 certificate checks,\n -- nested172_valid(), then15 super-guards covering all25 current predecessors.\n -- Whole173 profile/predecessor equality remains in large_import173_valid().\n -- Query cancellation has no handler here and propagates as57014.\n RETURN public.ordinary177_history_pim_valid() IS NOT DISTINCT FROM true;\nEND\n'' AND pg_get_userbyid(p.proowner)=(c.profile#>>''{functions,0,owner}'') AND p.prosecdef AND NOT p.proisstrict AND p.provolatile=''s'' AND p.proparallel=''u'' AND p.prokind=''f'' AND p.procost=100 AND p.prorows=0 AND NOT p.proretset AND NOT p.proleakproof AND p.pronargdefaults=0 AND p.proargmodes IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND l.lanname=''plpgsql'' AND p.proconfig=ARRAY[''search_path=pg_catalog, public'',''TimeZone=UTC''] AND pg_get_function_result(p.oid)=''boolean'' AND pg_get_function_identity_arguments(p.oid)='''' AND public.pim_dictionary_acl_metadata(coalesce(p.proacl,acldefault(''f'',p.proowner)))=jsonb_build_array(jsonb_build_array(pg_get_userbyid(p.proowner),pg_get_userbyid(p.proowner),''EXECUTE'',false))) THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.ordinary177_valid()'') AND pg_get_userbyid(p.proowner)=(c.profile#>>''{functions,0,owner}'') AND p.prosecdef AND NOT p.proisstrict AND p.provolatile=''s'' AND p.proparallel=''u'' AND p.prokind=''f'' AND p.procost=100 AND p.prorows=0 AND NOT p.proretset AND NOT p.proleakproof AND p.pronargdefaults=0 AND p.proargmodes IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND l.lanname=''plpgsql'' AND p.proconfig=ARRAY[''search_path=pg_catalog, public'',''TimeZone=UTC''] AND pg_get_function_result(p.oid)=''boolean'' AND pg_get_function_identity_arguments(p.oid)='''' AND public.pim_dictionary_acl_metadata(coalesce(p.proacl,acldefault(''f'',p.proowner)))=jsonb_build_array(jsonb_build_array(pg_get_userbyid(p.proowner),pg_get_userbyid(p.proowner),''EXECUTE'',false))) THEN RETURN false;END IF;\nmanual_basis:=public.ordinary181_manual_basis((SELECT payload FROM public.manual_inventory_off_certificate WHERE id));\n wave_ok:=public.order_merge_delivery209_wave_valid(manual_basis);\n IF (SELECT public.order_merge_delivery209_predecessor_source_sha(oid, merge_delivery209_local_frame) FROM pg_proc WHERE oid=to_regprocedure(''public.wave_print177_valid()'')) IS DISTINCT FROM ''789ecccafca44cb6243dfbe14e642f4d6ee59e87305e11682feef848b521f091'' OR wave_ok IS DISTINCT FROM true THEN RETURN false;END IF;\n p:=public.ordinary187_profile_project(public.order_merge_delivery209_predecessor_metadata(public.large_import173_metadata(), merge_delivery209_local_frame));\n IF p IS DISTINCT FROM c.profile OR encode(sha256(convert_to(p::text,''UTF8'')),''hex'') IS DISTINCT FROM c.profile_sha256 OR public.order_merge_delivery209_history_predecessor_project(public.order_merge_delivery209_predecessor_metadata(public.large_import173_predecessor_map(), merge_delivery209_local_frame), merge_delivery209_local_frame) IS DISTINCT FROM c.predecessor_map OR encode(sha256(convert_to(c.predecessor_map::text,''UTF8'')),''hex'') IS DISTINCT FROM c.predecessor_sha256 THEN RETURN false;END IF;\n RETURN public.order_merge_delivery209_history_parents_valid(manual_basis,wave_ok);\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND\n","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"definition":"CREATE OR REPLACE FUNCTION public.ordinary187_valid()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $functionx$\nDECLARE merge_delivery209_local_frame jsonb; c public.large_import173_certificate%ROWTYPE;p jsonb;manual_basis jsonb;wave_ok boolean;BEGIN\n merge_delivery209_local_frame:=public.order_merge_delivery209_checked_projection_map();\n IF public.partial_sale204_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n IF (SELECT array_agg(proname::text ORDER BY proname) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND starts_with(proname,''ordinary187_'')) IS DISTINCT FROM ARRAY[''ordinary187_approve'',''ordinary187_enter'',''ordinary187_journal_usage'',''ordinary187_owner_abandon_empty'',''ordinary187_owner_closed'',''ordinary187_owner_closed_complete'',''ordinary187_owner_context'',''ordinary187_owner_cut'',''ordinary187_owner_cut_header'',''ordinary187_owner_cut_page'',''ordinary187_owner_io_arm'',''ordinary187_owner_io_drain'',''ordinary187_owner_member'',''ordinary187_owner_member_finish'',''ordinary187_owner_member_xid'',''ordinary187_owner_open'',''ordinary187_owner_original'',''ordinary187_owner_original_drained'',''ordinary187_owner_pin'',''ordinary187_owner_poison'',''ordinary187_private_valid'',''ordinary187_profile_project'',''ordinary187_resource_guard'',''ordinary187_seal'',''ordinary187_valid'']::text[] THEN RETURN false;END IF;\n IF public.ordinary187_private_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.ordinary187_approve(text,text,text)'') AND (SELECT count(*) FROM pg_proc sibling WHERE sibling.pronamespace=p.pronamespace AND sibling.proname=p.proname)=1 AND public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_local_frame)=''488178531c4bc3c18e5e7e9c81bb541d63493471bf4417afb3610a39944f3afc'' AND pg_get_function_identity_arguments(p.oid)=''release_sha text, native_sha text, profile_sha text'' AND pg_get_function_result(p.oid)=''jsonb'' AND l.lanname=''plpgsql'' AND pg_get_userbyid(p.proowner)=''postgres'' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel=''u'' AND p.prokind=''f'' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile=''v'' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM ARRAY[''release_sha'',''native_sha'',''profile_sha'']::text[] AND p.proconfig=ARRAY[''search_path=pg_catalog, public'',''TimeZone=UTC'']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a)=''[[\"postgres\",\"postgres\",\"EXECUTE\",false]]''::jsonb AND p.provariadic=0 AND p.prosupport=0 AND p.probin IS NULL AND p.prosqlbody IS NULL AND p.proallargtypes IS NULL AND p.protrftypes IS NULL) THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(''public.ordinary187_private_valid()'') AND (SELECT count(*) FROM pg_proc sibling WHERE sibling.pronamespace=p.pronamespace AND sibling.proname=p.proname)=1 AND public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_local_frame)=''0a0ded2656c3f771c08f7ff9080166f5db3a5cd2151dd7930e1a9ea66a5530b1'' AND pg_get_function_identity_arguments(p.oid)='''' AND pg_get_function_result(p.oid)=''boolean'' AND l.lanname=''plpgsql'' AND pg_get_userbyid(p.proowner)=''postgres'' AND p.prosecdef AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel=''u'' AND p.prokind=''f'' AND NOT p.proretset AND p.procost=100 AND p.prorows=0 AND p.provolatile=''s'' AND p.proargmodes IS NULL AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.proargnames IS NOT DISTINCT FROM NULL::text[] AND p.proconfig=ARRAY[''search_path=pg_catalog, public'',''TimeZone=UTC'']::text[] AND (SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',