NOT FOUND OR b.state IS DISTINCT FROM ''''open'''' THEN RAISE EXCEPTION ''''Publication reservation is not active/owned'''' USING ERRCODE=''''42501'''';END IF;\\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \\\"C\\\" FOR SHARE;\\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \\\"C\\\" LOOP\\n  SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''''key'''';\\n  IF NOT FOUND OR x.state=''''released'''' OR x.byte_count IS DISTINCT FROM (v->>''''byte_count'''')::bigint OR x.sha256 IS DISTINCT FROM v->>''''sha256'''' THEN RAISE EXCEPTION ''''Publication allocation changed/terminal'''' USING ERRCODE=''''40001'''';END IF;\\n END LOOP;\\n -- Full fresh currentIAM/graph still present on both sides of pins; FS transaction caller also\\n -- retains its original late checkpoint AFTER actual writes. There is no cached schema verdict.\\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\\nEND $function$\\n\",\"volatility\":\"v\",\"body_sha256\":\"3e8e0c6adedf6290770084ef82ff4bf3fa14f12fbcbab33970ba5f26f6bb6786\",\"returns_set\":false,\"configuration\":[\"search_path=pg_catalog, public\",\"TimeZone=UTC\"],\"argument_modes\":null,\"argument_names\":[\"u\",\"t\",\"k\",\"r\",\"h\",\"q\",\"token\",\"items\"],\"security_definer\":true},{\"acl\":[[\"postgres\",\"dyna_app\",\"EXECUTE\",false],[\"postgres\",\"postgres\",\"EXECUTE\",false]],\"cost\":100,\"kind\":\"f\",\"rows\":0,\"owner\":\"postgres\",\"result\":\"jsonb\",\"strict\":false,\"defaults\":null,\"language\":\"plpgsql\",\"parallel\":\"u\",\"arguments\":\"u uuid, t uuid, k uuid, r text, h text, q uuid, request uuid, token text, kind0 text, raw0 bigint, metadata0 bigint, objects0 bigint\",\"leakproof\":false,\"signature\":\"large_import_quota_reserve173(uuid,uuid,uuid,text,text,uuid,uuid,text,text,bigint,bi