RE tenant_id=t AND octet_length(payload::text)+octet_length(request::text)>4194304) THEN RAISE EXCEPTION ''''Limit historii etykiet drukowania'''' USING ERRCODE=''''23514''''; END IF;\n SELECT coalesce((SELECT sum(octet_length(content_base64)+coalesce(octet_length(order_snapshot::text),0)+coalesce(octet_length(wave_snapshot::text),0)+octet_length(station_snapshot::text)+octet_length(printer_snapshot::text)+512) FROM print_jobs WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(result::text)+octet_length(coalesce(before_head::text,''''''''))+512) FROM print_job_events WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(to_jsonb(p)::text)) FROM print_printers p WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(content_encrypted)+octet_length(source_frame::text)+512) FROM print_label_assets WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(payload::text)+octet_length(request::text)+512) FROM print_label_previews WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(request::text)+512) FROM print_job_label_sources WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(content_encrypted)+octet_length(source_frame::text)+512) FROM shipment_label_cache_assets WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(request::text)+octet_length(source_frame::text)+1024) FROM shipment_label_cache_acquisitions WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(combined_content_encrypted)+octet_length(payload::text)+octet_length(request::text)+512) FROM shipment_label_batch_previews WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(payload::text)+512) FROM shipment_label_batch_preview_rows WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(payload::text)+octet_length(request::text)+512) FROM shipment_label_batch_executions WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(payload::text)+512) FROM shipment_label_batch_execution_rows WHERE tenant_id=t),0)+coalesce((SELECT sum(octet_length(request::text)+octet_length(witnesses::text)+512) FROM shipment_label_batch_admissions WHERE tenant_id=t),0) INTO n;\n IF n>67108864 THEN RAISE EXCEPTION ''''Limit historii drukowania'''' USING ERRCODE=''''23514''''; END IF;\nEND ''\n OR(live-''body''-''definition'') IS DISTINCT FROM(b-''body''-''definition'')\n OR replace(live->>''definition'',live->>''body'',b->>''body'') IS DISTINCT FROM b->>''definition'' THEN RETURN false;END IF;\n PERFORM public.wave_print177_project_packed(public.packing189_wave_project_packed(public.order_merge_delivery209_predecessor_metadata(public.wave_print177_packed_metadata(), merge_delivery209_local_frame)),c.packed_metadata,c.functions_before);\n\n -- Exact one declared operative leaf delta; every other record/property is retained.\n operative189:=public.order_merge_delivery209_predecessor_metadata(public.wave_print177_operative_metadata(), merge_delivery209_local_frame);\n IF jsonb_typeof(operative189->''functions'') IS DISTINCT FROM ''array''\n OR (SELECT count(*) FROM jsonb_array_elements(operative189->''functions'') WHERE value->>''name''=''operative_delivery_valid'' AND value->>''args''='''')<>1\n OR (SELECT count(*) FROM jsonb_array_elements(c.metadata_after#>''{operative,functions}'') WHERE value->>''name''=''operative_delivery_valid'' AND value->>''args''='''')<>1 THEN RETURN false;END IF;\n items189:=''[]'';\n FOR entry189 IN SELECT value FROM jsonb_array_elements(operative189->''functions'') LOOP\n  IF entry189->>''name''=''operative_delivery_valid'' AND entry189->>''args''='''' THEN\n   SELECT value INTO STRICT old_entry189 FROM jsonb_array_elements(c.metadata_after#>''{operative,functions}'') WHERE value->>''name''=''operative_delivery_valid'' AND value->>''args''='''';\n   IF (entry189-''def'') IS DISTINCT FROM (old_entry189-''def'')\n   OR position(leaf_sha IN entry189->>''def'')=0\n   OR replace(entry189->>''def'',leaf_sha,''cd77c1cd4b1b4be9d8fbfb1b225299508f9724cc552cb045f5ba710cc84fd666'') IS DISTINCT FROM old_entry189->>''def'' THEN RETURN false;END IF;\n   entry189:=old_entry189;\n  END IF;items189:=items189||jsonb_build_array(entry189);\n END LOOP;operative189:=jsonb_set(operative189,''{functions}'',items189);\n PERFORM public.wave_print177_project_operative(operative189,c.operative_before,c.functions_before);\n RETURN public.wave_print177_history_nested172_valid() IS TRUE AND public.order_merge_delivery209_startup_operative_valid(merge_delivery209_local_frame) IS TRUE;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND\n$function$\n","acl_null":false,"acl":[{"grantor":"postgres","grantee":"dyna_app","privilege":"EXECUTE","grantable":false},{"grantor":"postgres","grantee":"postgres","privilege":"EXECUTE","grantable":false}]},"after_check":{"owner":"postgres","language":"plpgsql","kind":"f","cost":100,"rows":0,"security_definer":true,"leakproof":false,"strict":false,"returns_set":false,"volatility":"s","parallel":"u","support":null,"variadic":null,"argument_names":null,"argument_modes":null,"arguments":"","result":"boolean","defaults":null,"source":["sha256-utf8-text/v1","fb17ff8f32ee1c9ced1e8bd22d1371b40560683358a498cbd50cb6865e595daa"],"binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"definition":["sha256-utf8-text/v1","f8f2609814f995c14bee59a7ae227bea80a7295e47925c964252dcaca753d352"],"acl_null":false,"acl":[{"grantor":"postgres","grantee":"dyna_app","privilege":"EXECUTE","grantable":false},{"grantor":"postgres","grantee":"postgres","privilege":"EXECUTE","grantable":false}]}},{"key":"public.cooperation171_valid()","before":{"owner":"postgres","language":"plpgsql","kind":"f","cost":100,"rows":0,"security_definer":true,"leakproof":false,"strict":false,"returns_set":false,"volatility":"s","parallel":"u","support":null,"variadic":null,"argument_names":null,"argument_modes":null,"arguments":"","result":"boolean","defaults":null,"source":"\nDECLARE c public.cooperation171_certificate;sig text;b jsonb;a jsonb;live jsonb;pred jsonb;r oid;\n expected_before jsonb:=$bodymap171${\"parcel_physical_wz_terminal_p