lic.nested172_valid()'') IS NULL THEN RETURN false;END IF;\n  IF(SELECT count(*) FROM public.nested172_certificate)<>1\n  OR (SELECT functions FROM public.nested172_certificate WHERE singleton) IS DISTINCT FROM public.nested172_function_map()\n  OR (SELECT metadata_hash FROM public.nested172_certificate WHERE singleton) IS DISTINCT FROM public.pim_dictionary_hash(public.nested172_metadata())\n  OR (SELECT public.order_merge_delivery209_predecessor_source_sha(oid, merge_delivery209_local_frame) FROM pg_proc WHERE oid=''public.nested172_function_map()''::regprocedure) IS DISTINCT FROM ''453e0ed82a069fba0822490c818c2e2d3b6e29f8bb62a0e608ce10df7b2b4e16''\n  OR (SELECT public.order_merge_delivery209_predecessor_source_sha(oid, merge_delivery209_local_frame) FROM pg_proc WHERE oid=''public.nested172_metadata()''::regprocedure) IS DISTINCT FROM ''5cbd5d4c412d66d0bd355bdf11c1b8726ea5f4954da23adcb654858d0d9ab1e1''\n  OR (SELECT public.order_merge_delivery209_predecessor_source_sha(oid, merge_delivery209_local_frame) FROM pg_proc WHERE oid=''public.nested172_valid()''::regprocedure) IS DISTINCT FROM ''1d3e63bd885f67080c1853096fea874330c8ced95159d9281939121758ba411a''\n  OR public.nested172_valid() IS DISTINCT FROM true THEN RETURN false;END IF;\n\n  RETURN true;\n END IF;\n\n IF current_setting(''session_replication_role'')<>''origin'' OR (SELECT public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_local_frame) FROM pg_proc p WHERE p.oid=to_regprocedure(''public.cooperation171_function_map()'')) IS DISTINCT FROM ''bd023956225b12dc40cc7f0e44c76d9c27699832791627ecb03143faa03691e2'' OR (SELECT public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_local_frame) FROM pg_proc p WHERE p.oid=to_regprocedure(''public.pim_dictionary_function_metadata(oid)'')) IS DISTINCT FROM ''0c28eea2eb88f0580540770447c3c5173657ee31f651e590e8e7985637e83f7d'' OR (SELECT public.order_merge_delivery209_predecessor_source_sha(p.oid, merge_delivery209_loca