CREATE TABLE public.order_merge_delivery209_manifest(
 id boolean PRIMARY KEY DEFAULT true CHECK(id),profile text NOT NULL CHECK(profile='merge-delivery-inheritance/v1'),
 original166 jsonb NOT NULL,constraints jsonb NOT NULL CHECK(jsonb_typeof(constraints)='array' AND jsonb_array_length(constraints)=4),
 fingerprint text NOT NULL CHECK(fingerprint~'^[a-f0-9]{64}$')
);
ALTER TABLE public.order_merge_delivery209_manifest ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.order_merge_delivery209_manifest FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_scope ON public.order_merge_delivery209_manifest TO postgres USING(true) WITH CHECK(true);
REVOKE ALL ON public.order_merge_delivery209_manifest FROM PUBLIC,dyna_app;
CREATE TRIGGER order_merge_delivery209_manifest_immutable BEFORE UPDATE OR DELETE ON public.order_merge_delivery209_manifest FOR EACH ROW EXECUTE FUNCTION public.order_merge_delivery209_immutable();
CREATE TRIGGER order_merge_delivery209_manifest_no_truncate BEFORE TRUNCATE ON public.order_merge_delivery209_manifest FOR EACH STATEMENT EXECUTE FUNCTION public.order_merge_delivery209_immutable();

CREATE FUNCTION public.order_merge_delivery209_validation_snapshot() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $snapshot209$
WITH legacy209_current(kind,key,value) AS MATERIALIZED (SELECT 'function',n.nspname||'.'||p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('owner',pg_catalog.pg_get_userbyid(p.proowner),'language',l.lanname,'kind',p.prokind,'cost',p.procost,'rows',p.prorows,'security_definer',p.prosecdef,'leakproof',p.proleakproof,'strict',p.proisstrict,'returns_set',p.proretset,'volatility',p.provolatile,'parallel',p.proparallel,'support',CASE WHEN p.prosupport=0 THEN NULL ELSE p.prosupport::regprocedure::text END,'variadic',CASE WHEN p.provariadic=0 THEN NULL ELSE pg_catalog.format_type(p.provariadic,NULL) END,'argument_names',p.proargnames,'argument_modes',p.proargmodes,'arguments',pg_catalog.pg_get_function_arguments(p.oid),'result',pg_catalog.pg_get_function_result(p.oid),'defaults',pg_catalog.pg_get_expr(p.proargdefaults,0),'source',jsonb_build_array('sha256-utf8-text/v1',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')),'binary',p.probin,'config',p.proconfig,'definition',jsonb_build_array('sha256-utf8-text/v1',encode(sha256(convert_to(pg_catalog.pg_get_functiondef(p.oid),'UTF8')),'hex')),'acl_null',p.proacl IS NULL,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_catalog.pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantor::regrole::text,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,a.privilege_type,a.is_grantable),'[]'::jsonb) FROM pg_catalog.aclexplode(CASE WHEN pg_catalog.cardinality(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner)))=0 THEN NULL::aclitem[] ELSE coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner)) END) a)) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace JOIN pg_catalog.pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname=ANY(ARRAY['buyer_address_preview_guard','buyer_address_state_guard','buyer_address_guards','buyer_address_fingerprint','manual_inventory_off_valid','manual_inventory_off_projection_valid','partial_sale204_predecessor_definition','ordinary187_valid','partial_sale204_valid','catalog_header205_valid','pim_dictionary_valid','nested172_valid','parcel_physical_wz_valid','operative_delivery_valid','wave_print177_valid','cooperation171_valid','packed_label_print_guards']::text[]))
SELECT jsonb_build_object(
 'fingerprint',(
 SELECT encode(sha256(convert_to(jsonb_build_object(
