 IF current_setting('server_encoding') IS DISTINCT FROM 'UTF8' OR public.order_merge_delivery209_valid() IS DISTINCT FROM true THEN RAISE EXCEPTION '209 exact generated projection required' USING ERRCODE='55000';END IF;
 SELECT count(*) OVER(),id,payload IS NOT NULL,payload_octets,payload_sha256,payload_jsonb INTO total,source_id,payload_present,payload_bytes,payload_hash,parsed_value FROM public.order_merge_delivery209_projection_basis;
 IF total IS DISTINCT FROM 1 OR source_id IS DISTINCT FROM true OR payload_present IS DISTINCT FROM true OR parsed_value IS NULL
  OR payload_bytes IS DISTINCT FROM 21756960 OR payload_hash IS DISTINCT FROM 'ed45aecdcf4d959c7ff636cd315a12162316f030cb1e382e7e82e5ed6eb4a2d4'
  THEN RAISE EXCEPTION '209 exact source projection basis required' USING ERRCODE='55000';END IF;
 RETURN parsed_value;
END
$map209$;
CREATE FUNCTION public.order_merge_delivery209_predecessor_descriptor(fn oid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $descriptor209$
DECLARE live jsonb;actual_key text;entry jsonb;entries jsonb;member_oid oid;total integer;selected_before jsonb;scoped boolean;source_id boolean;payload_present boolean;payload_bytes integer;payload_hash text;binding_ordinal integer;validated integer;BEGIN
 SELECT n.nspname='public' AND p.proname=ANY(ARRAY['buyer_address_preview_guard','buyer_address_state_guard','buyer_address_guards','buyer_address_fingerprint','manual_inventory_off_valid','manual_inventory_off_projection_valid','partial_sale204_predecessor_definition','ordinary187_valid','partial_sale204_valid','catalog_header205_valid','pim_dictionary_valid','nested172_valid','parcel_physical_wz_valid','operative_delivery_valid','wave_print177_valid','cooperation171_valid','packed_label_print_guards']::text[]) INTO scoped FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=fn;
