   THEN RAISE EXCEPTION '209 exact complete successor descriptor required' USING ERRCODE='55000';END IF;
 END LOOP;
 IF validated<>17 THEN RAISE EXCEPTION '209 complete predecessor scope required' USING ERRCODE='55000';END IF;
