c p WHERE p.pronamespace=''public''::regnamespace AND left(p.proname,20)=''catalog_stock_count_'' AND\n (p.proowner<>ownerid OR NOT p.prosecdef OR EXISTS(SELECT FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a WHERE a.grantee<>ownerid))) THEN RETURN false;END IF;\n FOREACH nm IN ARRAY ARRAY[''access'',''frame'',''prepare'',''child_scope'',''operation_key'',''location_scope'',''journal_proof'',''native_snapshot'',''bulk_witnesses'',''bulk_validate'',''lot_witnesses'',''lot_validate'',''finish'',''validate'',''budget'',''abandon'',''immutable'',''admission_guard'',''record_guard'',''complete'',''source_seal'',''fingerprint'',''guards'',''require'',''statement_guard'',''terminal_require''] LOOP\n IF NOT EXISTS(SELECT FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname=''catalog_stock_count_''||nm) THEN RETURN false;END IF;\n END LOOP;\n IF NOT EXISTS(SELECT FROM pg_constraint k WHERE k.conrelid=to_regclass(''public.catalog_stock_control_effects'') AND k.confrelid=''public.catalog_stock_count_receipts''::regclass AND k.contype=''f'' AND k.convalidated\n AND(SELECT array_agg(x.attname::text ORDER BY v.ord) FROM unnest(k.conkey) WITH ORDINALITY v(att,ord) JOIN pg_attribute x ON(x.attrelid,x.attnum)=(k.conrelid,v.att))=ARRAY[''tenant_id'',''count_receipt_id'']\n AND(SELECT array_agg(x.attname::text ORDER BY v.ord) FROM unnest(k.confkey) WITH ORDINALITY v(att,ord) JOIN pg_attribute x ON(x.attrelid,x.attnum)=(k.confrelid,v.att))=ARRAY[''tenant_id'',''id'']) THEN RETURN false;END IF;\n IF to_regprocedure(''public.catalog_stock_control_effect_validate(uuid)'') IS NULL OR to_regprocedure(''public.catalog_stock_control_counter_complete()'') IS NULL OR\n position(''PERFORM public.catalog_stock_count_validate(eid);'' IN(SELECT prosrc FROM pg_proc WHERE oid=to_regprocedure(''public.catalog_stock_control_effect_validate(uuid)'')))=0 OR\n position(''FROM public.catalog_stock_count_documents WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year)'' IN(SELECT prosrc FROM pg_proc WHERE oid=to_regprocedure(''public.catalog_stock_control_counter_complete()'')))=0 THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND t.tgenabled IN(''O'',''A'') AND p.pronamespace=''public''::regnamespace AND left(p.proname,20)=''catalog_stock_count_'')<>44 THEN RETURN false;END IF;\n FOREACH nm IN ARRAY ARRAY[''receipts'',''documents'',''rows'',''bin_maps'',''stock_maps'',''layer_maps'',''native_maps'',''move_maps''] LOOP\n  IF NOT EXISTS(SELECT FROM pg_trigger t WHERE t.tgrelid=to_regclass(''public.catalog_stock_count_''||nm)\n   AND t.tgname=''count_statement_before'' AND t.tgtype=6 AND t.tgenabled=''O'' AND NOT t.tgisinternal\n   AND NOT t.tgdeferrable AND NOT t.tginitdeferred AND t.tgqual IS NULL AND t.tgnargs=0\n   AND t.tgfoid=to_regprocedure(''public.catalog_stock_count_statement_guard()'')) OR\n  NOT EXISTS(SELECT FROM pg_trigger t WHERE t.tgrelid=to_regclass(''public.catalog_stock_count_''||nm)\n   AND t.tgname=''count_statement_after'' AND t.tgtype=4 AND t.tgenabled=''O'' AND NOT t.tgisinternal\n   AND NOT t.tgdeferrable AND NOT t.tginitdeferred AND t.tgqual IS NULL AND t.tgnargs=0\n   AND t.tgfoid=to_regprocedure(''public.catalog_stock_count_statement_guard()'')) THEN RETURN false;END IF;\n END LOOP;\n RETURN coalesce((SELECT fingerprint=public.catalog_stock_count_fingerprint() FROM public.catalog_stock_count_manifest WHERE id),false);\nEND $function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"manual_inventory_off_valid":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"manual_inventory_off_valid()","definition":"CREATE OR REPLACE FUNCTION public.manual_inventory_off_valid()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE cert jsonb;ownrole text:=pg_get_userbyid((SELECT proowner FROM pg_proc WHERE oid=''public.manual_inventory_off_valid()''::regprocedure));n text;v jsonb;actual text;bootstrap boolean:=false;BEGIN\n IF to_regclass(''public.manual_inventory_off_certificate'') IS NULL THEN RETURN false;END IF;\n SELECT payload INTO cert FROM manual_inventory_off_certificate WHERE id;\n IF jsonb_typeof(cert) IS DISTINCT FROM ''object'' THEN RETURN false;END IF;\n IF (cert-ARRAY[''profile'',''original152_manifest'',''predecessor_fingerprint'',''predecessor_functions'',''successor_functions'',''successor_fingerprint'',''own_fingerprint'',''predecessor_catalog_functions'',''original160_fingerprint'',''projected_functions''])<>''{}''\n OR cert->''predecessor_functions'' IS DISTINCT FROM $expectedold${\"catalog_stock_control_effect_prepare\":{\"body\":\"\\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;strictids jsonb;eid uuid:=gen_random_uuid();s public.catalog_stock_control_series;d public.warehouse_documents;w uuid;kindj text;yr integer:=extract(year FROM transaction_timestamp());n bigint;num jsonb;f jsonb;old public.catalog_stock_control_effect_admissions;pv public.wms_previews;\\nBEGIN PERFORM public.catalog_stock_control_require();\\n -- No public activation scopes are imposed on ordinary physical callers; their\\n -- actual enclosing source IAM is enlisted by the trusted server adapter.\\n IF uid IS NOT NULL AND NOT EXISTS(SELECT FROM public.memberships WHERE(tenant_id,user_id)=(t,uid) AND role IN(''admin'',''operator'')) THEN RAISE EXCEPTION ''Brak aktualnego operatora fizycznego efektu'' USING ERRCODE=''42501'';END IF;\\n IF b->>''source_kind'' NOT IN(''warehouse_document'',''purchase_receipt'',''dispatch'',''stocktake'',''location_operation'',''wms_movement'',''wms_receipt'',''return'',''wms_opening'',''catalog_import'',''inventory_import'') THEN RAISE EXCEPTION ''Nieznane źródło fizyczne'' USING ERRCODE=''23514'';END IF;\\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''catalog.strict.lifecycle:''||t,0));\\n SELECT coalesce(jsonb_agg(DISTINCT p.catalog_id ORDER BY p.catalog_id),''[]'') INTO strictids FROM public.products p JOIN public.catalog_stock_control_policies h ON(h.tenant_id,h.catalog_id)=(p.tenant_id,p.catalog_id) WHERE p.tenant_id=t AND p.id IN(SELECT v::uuid FROM jsonb_array_elements_text(b->''product_ids'')v);\\n IF jsonb_array_length(strictids)=0 THEN RETURN NULL;END IF;\\n FOR w IN SELECT v::uuid FROM jsonb_array_elements_text(b->''warehouse_ids'')v ORDER BY v LOOP PERFORM public.warehouse_inventory_policy_lock(t,w);END LOOP;\\n PERFORM pg_advisory_xact_lock(hashtextextended(''catalog.strict.quota:''||t,0));\\n SELECT * INTO old FROM public.catalog_stock_control_effect_admissions WHERE(tenant_id,source_kind,source_id)=(t,b->>''source_kind'',(b->>''source_id'')::uuid);\\n IF old.id IS NOT NULL THEN IF old.sealed THEN RETURN NULL;END IF;IF old.txid<>pg_current_xact_id() OR old.actor_id IS DISTINCT FROM uid OR old.api_key_id IS DISTINCT FROM kid OR old.request<>b THEN RAISE EXCEPTION ''Inne przyjęcie fizycznego źródła'' USING ERRCODE=''23514'';END IF;RETURN jsonb_build_object(''id'',old.id,''tenant_id'',t,''source'',b,''strict_catalog_ids'',strictids,''number'',old.number);END IF;\\n IF b->>''source_kind''=''warehouse_document'' THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(t,(b->>''source_id'')::uuid);IF d.id IS NULL OR d.status<>''draft'' THEN RAISE EXCEPTION ''Historyczne źródło nie otrzyma nowego numeru'' USING ERRCODE=''23514'';END IF;kindj:=CASE d.kind WHEN ''receipt'' THEN ''PZ'' WHEN ''transfer'' THEN ''MM'' WHEN ''issue'' THEN ''WZ'' END;IF kindj IS NULL THEN RAISE EXCEPTION ''Pomiar strict wymaga PW/RW'' USING ERRCODE=''23514'';END IF;\\n INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,d.warehouse_id,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;\\n SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,d.warehouse_id,kindj) FOR UPDATE;\\n n:=public.catalog_stock_control_next(t,s.id,yr);\\n num:=jsonb_build_object(''kind'',kindj,''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;\\n IF b->>''source_kind'' IN(''purchase_receipt'',''wms_receipt'') THEN SELECT v::uuid INTO w FROM jsonb_array_elements_text(b->''warehouse_ids'')v;IF jsonb_array_length(b->''warehouse_ids'')<>1 THEN RAISE EXCEPTION ''Przyjęcie dostawy ma jeden rzeczywisty magazyn'' USING ERRCODE=''23514'';END IF;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,''PZ'',''PZ'',''PZ'') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,''PZ'') FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object(''kind'',''PZ'',''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;\\n IF b->>''source_kind''=''wms_movement'' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>''source_id'')::uuid,uid);IF pv.id IS NULL OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.kind NOT IN(''issue'',''transfer'',''bin_move'',''adjustment'') OR b->''product_ids''<>jsonb_build_array(pv.request->''product_id'') OR b->''warehouse_ids''<>(SELECT jsonb_agg(v ORDER BY v#>>''{}'') FROM jsonb_array_elements(jsonb_build_array(pv.request->''warehouse_id'')||CASE WHEN pv.kind=''transfer'' THEN jsonb_build_array(pv.request->''destination_warehouse_id'') ELSE ''[]''::jsonb END)v) THEN RAISE EXCEPTION ''Brak własnego gotowego źródła ruchu WMS lub strict PW/RW'' USING ERRCODE=''23514'';END IF;kindj:=CASE pv.kind WHEN ''issue'' THEN ''WZ'' WHEN ''transfer'' THEN ''MM'' WHEN ''adjustment'' THEN CASE WHEN (pv.request->>''quantity'')::integer>0 THEN ''PW'' ELSE ''RW'' END END;IF kindj IS NOT NULL THEN w:=(pv.request->>''warehouse_id'')::uuid;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,kindj) FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object(''kind'',kindj,''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;END IF;\\n IF b->>''source_kind''=''wms_opening'' AND EXISTS(SELECT FROM public.wms_operations o JOIN public.wms_policies h\\n  ON(h.tenant_id,h.opening_operation_id)=(o.tenant_id,o.id) WHERE o.tenant_id=t AND o.kind=''opening''\\n  AND o.request->>''preview_id''=b->>''source_id'') THEN RETURN NULL;END IF;\\n IF b->>''source_kind''=''wms_opening'' THEN\\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>''source_id'')::uuid,uid);\\n  IF pv.id IS NULL OR pv.kind<>''opening'' OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.policy_version<>0\\n   OR b->''product_ids'' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>''product_id'' v FROM jsonb_array_elements(pv.snapshot->''rows'')r)x)\\n   OR b->''warehouse_ids'' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>''warehouse_id'' v FROM jsonb_array_elements(pv.snapshot->''rows'')r)x)\\n   OR EXISTS(SELECT FROM public.wms_policies WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_lots WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_cost_layers WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_layer_positions WHERE tenant_id=t)\\n  THEN RAISE EXCEPTION ''Otwarcie strict wymaga własnego pełnego źródła WMS OFF'' USING ERRCODE=''23514'';END IF;\\n END IF;\\n f:=public.catalog_stock_control_effect_frame(b);\\n INSERT INTO public.catalog_stock_control_effect_admissions(id,tenant_id,actor_id,api_key_id,source_kind,source_id,request,before_frame,number) VALUES(eid,t,uid,kid,b->>''source_kind'',(b->>''source_id'')::uuid,b,f,num);\\n RETURN jsonb_build_object(''id'',eid,''tenant_id'',t,''source'',b,''strict_catalog_ids'',strictids,''number'',num);END \",\"sha256\":\"8124f34c7893ddf592740b55738b7b48eb67ac1694add340bbe29c0385366044\"},\"catalog_stock_control_effect_validate\":{\"body\":\"\\nDECLARE a public.catalog_stock_control_effect_admissions;e public.catalog_stock_control_effects;f jsonb;kindj text;keyj text;ids jsonb;news jsonb;beforej jsonb;afterj jsonb;x jsonb;priorj jsonb;delta numeric;sumdelta numeric;d public.warehouse_documents;op public.wms_operations;pv public.wms_previews;countj bigint;\\nBEGIN SELECT * INTO a FROM public.catalog_stock_control_effect_admissions WHERE id=eid;IF a.id IS NULL OR a.txid<>pg_current_xact_id() THEN RAISE EXCEPTION ''Brak przyjęcia strict w bieżącej transakcji'' USING ERRCODE=''23514'';END IF;SELECT * INTO e FROM public.catalog_stock_control_effects WHERE(tenant_id,admission_id)=(a.tenant_id,a.id);IF e.admission_id IS NULL THEN RAISE EXCEPTION ''Brak pełnego dokumentu fizycznego efektu'' USING ERRCODE=''23514'';END IF;\\n f:=public.catalog_stock_control_effect_frame(a.request);IF NOT EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions later WHERE later.tenant_id=a.tenant_id AND later.txid=a.txid AND later.id<>a.id AND later.sealed AND later.request->''product_ids''=a.request->''product_ids'' AND later.request->''warehouse_ids''=a.request->''warehouse_ids'' AND later.before_frame=e.after_frame) AND f<>e.after_frame THEN RAISE EXCEPTION ''Zapieczętowany fizyczny efekt zmienił się'' USING ERRCODE=''23514'';END IF;f:=e.after_frame;\\n FOREACH kindj IN ARRAY ARRAY[''stock'',''bin'',''layer''] LOOP keyj:=CASE kindj WHEN ''stock'' THEN ''stock_movement_ids'' WHEN ''bin'' THEN ''location_movement_ids'' ELSE ''layer_movement_ids'' END;\\n ids:=coalesce(e.proof->keyj,''[]'');beforej:=a.before_frame->(kindj||''_journals'');afterj:=f->(kindj||''_journals'');\\n IF EXISTS(SELECT FROM jsonb_array_elements(beforej)b WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(afterj)n WHERE n=b)) THEN RAISE EXCEPTION ''Historia fizyczna została zmieniona'' USING ERRCODE=''23514'';END IF;\\n SELECT coalesce(jsonb_agg(v->''id'' ORDER BY v->>''id''),''[]'') INTO news FROM jsonb_array_elements(afterj)v WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(beforej)o WHERE o->>''id''=v->>''id'');\\n IF news<>(SELECT coalesce(jsonb_agg(v ORDER BY v#>>''{}''),''[]'') FROM jsonb_array_elements(ids)v) OR jsonb_array_length(ids)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(ids)v) THEN RAISE EXCEPTION ''Dowód nie obejmuje wszystkich rzeczywistych ruchów'' USING ERRCODE=''23514'';END IF;END LOOP;\\n -- Every signed cell delta equals the actual new journal sum, including net-zero SKU moves.\\n FOREACH kindj IN ARRAY ARRAY[''stock'',''bins'',''positions''] LOOP\\n WITH old_cells AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,(v->>(CASE WHEN kindj=''stock'' THEN ''on_hand'' ELSE ''quantity'' END))::numeric q FROM jsonb_array_elements(a.before_frame->kindj)v),\\n new_cells AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,(v->>(CASE WHEN kindj=''stock'' THEN ''on_hand'' ELSE ''quantity'' END))::numeric q FROM jsonb_array_elements(f->kindj)v),\\n journals AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,sum((v->>''delta'')::numeric) delta FROM jsonb_array_elements(f->(CASE kindj WHEN ''stock'' THEN ''stock_journals'' WHEN ''bins'' THEN ''bin_journals'' ELSE ''layer_journals'' END))v WHERE v->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->(CASE kindj WHEN ''stock'' THEN ''stock_movement_ids'' WHEN ''bins'' THEN ''location_movement_ids'' ELSE ''layer_movement_ids'' END))) GROUP BY 1,2,3,4),\\n cells AS(SELECT coalesce(n.w,o.w) w,coalesce(n.p,o.p) p,coalesce(n.l,o.l) l,coalesce(n.layer,o.layer) layer,coalesce(n.q,0)-coalesce(o.q,0) delta FROM old_cells o FULL JOIN new_cells n USING(w,p,l,layer))\\n SELECT count(*) INTO countj FROM cells c FULL JOIN journals j USING(w,p,l,layer) WHERE coalesce(c.delta,0)<>coalesce(j.delta,0);\\n IF countj<>0 THEN RAISE EXCEPTION ''Ruch nie odpowiada dokładnemu stanowi komórki'' USING ERRCODE=''23514'';END IF;END LOOP;\\n IF a.source_kind IN(''warehouse_document'',''purchase_receipt'',''wms_movement'',''wms_receipt'') THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(a.tenant_id,(e.proof->>''warehouse_document_id'')::uuid);IF d.id IS NULL OR d.status<>''posted'' OR(a.source_kind=''warehouse_document'' AND d.id<>a.source_id) OR(a.number IS NOT NULL AND d.number<>a.number->>''number'' AND NOT(a.source_kind=''wms_movement'' AND EXISTS(SELECT FROM public.wms_previews wp WHERE(wp.tenant_id,wp.id)=(a.tenant_id,a.source_id) AND wp.kind=''adjustment''))) THEN RAISE EXCEPTION ''Brak rzeczywistego zaksięgowanego dokumentu'' USING ERRCODE=''23514'';END IF;\\n IF EXISTS(SELECT FROM jsonb_array_elements(f->''stock_journals'')v WHERE v->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''stock_movement_ids'')) AND v->>''warehouse_document_id'' IS DISTINCT FROM d.id::text) THEN RAISE EXCEPTION ''Ruch obcego dokumentu'' USING ERRCODE=''23514'';END IF;\\n IF a.source_kind=''purchase_receipt'' AND NOT EXISTS(SELECT FROM public.purchase_receipts pr JOIN public.purchase_orders po ON(po.tenant_id,po.id)=(pr.tenant_id,pr.order_id) WHERE(pr.tenant_id,pr.id,pr.document_id)=(a.tenant_id,a.source_id,d.id) AND pr.id=e.purchase_receipt_id AND po.warehouse_id=d.warehouse_id AND NOT EXISTS(SELECT FROM public.purchase_receipt_lines l WHERE(l.tenant_id,l.receipt_id)=(pr.tenant_id,pr.id) AND NOT EXISTS(SELECT FROM public.warehouse_document_lines dl WHERE(dl.tenant_id,dl.document_id,dl.product_id,dl.quantity,dl.location)=(l.tenant_id,d.id,l.product_id,l.quantity,l.location)))) THEN RAISE EXCEPTION ''Dowód PZ nie odpowiada rzeczywistemu przyjęciu dostawy'' USING ERRCODE=''23514'';END IF;\\n IF a.source_kind IN(''wms_movement'',''wms_receipt'') THEN SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);IF op.id IS NULL OR op.warehouse_document_id IS DISTINCT FROM d.id OR(a.source_kind=''wms_receipt'' AND(op.kind<>''receipt'' OR op.client_key<>a.source_id OR op.purchase_receipt_id IS NOT NULL)) OR(a.source_kind=''wms_movement'' AND op.request->>''preview_id'' IS DISTINCT FROM a.source_id::text) THEN RAISE EXCEPTION ''Dokument nie odpowiada rzeczywistemu źródłu WMS'' USING ERRCODE=''23514'';END IF;IF a.source_kind=''wms_movement'' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id)=(a.tenant_id,a.source_id);IF pv.id IS NULL OR pv.kind<>op.kind OR d.reference<>''WMS/''||pv.id OR d.warehouse_id<>(pv.request->>''warehouse_id'')::uuid THEN RAISE EXCEPTION ''Obcy zapisany plan ruchu WMS'' USING ERRCODE=''23514'';END IF;IF pv.kind=''adjustment'' AND e.proof->''correction_document'' IS DISTINCT FROM public.catalog_stock_control_wms_correction_build(a.id,e.proof) THEN RAISE EXCEPTION ''Niepełny zapisany dokument PW/RW korekty'' USING ERRCODE=''23514'';END IF;END IF;END IF;\\n ELSIF a.source_kind=''wms_opening'' THEN\\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(a.tenant_id,a.source_id,a.actor_id);\\n  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);\\n  IF pv.id IS NULL OR pv.kind<>''opening'' OR NOT pv.ready OR pv.policy_version<>0 OR op.id IS NULL\\n   OR op.kind<>''opening'' OR op.actor_id IS DISTINCT FROM a.actor_id OR op.policy_version<>1\\n   OR op.request->>''preview_id'' IS DISTINCT FROM pv.id::text OR op.request->>''scope_hash'' IS DISTINCT FROM pv.scope_hash\\n   OR op.request->''confirmed'' IS DISTINCT FROM ''true''::jsonb\\n   OR (pv.snapshot->''valuation''->>''unknown_quantity''<>''0'' AND op.request->''ack_unknown_costs'' IS DISTINCT FROM ''true''::jsonb)\\n   OR NOT EXISTS(SELECT FROM public.wms_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,op.id) AND public.catalog_stock_control_owns_xmin(o.xmin))\\n   OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL OR op.order_id IS NOT NULL OR op.return_id IS NOT NULL\\n   OR e.warehouse_document_id IS NOT NULL OR e.location_operation_id IS NOT NULL OR a.number IS NOT NULL\\n   OR a.before_frame->''stock''<>f->''stock'' OR a.before_frame->''bins''<>f->''bins''\\n   OR a.before_frame->''positions''<>''[]''::jsonb\\n   OR e.proof->''stock_movement_ids''<>''[]''::jsonb OR e.proof->''location_movement_ids''<>''[]''::jsonb\\n   OR NOT EXISTS(SELECT FROM public.wms_policies h WHERE h.tenant_id=a.tenant_id AND h.enabled AND h.version=1\\n    AND h.method=''FIFO'' AND h.opening_operation_id=op.id AND h.currency=pv.request->>''currency'' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))\\n  THEN RAISE EXCEPTION ''Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF'' USING ERRCODE=''23514'';END IF;\\n  -- Every positive physical bin in the entire tenant, including nonstrict\\n  -- catalogs, is represented once. Opening never writes stock or a second PZ.\\n  WITH expected AS(SELECT r->>''warehouse_id'' w,r->>''product_id'' p,r->>''location'' l,(r->>''quantity'')::integer q\\n    FROM jsonb_array_elements(pv.snapshot->''rows'')r),\\n   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)\\n  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;\\n  IF countj<>0 THEN RAISE EXCEPTION ''Otwarcie nie obejmuje całego zapasu firmy'' USING ERRCODE=''23514'';END IF;\\n  WITH expected AS(SELECT r->>''warehouse_id'' w,r->>''product_id'' p,r->>''location'' l,(r->>''quantity'')::integer q,\\n    r->>''lot_code'' code,(r->>''unit_cost_minor'')::bigint cost,r->>''currency'' currency FROM jsonb_array_elements(pv.snapshot->''rows'')r),\\n   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency\\n    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)\\n    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)\\n    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin=''opening''\\n     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL\\n     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))\\n  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code\\n    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;\\n  IF countj<>0 OR jsonb_array_length(f->''positions'')<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR jsonb_array_length(e.proof->''layer_movement_ids'')<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR EXISTS(SELECT FROM jsonb_array_elements(f->''layer_journals'')j WHERE j->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''layer_movement_ids''))\\n     AND(j->>''operation_id'' IS DISTINCT FROM op.id::text OR j->>''kind''<>''opening'' OR(j->>''delta'')::integer<=0))\\n  THEN RAISE EXCEPTION ''Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''inventory_import'' THEN PERFORM public.catalog_stock_count_validate(eid);\\n ELSIF a.source_kind=''return'' THEN PERFORM public.catalog_stock_return_validate(eid);\\n ELSIF a.source_kind=''dispatch'' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION ''Brak pełnego automatycznego WZ'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''stocktake'' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION ''Brak pełnego PW/RW'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''location_operation'' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>''kind''=''move'') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->''bin_journals'')j WHERE j->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''location_movement_ids'')) AND j->>''operation_id'' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->''stock'')v WHERE coalesce((v->>''on_hand'')::integer,0) IS DISTINCT FROM(SELECT(o->>''on_hand'')::integer FROM jsonb_array_elements(a.before_frame->''stock'')o WHERE(o->>''warehouse_id'',o->>''product_id'')=(v->>''warehouse_id'',v->>''product_id''))) THEN RAISE EXCEPTION ''Pomiar strict wymaga PW/RW; relokacja wymaga dowodu'' USING ERRCODE=''23514'';END IF;\\n ELSE RAISE EXCEPTION ''Źródło strict wymaga certyfikowanego adaptera dokumentu'' USING ERRCODE=''23514'';END IF;END \",\"sha256\":\"aa3c54fdeee098fb147ae76b48d6197e03e16b162ff880ba0e1fd7c03847cace\"},\"catalog_stock_control_guards\":{\"body\":\" DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid=''public.catalog_stock_control_guards()''::regprocedure);BEGIN\\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace=''public''::regnamespace AND p.proname IN(''catalog_stock_control_xid_claim_guard'',''catalog_stock_control_capture_xid_birth''))<>13 OR\\n  to_regprocedure(''public.catalog_stock_control_owns_xmin(xid)'') IS NULL OR\\n  to_regprocedure(''public.catalog_stock_control_prune_xid_claims()'') IS NULL THEN RETURN false; END IF;\\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''catalog_stock_control_%'' AND relkind=''r'')<>14 THEN RETURN false;END IF;\\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND c.relname LIKE ''catalog_stock_control_%'' AND c.relkind=''r'' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''catalog_stock_control_%'' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\\n RETURN coalesce((SELECT fingerprint=public.catalog_stock_control_fingerprint() FROM public.catalog_stock_control_manifest WHERE id),false);END \",\"sha256\":\"71ae1c60ac7e99bc32e0175f59594d915dbfa6e9aef1a84bb0d349d36a5462b7\"},\"b2b_credit_fingerprint\":{\"body\":\"\\n SELECT md5(jsonb_build_object(\\n ''tables'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''owner'',pg_get_userbyid(c.relowner),''rls'',c.relrowsecurity,''force'',c.relforcerowsecurity,\\n ''acl'',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a),\\n ''cols'',(SELECT jsonb_agg(jsonb_build_array(x.attname,format_type(x.atttypid,x.atttypmod),x.attnotnull,x.attgenerated,x.attidentity,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(ca.grantor),CASE WHEN ca.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,ca.is_grantable) ORDER BY CASE WHEN ca.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,pg_get_userbyid(ca.grantor)::text,ca.is_grantable) FROM aclexplode(x.attacl)ca),pg_get_expr(d.adbin,d.adrelid)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),\\n ''constraints'',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.convalidated,pg_get_constraintdef(k.oid,true)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),\\n ''policies'',(SELECT jsonb_agg(jsonb_build_array(po.polname,(SELECT array_agg(CASE WHEN x=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x)::text END) FROM unnest(po.polroles)x),po.polcmd,pg_get_expr(po.polqual,po.polrelid),pg_get_expr(po.polwithcheck,po.polrelid)) ORDER BY po.polname) FROM pg_policy po WHERE po.polrelid=c.oid),\\n ''indexes'',(SELECT jsonb_agg(jsonb_build_array(i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indrelid=c.oid),\\n ''triggers'',(SELECT jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid,true)) ORDER BY tr.tgname) FROM pg_trigger tr WHERE tr.tgrelid=c.oid AND NOT tr.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND (c.relname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''catalog\\\\_stock\\\\_return\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''catalog\\\\_stock\\\\_control\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'' OR c.relname IN(''local_invoice_series'',''local_invoice_series_commands'',''orders'',''order_items'',''order_merge_claims'',''return_cases'',''documents'',''invoice_plans'',''odoo_invoice_exports'',''users'',''sessions'',''memberships'',''api_keys'',''account_security'',''workspace_security_policies'',''tenants'',''return_items'',''stock_movements'',''stock_location_movements'',''wms_layer_movements'',''wms_cost_layers'',''wms_issue_fragments'',''wms_return_fragments'',''wms_operations'')) AND c.relkind IN(''r'',''p'')),\\n ''functions'',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.provolatile,p.proisstrict,p.proleakproof,p.proparallel,p.prokind,p.proretset,p.prorettype,pg_get_function_identity_arguments(p.oid),pg_get_function_result(p.oid),p.proargmodes,p.proargnames,pg_get_expr(p.proargdefaults,0),(SELECT lanname FROM pg_language WHERE oid=p.prolang),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND ((p.proname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''catalog\\\\_stock\\\\_return\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''catalog\\\\_stock\\\\_control\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''local\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'') OR p.oid IN(SELECT tr.tgfoid FROM pg_trigger tr JOIN pg_class rel ON rel.oid=tr.tgrelid WHERE rel.relnamespace=''public''::regnamespace AND NOT tr.tgisinternal AND rel.relname IN(''orders'',''order_items'',''order_merge_claims'',''return_cases'',''documents'',''invoice_plans'',''odoo_invoice_exports'',''users'',''sessions'',''memberships'',''api_keys'',''account_security'',''workspace_security_policies'',''tenants'')))),\\n ''documents_checks'',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,pg_get_constraintdef(oid,true)) ORDER BY conname) FROM pg_constraint WHERE conrelid=''public.documents''::regclass AND conname IN(''documents_kind_check'',''documents_proforma_local'',''documents_native_invoice'')),\\n ''document_indexes'',(SELECT jsonb_agg(jsonb_build_array(c.relname,i.indisvalid,pg_get_indexdef(i.indexrelid)) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE c.relname IN(''document_order_mode'',''document_demo_number'')),\\n ''parent_triggers'',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid,true)) ORDER BY tgrelid::regclass::text,tgname) FROM pg_trigger WHERE tgfoid IN(SELECT oid FROM pg_proc WHERE pronamespace=''public''::regnamespace AND(proname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'')))\\n )::text) \",\"sha256\":\"eb63a87e7d4dd426474f7f9a4cc08c3acb5a482247f1fdf40dcc21f21015c948\"}}$expectedold$::jsonb OR cert->''successor_functions'' IS DISTINCT FROM $expectednew${\"catalog_stock_control_effect_prepare\":{\"body\":\"\\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;strictids jsonb;eid uuid:=gen_random_uuid();s public.catalog_stock_control_series;d public.warehouse_documents;w uuid;kindj text;yr integer:=extract(year FROM transaction_timestamp());n bigint;num jsonb;f jsonb;old public.catalog_stock_control_effect_admissions;pv public.wms_previews;\\nBEGIN PERFORM public.catalog_stock_control_require();\\n -- No public activation scopes are imposed on ordinary physical callers; their\\n -- actual enclosing source IAM is enlisted by the trusted server adapter.\\n IF uid IS NOT NULL AND NOT EXISTS(SELECT FROM public.memberships WHERE(tenant_id,user_id)=(t,uid) AND role IN(''admin'',''operator'')) THEN RAISE EXCEPTION ''Brak aktualnego operatora fizycznego efektu'' USING ERRCODE=''42501'';END IF;\\n IF b->>''source_kind'' NOT IN(''warehouse_document'',''purchase_receipt'',''dispatch'',''stocktake'',''location_operation'',''wms_movement'',''wms_receipt'',''return'',''wms_opening'',''catalog_import'',''inventory_import'',''manual_off_correction'') THEN RAISE EXCEPTION ''Nieznane źródło fizyczne'' USING ERRCODE=''23514'';END IF;\\n\\n IF b->>''source_kind''=''manual_off_correction'' AND NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma JOIN public.manual_inventory_off_previews mp ON(mp.tenant_id,mp.id)=(ma.tenant_id,ma.preview_id)\\n WHERE(ma.tenant_id,ma.id,ma.actor_id)=(t,(b->>''source_id'')::uuid,uid) AND ma.api_key_id IS NOT DISTINCT FROM kid AND ma.root_xid=pg_current_xact_id()\\n AND b=jsonb_build_object(''source_kind'',''manual_off_correction'',''source_id'',ma.id,''product_ids'',jsonb_build_array(mp.request->''product_id''),''warehouse_ids'',jsonb_build_array(mp.request->''warehouse_id'')))\\n THEN RAISE EXCEPTION ''Manual strict source requires genuine managed parent'' USING ERRCODE=''23514'';END IF;\\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''catalog.strict.lifecycle:''||t,0));\\n SELECT coalesce(jsonb_agg(DISTINCT p.catalog_id ORDER BY p.catalog_id),''[]'') INTO strictids FROM public.products p JOIN public.catalog_stock_control_policies h ON(h.tenant_id,h.catalog_id)=(p.tenant_id,p.catalog_id) WHERE p.tenant_id=t AND p.id IN(SELECT v::uuid FROM jsonb_array_elements_text(b->''product_ids'')v);\\n IF jsonb_array_length(strictids)=0 THEN RETURN NULL;END IF;\\n FOR w IN SELECT v::uuid FROM jsonb_array_elements_text(b->''warehouse_ids'')v ORDER BY v LOOP PERFORM public.warehouse_inventory_policy_lock(t,w);END LOOP;\\n PERFORM pg_advisory_xact_lock(hashtextextended(''catalog.strict.quota:''||t,0));\\n SELECT * INTO old FROM public.catalog_stock_control_effect_admissions WHERE(tenant_id,source_kind,source_id)=(t,b->>''source_kind'',(b->>''source_id'')::uuid);\\n IF old.id IS NOT NULL THEN IF old.sealed THEN RETURN NULL;END IF;IF old.txid<>pg_current_xact_id() OR old.actor_id IS DISTINCT FROM uid OR old.api_key_id IS DISTINCT FROM kid OR old.request<>b THEN RAISE EXCEPTION ''Inne przyjęcie fizycznego źródła'' USING ERRCODE=''23514'';END IF;RETURN jsonb_build_object(''id'',old.id,''tenant_id'',t,''source'',b,''strict_catalog_ids'',strictids,''number'',old.number);END IF;\\n IF b->>''source_kind''=''warehouse_document'' THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(t,(b->>''source_id'')::uuid);IF d.id IS NULL OR d.status<>''draft'' THEN RAISE EXCEPTION ''Historyczne źródło nie otrzyma nowego numeru'' USING ERRCODE=''23514'';END IF;kindj:=CASE d.kind WHEN ''receipt'' THEN ''PZ'' WHEN ''transfer'' THEN ''MM'' WHEN ''issue'' THEN ''WZ'' END;IF kindj IS NULL THEN RAISE EXCEPTION ''Pomiar strict wymaga PW/RW'' USING ERRCODE=''23514'';END IF;\\n INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,d.warehouse_id,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;\\n SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,d.warehouse_id,kindj) FOR UPDATE;\\n n:=public.catalog_stock_control_next(t,s.id,yr);\\n num:=jsonb_build_object(''kind'',kindj,''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;\\n IF b->>''source_kind'' IN(''purchase_receipt'',''wms_receipt'') THEN SELECT v::uuid INTO w FROM jsonb_array_elements_text(b->''warehouse_ids'')v;IF jsonb_array_length(b->''warehouse_ids'')<>1 THEN RAISE EXCEPTION ''Przyjęcie dostawy ma jeden rzeczywisty magazyn'' USING ERRCODE=''23514'';END IF;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,''PZ'',''PZ'',''PZ'') ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,''PZ'') FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object(''kind'',''PZ'',''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;\\n IF b->>''source_kind''=''wms_movement'' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>''source_id'')::uuid,uid);IF pv.id IS NULL OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.kind NOT IN(''issue'',''transfer'',''bin_move'',''adjustment'') OR b->''product_ids''<>jsonb_build_array(pv.request->''product_id'') OR b->''warehouse_ids''<>(SELECT jsonb_agg(v ORDER BY v#>>''{}'') FROM jsonb_array_elements(jsonb_build_array(pv.request->''warehouse_id'')||CASE WHEN pv.kind=''transfer'' THEN jsonb_build_array(pv.request->''destination_warehouse_id'') ELSE ''[]''::jsonb END)v) THEN RAISE EXCEPTION ''Brak własnego gotowego źródła ruchu WMS lub strict PW/RW'' USING ERRCODE=''23514'';END IF;kindj:=CASE pv.kind WHEN ''issue'' THEN ''WZ'' WHEN ''transfer'' THEN ''MM'' WHEN ''adjustment'' THEN CASE WHEN (pv.request->>''quantity'')::integer>0 THEN ''PW'' ELSE ''RW'' END END;IF kindj IS NOT NULL THEN w:=(pv.request->>''warehouse_id'')::uuid;INSERT INTO public.catalog_stock_control_series(id,tenant_id,warehouse_id,kind,name,prefix) VALUES(gen_random_uuid(),t,w,kindj,kindj,kindj) ON CONFLICT(tenant_id,warehouse_id,kind) DO NOTHING;SELECT * INTO s FROM public.catalog_stock_control_series WHERE(tenant_id,warehouse_id,kind)=(t,w,kindj) FOR UPDATE;n:=public.catalog_stock_control_next(t,s.id,yr);num:=jsonb_build_object(''kind'',kindj,''number'',s.prefix||''/''||yr||''/''||(CASE WHEN length(n::text)>=6 THEN n::text ELSE lpad(n::text,6,''0'') END),''series_id'',s.id,''year'',yr,''sequence'',n::text);END IF;END IF;\\n IF b->>''source_kind''=''wms_opening'' AND EXISTS(SELECT FROM public.wms_operations o JOIN public.wms_policies h\\n  ON(h.tenant_id,h.opening_operation_id)=(o.tenant_id,o.id) WHERE o.tenant_id=t AND o.kind=''opening''\\n  AND o.request->>''preview_id''=b->>''source_id'') THEN RETURN NULL;END IF;\\n IF b->>''source_kind''=''wms_opening'' THEN\\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(t,(b->>''source_id'')::uuid,uid);\\n  IF pv.id IS NULL OR pv.kind<>''opening'' OR NOT pv.ready OR pv.expires_at<=clock_timestamp() OR pv.policy_version<>0\\n   OR b->''product_ids'' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>''product_id'' v FROM jsonb_array_elements(pv.snapshot->''rows'')r)x)\\n   OR b->''warehouse_ids'' IS DISTINCT FROM(SELECT jsonb_agg(v ORDER BY v) FROM(SELECT DISTINCT r->>''warehouse_id'' v FROM jsonb_array_elements(pv.snapshot->''rows'')r)x)\\n   OR EXISTS(SELECT FROM public.wms_policies WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_lots WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_cost_layers WHERE tenant_id=t)\\n   OR EXISTS(SELECT FROM public.wms_layer_positions WHERE tenant_id=t)\\n  THEN RAISE EXCEPTION ''Otwarcie strict wymaga własnego pełnego źródła WMS OFF'' USING ERRCODE=''23514'';END IF;\\n END IF;\\n f:=public.catalog_stock_control_effect_frame(b);\\n INSERT INTO public.catalog_stock_control_effect_admissions(id,tenant_id,actor_id,api_key_id,source_kind,source_id,request,before_frame,number) VALUES(eid,t,uid,kid,b->>''source_kind'',(b->>''source_id'')::uuid,b,f,num);\\n RETURN jsonb_build_object(''id'',eid,''tenant_id'',t,''source'',b,''strict_catalog_ids'',strictids,''number'',num);END \",\"sha256\":\"79a6d5339095308abcbe89931ca6bdb23d14be33f36a75928a358e57b24a633f\"},\"catalog_stock_control_effect_validate\":{\"body\":\"\\nDECLARE a public.catalog_stock_control_effect_admissions;e public.catalog_stock_control_effects;f jsonb;kindj text;keyj text;ids jsonb;news jsonb;beforej jsonb;afterj jsonb;x jsonb;priorj jsonb;delta numeric;sumdelta numeric;d public.warehouse_documents;op public.wms_operations;pv public.wms_previews;countj bigint;\\nBEGIN SELECT * INTO a FROM public.catalog_stock_control_effect_admissions WHERE id=eid;IF a.id IS NULL OR a.txid<>pg_current_xact_id() THEN RAISE EXCEPTION ''Brak przyjęcia strict w bieżącej transakcji'' USING ERRCODE=''23514'';END IF;SELECT * INTO e FROM public.catalog_stock_control_effects WHERE(tenant_id,admission_id)=(a.tenant_id,a.id);IF e.admission_id IS NULL THEN RAISE EXCEPTION ''Brak pełnego dokumentu fizycznego efektu'' USING ERRCODE=''23514'';END IF;\\n f:=public.catalog_stock_control_effect_frame(a.request);IF NOT EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions later WHERE later.tenant_id=a.tenant_id AND later.txid=a.txid AND later.id<>a.id AND later.sealed AND later.request->''product_ids''=a.request->''product_ids'' AND later.request->''warehouse_ids''=a.request->''warehouse_ids'' AND later.before_frame=e.after_frame) AND f<>e.after_frame THEN RAISE EXCEPTION ''Zapieczętowany fizyczny efekt zmienił się'' USING ERRCODE=''23514'';END IF;f:=e.after_frame;\\n FOREACH kindj IN ARRAY ARRAY[''stock'',''bin'',''layer''] LOOP keyj:=CASE kindj WHEN ''stock'' THEN ''stock_movement_ids'' WHEN ''bin'' THEN ''location_movement_ids'' ELSE ''layer_movement_ids'' END;\\n ids:=coalesce(e.proof->keyj,''[]'');beforej:=a.before_frame->(kindj||''_journals'');afterj:=f->(kindj||''_journals'');\\n IF EXISTS(SELECT FROM jsonb_array_elements(beforej)b WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(afterj)n WHERE n=b)) THEN RAISE EXCEPTION ''Historia fizyczna została zmieniona'' USING ERRCODE=''23514'';END IF;\\n SELECT coalesce(jsonb_agg(v->''id'' ORDER BY v->>''id''),''[]'') INTO news FROM jsonb_array_elements(afterj)v WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(beforej)o WHERE o->>''id''=v->>''id'');\\n IF news<>(SELECT coalesce(jsonb_agg(v ORDER BY v#>>''{}''),''[]'') FROM jsonb_array_elements(ids)v) OR jsonb_array_length(ids)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(ids)v) THEN RAISE EXCEPTION ''Dowód nie obejmuje wszystkich rzeczywistych ruchów'' USING ERRCODE=''23514'';END IF;END LOOP;\\n -- Every signed cell delta equals the actual new journal sum, including net-zero SKU moves.\\n FOREACH kindj IN ARRAY ARRAY[''stock'',''bins'',''positions''] LOOP\\n WITH old_cells AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,(v->>(CASE WHEN kindj=''stock'' THEN ''on_hand'' ELSE ''quantity'' END))::numeric q FROM jsonb_array_elements(a.before_frame->kindj)v),\\n new_cells AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,(v->>(CASE WHEN kindj=''stock'' THEN ''on_hand'' ELSE ''quantity'' END))::numeric q FROM jsonb_array_elements(f->kindj)v),\\n journals AS(SELECT v->>''warehouse_id'' w,v->>''product_id'' p,CASE WHEN kindj=''stock'' THEN '''' ELSE v->>''location'' END l,CASE WHEN kindj=''positions'' THEN v->>''layer_id'' ELSE '''' END layer,sum((v->>''delta'')::numeric) delta FROM jsonb_array_elements(f->(CASE kindj WHEN ''stock'' THEN ''stock_journals'' WHEN ''bins'' THEN ''bin_journals'' ELSE ''layer_journals'' END))v WHERE v->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->(CASE kindj WHEN ''stock'' THEN ''stock_movement_ids'' WHEN ''bins'' THEN ''location_movement_ids'' ELSE ''layer_movement_ids'' END))) GROUP BY 1,2,3,4),\\n cells AS(SELECT coalesce(n.w,o.w) w,coalesce(n.p,o.p) p,coalesce(n.l,o.l) l,coalesce(n.layer,o.layer) layer,coalesce(n.q,0)-coalesce(o.q,0) delta FROM old_cells o FULL JOIN new_cells n USING(w,p,l,layer))\\n SELECT count(*) INTO countj FROM cells c FULL JOIN journals j USING(w,p,l,layer) WHERE coalesce(c.delta,0)<>coalesce(j.delta,0);\\n IF countj<>0 THEN RAISE EXCEPTION ''Ruch nie odpowiada dokładnemu stanowi komórki'' USING ERRCODE=''23514'';END IF;END LOOP;\\n IF a.source_kind IN(''warehouse_document'',''purchase_receipt'',''wms_movement'',''wms_receipt'') THEN SELECT * INTO d FROM public.warehouse_documents WHERE(tenant_id,id)=(a.tenant_id,(e.proof->>''warehouse_document_id'')::uuid);IF d.id IS NULL OR d.status<>''posted'' OR(a.source_kind=''warehouse_document'' AND d.id<>a.source_id) OR(a.number IS NOT NULL AND d.number<>a.number->>''number'' AND NOT(a.source_kind=''wms_movement'' AND EXISTS(SELECT FROM public.wms_previews wp WHERE(wp.tenant_id,wp.id)=(a.tenant_id,a.source_id) AND wp.kind=''adjustment''))) THEN RAISE EXCEPTION ''Brak rzeczywistego zaksięgowanego dokumentu'' USING ERRCODE=''23514'';END IF;\\n IF EXISTS(SELECT FROM jsonb_array_elements(f->''stock_journals'')v WHERE v->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''stock_movement_ids'')) AND v->>''warehouse_document_id'' IS DISTINCT FROM d.id::text) THEN RAISE EXCEPTION ''Ruch obcego dokumentu'' USING ERRCODE=''23514'';END IF;\\n IF a.source_kind=''purchase_receipt'' AND NOT EXISTS(SELECT FROM public.purchase_receipts pr JOIN public.purchase_orders po ON(po.tenant_id,po.id)=(pr.tenant_id,pr.order_id) WHERE(pr.tenant_id,pr.id,pr.document_id)=(a.tenant_id,a.source_id,d.id) AND pr.id=e.purchase_receipt_id AND po.warehouse_id=d.warehouse_id AND NOT EXISTS(SELECT FROM public.purchase_receipt_lines l WHERE(l.tenant_id,l.receipt_id)=(pr.tenant_id,pr.id) AND NOT EXISTS(SELECT FROM public.warehouse_document_lines dl WHERE(dl.tenant_id,dl.document_id,dl.product_id,dl.quantity,dl.location)=(l.tenant_id,d.id,l.product_id,l.quantity,l.location)))) THEN RAISE EXCEPTION ''Dowód PZ nie odpowiada rzeczywistemu przyjęciu dostawy'' USING ERRCODE=''23514'';END IF;\\n IF a.source_kind IN(''wms_movement'',''wms_receipt'') THEN SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);IF op.id IS NULL OR op.warehouse_document_id IS DISTINCT FROM d.id OR(a.source_kind=''wms_receipt'' AND(op.kind<>''receipt'' OR op.client_key<>a.source_id OR op.purchase_receipt_id IS NOT NULL)) OR(a.source_kind=''wms_movement'' AND op.request->>''preview_id'' IS DISTINCT FROM a.source_id::text) THEN RAISE EXCEPTION ''Dokument nie odpowiada rzeczywistemu źródłu WMS'' USING ERRCODE=''23514'';END IF;IF a.source_kind=''wms_movement'' THEN SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id)=(a.tenant_id,a.source_id);IF pv.id IS NULL OR pv.kind<>op.kind OR d.reference<>''WMS/''||pv.id OR d.warehouse_id<>(pv.request->>''warehouse_id'')::uuid THEN RAISE EXCEPTION ''Obcy zapisany plan ruchu WMS'' USING ERRCODE=''23514'';END IF;IF pv.kind=''adjustment'' AND e.proof->''correction_document'' IS DISTINCT FROM public.catalog_stock_control_wms_correction_build(a.id,e.proof) THEN RAISE EXCEPTION ''Niepełny zapisany dokument PW/RW korekty'' USING ERRCODE=''23514'';END IF;END IF;END IF;\\n ELSIF a.source_kind=''wms_opening'' THEN\\n  SELECT * INTO pv FROM public.wms_previews WHERE(tenant_id,id,actor_id)=(a.tenant_id,a.source_id,a.actor_id);\\n  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(a.tenant_id,e.operation_id);\\n  IF pv.id IS NULL OR pv.kind<>''opening'' OR NOT pv.ready OR pv.policy_version<>0 OR op.id IS NULL\\n   OR op.kind<>''opening'' OR op.actor_id IS DISTINCT FROM a.actor_id OR op.policy_version<>1\\n   OR op.request->>''preview_id'' IS DISTINCT FROM pv.id::text OR op.request->>''scope_hash'' IS DISTINCT FROM pv.scope_hash\\n   OR op.request->''confirmed'' IS DISTINCT FROM ''true''::jsonb\\n   OR (pv.snapshot->''valuation''->>''unknown_quantity''<>''0'' AND op.request->''ack_unknown_costs'' IS DISTINCT FROM ''true''::jsonb)\\n   OR NOT EXISTS(SELECT FROM public.wms_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,op.id) AND public.catalog_stock_control_owns_xmin(o.xmin))\\n   OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL OR op.order_id IS NOT NULL OR op.return_id IS NOT NULL\\n   OR e.warehouse_document_id IS NOT NULL OR e.location_operation_id IS NOT NULL OR a.number IS NOT NULL\\n   OR a.before_frame->''stock''<>f->''stock'' OR a.before_frame->''bins''<>f->''bins''\\n   OR a.before_frame->''positions''<>''[]''::jsonb\\n   OR e.proof->''stock_movement_ids''<>''[]''::jsonb OR e.proof->''location_movement_ids''<>''[]''::jsonb\\n   OR NOT EXISTS(SELECT FROM public.wms_policies h WHERE h.tenant_id=a.tenant_id AND h.enabled AND h.version=1\\n    AND h.method=''FIFO'' AND h.opening_operation_id=op.id AND h.currency=pv.request->>''currency'' AND h.exponent=2 AND public.catalog_stock_control_owns_xmin(h.xmin))\\n  THEN RAISE EXCEPTION ''Otwarcie warstw nie odpowiada rzeczywistemu źródłu WMS OFF'' USING ERRCODE=''23514'';END IF;\\n  -- Every positive physical bin in the entire tenant, including nonstrict\\n  -- catalogs, is represented once. Opening never writes stock or a second PZ.\\n  WITH expected AS(SELECT r->>''warehouse_id'' w,r->>''product_id'' p,r->>''location'' l,(r->>''quantity'')::integer q\\n    FROM jsonb_array_elements(pv.snapshot->''rows'')r),\\n   physical AS(SELECT warehouse_id::text w,product_id::text p,location l,quantity q FROM public.stock_locations WHERE tenant_id=a.tenant_id AND quantity>0)\\n  SELECT count(*) INTO countj FROM expected FULL JOIN physical USING(w,p,l) WHERE expected.q IS DISTINCT FROM physical.q;\\n  IF countj<>0 THEN RAISE EXCEPTION ''Otwarcie nie obejmuje całego zapasu firmy'' USING ERRCODE=''23514'';END IF;\\n  WITH expected AS(SELECT r->>''warehouse_id'' w,r->>''product_id'' p,r->>''location'' l,(r->>''quantity'')::integer q,\\n    r->>''lot_code'' code,(r->>''unit_cost_minor'')::bigint cost,r->>''currency'' currency FROM jsonb_array_elements(pv.snapshot->''rows'')r),\\n   actual AS(SELECT pos.warehouse_id::text w,pos.product_id::text p,pos.location l,pos.quantity q,lot.lot_code code,cl.unit_cost_minor cost,cl.currency\\n    FROM public.wms_layer_positions pos JOIN public.wms_cost_layers cl ON(cl.tenant_id,cl.id,cl.product_id)=(pos.tenant_id,pos.layer_id,pos.product_id)\\n    JOIN public.wms_lots lot ON(lot.tenant_id,lot.id,lot.product_id)=(cl.tenant_id,cl.lot_id,cl.product_id)\\n    WHERE pos.tenant_id=a.tenant_id AND cl.operation_id=op.id AND lot.operation_id=op.id AND lot.origin=''opening''\\n     AND pos.reserved=0 AND cl.quantity_received=pos.quantity AND cl.exponent=2 AND cl.warehouse_document_id IS NULL AND cl.purchase_receipt_id IS NULL\\n     AND public.catalog_stock_control_owns_xmin(pos.xmin) AND public.catalog_stock_control_owns_xmin(cl.xmin) AND public.catalog_stock_control_owns_xmin(lot.xmin))\\n  SELECT count(*) INTO countj FROM expected FULL JOIN actual USING(w,p,l) WHERE expected.q IS DISTINCT FROM actual.q OR expected.code IS DISTINCT FROM actual.code\\n    OR expected.cost IS DISTINCT FROM actual.cost OR expected.currency IS DISTINCT FROM actual.currency;\\n  IF countj<>0 OR jsonb_array_length(f->''positions'')<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR(SELECT count(*) FROM public.wms_lots WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR(SELECT count(*) FROM public.wms_cost_layers WHERE tenant_id=a.tenant_id)<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR jsonb_array_length(e.proof->''layer_movement_ids'')<>jsonb_array_length(pv.snapshot->''rows'')\\n   OR EXISTS(SELECT FROM jsonb_array_elements(f->''layer_journals'')j WHERE j->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''layer_movement_ids''))\\n     AND(j->>''operation_id'' IS DISTINCT FROM op.id::text OR j->>''kind''<>''opening'' OR(j->>''delta'')::integer<=0))\\n  THEN RAISE EXCEPTION ''Otwarcie nie odtwarza dokładnych partii, ilości i kosztów źródła'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''inventory_import'' THEN PERFORM public.catalog_stock_count_validate(eid);\\n ELSIF a.source_kind=''return'' THEN PERFORM public.catalog_stock_return_validate(eid);\\n ELSIF a.source_kind=''dispatch'' THEN IF NOT EXISTS(SELECT FROM public.warehouse_wz_issuer_receipts r WHERE r.tenant_id=a.tenant_id AND r.shipment_id=a.source_id AND r.id=e.dispatch_receipt_id AND EXISTS(SELECT FROM public.warehouse_wz_issuer_admissions wa WHERE(wa.tenant_id,wa.id,wa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION ''Brak pełnego automatycznego WZ'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''stocktake'' THEN IF NOT EXISTS(SELECT FROM public.stocktake_adjustment_receipts r WHERE r.tenant_id=a.tenant_id AND r.id=a.source_id AND r.id=e.adjustment_receipt_id AND EXISTS(SELECT FROM public.stocktake_adjustment_admissions sa WHERE(sa.tenant_id,sa.id,sa.txid)=(r.tenant_id,r.id,pg_current_xact_id()))) THEN RAISE EXCEPTION ''Brak pełnego PW/RW'' USING ERRCODE=''23514'';END IF;\\n ELSIF a.source_kind=''location_operation'' THEN IF NOT EXISTS(SELECT FROM public.stock_location_operations o WHERE(o.tenant_id,o.id)=(a.tenant_id,a.source_id) AND o.id=e.location_operation_id AND public.catalog_stock_control_owns_xmin(o.xmin) AND o.result->>''kind''=''move'') OR e.operation_id IS NOT NULL OR EXISTS(SELECT FROM jsonb_array_elements(f->''bin_journals'')j WHERE j->''id'' IN(SELECT value FROM jsonb_array_elements(e.proof->''location_movement_ids'')) AND j->>''operation_id'' IS DISTINCT FROM a.source_id::text) OR EXISTS(SELECT FROM jsonb_array_elements(f->''stock'')v WHERE coalesce((v->>''on_hand'')::integer,0) IS DISTINCT FROM(SELECT(o->>''on_hand'')::integer FROM jsonb_array_elements(a.before_frame->''stock'')o WHERE(o->>''warehouse_id'',o->>''product_id'')=(v->>''warehouse_id'',v->>''product_id''))) THEN RAISE EXCEPTION ''Pomiar strict wymaga PW/RW; relokacja wymaga dowodu'' USING ERRCODE=''23514'';END IF;\\n\\n ELSIF a.source_kind=''manual_off_correction'' THEN\\n IF e.proof<>jsonb_build_object(''manual_receipt_id'',a.source_id,''stock_movement_ids'',jsonb_build_array((SELECT stock_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),\\n ''location_movement_ids'',jsonb_build_array((SELECT location_movement_id FROM public.manual_inventory_off_receipts WHERE(tenant_id,id)=(a.tenant_id,a.source_id))),''layer_movement_ids'',''[]''::jsonb)\\n OR a.number IS NOT NULL OR e.warehouse_document_id IS NOT NULL OR e.operation_id IS NOT NULL OR e.purchase_receipt_id IS NOT NULL OR e.dispatch_receipt_id IS NOT NULL OR e.adjustment_receipt_id IS NOT NULL OR e.location_operation_id IS NOT NULL\\n OR NOT EXISTS(SELECT FROM public.manual_inventory_off_admissions ma WHERE(ma.tenant_id,ma.id,ma.strict_effect_id,ma.actor_id)=(a.tenant_id,a.source_id,a.id,a.actor_id) AND ma.api_key_id IS NOT DISTINCT FROM a.api_key_id AND ma.root_xid=a.txid)\\n THEN RAISE EXCEPTION ''Manual strict proof does not bind genuine parent'' USING ERRCODE=''23514'';END IF;\\n -- Parent validation excludes the strict-sealed predicate until effect_finish seals.\\n PERFORM public.manual_inventory_off_validate(a.source_id,false);\\n ELSE RAISE EXCEPTION ''Źródło strict wymaga certyfikowanego adaptera dokumentu'' USING ERRCODE=''23514'';END IF;END \",\"sha256\":\"72a340b76487f8c5615720219741ed3d7faa4d486427db21b587a7036fd2ad99\"},\"catalog_stock_control_guards\":{\"body\":\" DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid=''public.catalog_stock_control_guards()''::regprocedure);BEGIN\\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace=''public''::regnamespace AND p.proname IN(''catalog_stock_control_xid_claim_guard'',''catalog_stock_control_capture_xid_birth''))<>13 OR\\n  to_regprocedure(''public.catalog_stock_control_owns_xmin(xid)'') IS NULL OR\\n  to_regprocedure(''public.catalog_stock_control_prune_xid_claims()'') IS NULL THEN RETURN false; END IF;\\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''catalog_stock_control_%'' AND relkind=''r'')<>14 THEN RETURN false;END IF;\\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND c.relname LIKE ''catalog_stock_control_%'' AND c.relkind=''r'' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''catalog_stock_control_%'' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\\n RETURN public.manual_inventory_off_valid();END \",\"sha256\":\"ef9c31fbabca36776256efe76dcd16265c9f742ce4a64cbd7cc000c056baf225\"},\"b2b_credit_fingerprint\":{\"body\":\"\\n SELECT CASE WHEN public.manual_inventory_off_projection_valid() THEN (SELECT md5(jsonb_build_object(\\n ''tables'',(SELECT jsonb_agg(jsonb_build_object(''name'',c.relname,''owner'',pg_get_userbyid(c.relowner),''rls'',c.relrowsecurity,''force'',c.relforcerowsecurity,\\n ''acl'',(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a),\\n ''cols'',(SELECT jsonb_agg(jsonb_build_array(x.attname,format_type(x.atttypid,x.atttypmod),x.attnotnull,x.attgenerated,x.attidentity,(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(ca.grantor),CASE WHEN ca.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,ca.is_grantable) ORDER BY CASE WHEN ca.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(ca.grantee)::text END,ca.privilege_type,pg_get_userbyid(ca.grantor)::text,ca.is_grantable) FROM aclexplode(x.attacl)ca),pg_get_expr(d.adbin,d.adrelid)) ORDER BY x.attnum) FROM pg_attribute x LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(x.attrelid,x.attnum) WHERE x.attrelid=c.oid AND x.attnum>0 AND NOT x.attisdropped),\\n ''constraints'',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.convalidated,pg_get_constraintdef(k.oid,true)) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=c.oid),\\n ''policies'',(SELECT jsonb_agg(jsonb_build_array(po.polname,(SELECT array_agg(CASE WHEN x=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x)::text END ORDER BY CASE WHEN x=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(x)::text END) FROM unnest(po.polroles)x),po.polcmd,pg_get_expr(po.polqual,po.polrelid),pg_get_expr(po.polwithcheck,po.polrelid)) ORDER BY po.polname) FROM pg_policy po WHERE po.polrelid=c.oid),\\n ''indexes'',(SELECT jsonb_agg(jsonb_build_array(i.indisvalid,i.indisready,pg_get_indexdef(i.indexrelid)) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indrelid=c.oid),\\n ''triggers'',(SELECT jsonb_agg(jsonb_build_array(tr.tgname,tr.tgenabled,pg_get_triggerdef(tr.oid,true)) ORDER BY tr.tgname) FROM pg_trigger tr WHERE tr.tgrelid=c.oid AND NOT tr.tgisinternal)) ORDER BY c.relname) FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND (c.relname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''catalog\\\\_stock\\\\_return\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''catalog\\\\_stock\\\\_control\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR c.relname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'' OR c.relname IN(''local_invoice_series'',''local_invoice_series_commands'',''orders'',''order_items'',''order_merge_claims'',''return_cases'',''documents'',''invoice_plans'',''odoo_invoice_exports'',''users'',''sessions'',''memberships'',''api_keys'',''account_security'',''workspace_security_policies'',''tenants'',''return_items'',''stock_movements'',''stock_location_movements'',''wms_layer_movements'',''wms_cost_layers'',''wms_issue_fragments'',''wms_return_fragments'',''wms_operations'')) AND c.relkind IN(''r'',''p'')),\\n ''functions'',(SELECT jsonb_agg(jsonb_build_array(p.oid::regprocedure::text,public.manual_inventory_off_projected_definition(p.oid),pg_get_userbyid(p.proowner),p.provolatile,p.proisstrict,p.proleakproof,p.proparallel,p.prokind,p.proretset,p.prorettype,pg_get_function_identity_arguments(p.oid),pg_get_function_result(p.oid),p.proargmodes,p.proargnames,pg_get_expr(p.proargdefaults,0),(SELECT lanname FROM pg_language WHERE oid=p.prolang),(SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee)::text END,a.privilege_type,pg_get_userbyid(a.grantor)::text,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND ((p.proname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''catalog\\\\_stock\\\\_return\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''catalog\\\\_stock\\\\_control\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''local\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR p.proname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'') OR p.oid IN(SELECT tr.tgfoid FROM pg_trigger tr JOIN pg_class rel ON rel.oid=tr.tgrelid WHERE rel.relnamespace=''public''::regnamespace AND NOT tr.tgisinternal AND rel.relname IN(''orders'',''order_items'',''order_merge_claims'',''return_cases'',''documents'',''invoice_plans'',''odoo_invoice_exports'',''users'',''sessions'',''memberships'',''api_keys'',''account_security'',''workspace_security_policies'',''tenants'')))),\\n ''documents_checks'',(SELECT jsonb_agg(jsonb_build_array(conname,convalidated,pg_get_constraintdef(oid,true)) ORDER BY conname) FROM pg_constraint WHERE conrelid=''public.documents''::regclass AND conname IN(''documents_kind_check'',''documents_proforma_local'',''documents_native_invoice'')),\\n ''document_indexes'',(SELECT jsonb_agg(jsonb_build_array(c.relname,i.indisvalid,pg_get_indexdef(i.indexrelid)) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE c.relname IN(''document_order_mode'',''document_demo_number'')),\\n ''parent_triggers'',(SELECT jsonb_agg(jsonb_build_array(tgname,tgenabled,pg_get_triggerdef(oid,true)) ORDER BY tgrelid::regclass::text,tgname) FROM pg_trigger WHERE tgfoid IN(SELECT oid FROM pg_proc WHERE pronamespace=''public''::regnamespace AND(proname LIKE ''b2b\\\\_credit\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''b2b\\\\_invoice\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''fa3\\\\_draft\\\\_%'' ESCAPE ''\\\\'' OR proname LIKE ''b2b\\\\_dropship\\\\_%'' ESCAPE ''\\\\'')))\\n )::text)) ELSE NULL END\\n\",\"sha256\":\"9e3766d47014f65190e470b4aa4ac70d54bc96ce094493408480a41026564a0b\"}}$expectednew$::jsonb OR cert->>''profile''<>''152-original-manual-off-pw-rw/v1'' OR jsonb_typeof(cert->''predecessor_functions'') IS DISTINCT FROM ''object'' OR jsonb_typeof(cert->''successor_functions'') IS DISTINCT FROM ''object''\n OR cert->''original152_manifest'' IS DISTINCT FROM(SELECT to_jsonb(m) FROM catalog_stock_control_manifest m WHERE id)\n OR cert->>''predecessor_fingerprint'' IS DISTINCT FROM cert#>>''{original152_manifest,fingerprint}''\n OR cert->>''predecessor_fingerprint'' IS DISTINCT FROM manual_inventory_off_original152_fingerprint()\n OR cert->''predecessor_catalog_functions'' IS DISTINCT FROM manual_inventory_off_catalog_functions(true)\n OR cert->>''successor_fingerprint'' IS DISTINCT FROM catalog_stock_control_fingerprint()\n OR cert->>''own_fingerprint'' IS DISTINCT FROM manual_inventory_off_fingerprint()\n OR NOT manual_inventory_off_projection_valid()\n OR cert->>''original160_fingerprint'' IS DISTINCT FROM b2b_credit_fingerprint() THEN RETURN false;END IF;\n FOR n,v IN SELECT key,value FROM jsonb_each(cert->''successor_functions'') LOOP\n SELECT prosrc INTO actual FROM pg_proc WHERE oid=(''public.''||n||CASE n WHEN ''catalog_stock_control_effect_prepare'' THEN ''(uuid,uuid,jsonb)'' WHEN ''catalog_stock_control_effect_validate'' THEN ''(uuid)'' ELSE ''()'' END)::regprocedure;\n IF actual IS DISTINCT FROM v->>''body'' THEN RETURN false;END IF;END LOOP;\n IF EXISTS(SELECT FROM migrations WHERE name=''169_manual_inventory_off'') THEN RETURN true;END IF;\n IF current_user=ownrole AND session_user=ownrole AND to_regclass(''pg_temp.manual_inventory_off_install_basis'') IS NOT NULL THEN\n SELECT EXISTS(SELECT FROM pg_temp.manual_inventory_off_install_basis b WHERE b.owner_name=ownrole AND b.root_xid=pg_current_xact_id()::text AND b.start_at=transaction_timestamp() AND b.backend_pid=pg_backend_pid()\n AND b.original152_manifest=cert->''original152_manifest'' AND b.changed_functions=cert->''predecessor_functions'') INTO bootstrap;END IF;RETURN bootstrap;\nEXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN RETURN false;END$function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"warehouse_wz_issuer_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"warehouse_wz_issuer_guards()","definition":"CREATE OR REPLACE FUNCTION public.warehouse_wz_issuer_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE expected text;BEGIN\n IF NOT public.warehouse_wz_issuer_installed() THEN RETURN false;END IF;\n IF to_regprocedure(''public.warehouse_automatic_wz_guards()'') IS NULL OR NOT public.warehouse_automatic_wz_guards() THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace=''public''::regnamespace AND c.relname=ANY(ARRAY[''orders'',''order_items'',''shipments'',''reservations'',''reservation_locations'',''stock'',''stock_locations'',''wms_reservation_layers'',''wms_layer_positions'',''stock_movements'',''stock_location_movements'',''wms_operations'',''wms_issue_fragments'',''wms_layer_movements''])\n  AND t.tgname=''warehouse_wz_issuer_source_seal'' AND t.tgfoid=''public.warehouse_wz_issuer_source_seal()''::regprocedure AND t.tgtype=31 AND t.tgenabled=''O'' AND NOT t.tgisinternal AND t.tgqual IS NULL AND t.tgargs=''\\x''::bytea AND t.tgattr::text='''')<>14 THEN RETURN false;END IF;\n IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) a WHERE c.relnamespace=''public''::regnamespace AND c.relkind=''r'' AND c.relname LIKE ''warehouse_wz_issuer_%'' AND a.grantee<>c.relowner)\n  OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_attribute b ON b.attrelid=c.oid CROSS JOIN LATERAL aclexplode(b.attacl) a WHERE c.relnamespace=''public''::regnamespace AND c.relname LIKE ''warehouse_wz_issuer_%'' AND a.grantee<>c.relowner)\n  OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''warehouse_wz_issuer_%'' AND a.grantee<>p.proowner) THEN RETURN false;END IF;\n SELECT fingerprint INTO expected FROM public.warehouse_wz_issuer_manifest WHERE singleton;\n RETURN expected IS NOT NULL AND public.parcel_physical_wz_valid();\nEXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN RETURN false;\nEND $function$\n","volatility":"s","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"catalog_stock_return_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"catalog_stock_return_guards()","definition":"CREATE OR REPLACE FUNCTION public.catalog_stock_return_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid=''public.catalog_stock_return_guards()''::regprocedure);\nBEGIN\n -- Separate statement avoids planning a call to an absent optional phase delegate.\n IF to_regprocedure(''public.catalog_stock_legacy_group_guards()'') IS NULL THEN RETURN false;END IF;\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_legacy_group_guards() OR\n  (SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''catalog_stock_return_%'' AND relkind=''r'')<>8 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND c.relname LIKE ''catalog_stock_return_%'' AND c.relkind=''r'' AND\n  (c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a WHERE a.grantee<>ownerid) OR\n   EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR\n  EXISTS(SELECT FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''catalog_stock_return_%'' AND\n   (p.proowner<>ownerid OR NOT p.prosecdef OR EXISTS(SELECT FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a WHERE a.grantee<>ownerid))) THEN RETURN false;END IF;\n -- The parent manifest pins the complete implementations of both delegates;\n -- this non-recursive guard also checks their installed, explicit wiring.\n IF to_regprocedure(''public.catalog_stock_control_effect_validate(uuid)'') IS NULL OR\n    to_regprocedure(''public.catalog_stock_control_counter_complete()'') IS NULL THEN RETURN false;END IF;\n IF position(''PERFORM public.catalog_stock_return_validate(eid);'' IN(SELECT prosrc FROM pg_proc WHERE oid=''public.catalog_stock_control_effect_validate(uuid)''::regprocedure))=0 OR\n    position(''FROM public.catalog_stock_return_documents WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year)'' IN(SELECT prosrc FROM pg_proc WHERE oid=''public.catalog_stock_control_counter_complete()''::regprocedure))=0 THEN RETURN false;END IF;\n RETURN coalesce((SELECT fingerprint=public.catalog_stock_return_fingerprint() FROM public.catalog_stock_return_manifest WHERE id),false);\nEND $function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"credit_source_upgrade_valid":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"credit_source_upgrade_valid()","definition":"CREATE OR REPLACE FUNCTION public.credit_source_upgrade_valid()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE c record;tab text;sig text;BEGIN\n IF EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''financial_return_''))\n OR EXISTS(SELECT FROM pg_proc WHERE pronamespace=''public''::regnamespace AND starts_with(proname,''financial_return_''))\n OR EXISTS(SELECT FROM pg_trigger WHERE starts_with(tgname,''financial_return_''))\n OR EXISTS(SELECT FROM migrations WHERE name=''162_financial_return'') THEN\n  IF to_regprocedure(''public.financial_return_upgrade_valid()'') IS NULL THEN RETURN false;END IF;\n  RETURN financial_return_upgrade_valid();\n END IF;\n IF current_setting(''session_replication_role'')<>''origin'' THEN RETURN false;END IF;\n FOREACH tab IN ARRAY ARRAY[''migrations'',''local_invoice_manifest'',''fa3_draft_manifest'',''b2b_invoice_upgrade'',''b2b_credit_upgrade'',''credit_source_upgrade_certificate''] LOOP IF to_regclass(''public.''||tab) IS NULL THEN RETURN false;END IF;END LOOP;\n FOREACH sig IN ARRAY ARRAY[''local_invoice_fingerprint()'',''fa3_draft_fingerprint()'',''b2b_invoice_fingerprint()'',''b2b_credit_fingerprint()'',''b2b_credit_basis(uuid,uuid)'',''b2b_credit_upgrade_valid()'',''credit_source_upgrade_context()'',''credit_source_upgrade_fingerprint()'',''credit_source_upgrade_valid()'',''credit_source_upgrade_guard()''] LOOP IF to_regprocedure(''public.''||sig) IS NULL THEN RETURN false;END IF;END LOOP;\n IF to_regclass(''public.document_order_mode'') IS NULL OR to_regclass(''public.document_return_mode'') IS NULL THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''credit\\_source\\_upgrade\\_%'' ESCAPE ''\\'')<>2\n OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''credit\\_source\\_upgrade\\_%'' ESCAPE ''\\'' AND NOT((relname=''credit_source_upgrade_certificate'' AND relkind=''r'') OR(relname=''credit_source_upgrade_certificate_pkey'' AND relkind=''i'')))\n OR(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''credit\\_source\\_upgrade\\_%'' ESCAPE ''\\'' AND relkind IN(''r'',''p''))<>1\n OR NOT EXISTS(SELECT FROM pg_class WHERE oid=''public.credit_source_upgrade_certificate''::regclass AND relkind=''r'' AND relrowsecurity AND relforcerowsecurity)\n OR(SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname LIKE ''credit\\_source\\_upgrade\\_%'' ESCAPE ''\\'')<>4\n OR(SELECT count(*) FROM pg_trigger WHERE tgname LIKE ''credit\\_source\\_upgrade\\_%'' ESCAPE ''\\'')<>1\n OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgname=''credit_source_upgrade_guard'' AND tgrelid=''public.credit_source_upgrade_certificate''::regclass AND tgfoid=''public.credit_source_upgrade_guard()''::regprocedure AND NOT tgisinternal AND tgenabled=''O'' AND NOT tgdeferrable) THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM migrations WHERE name=''160_b2b_credit'') OR(SELECT count(*) FROM credit_source_upgrade_certificate)<>1\n OR(SELECT count(*) FROM local_invoice_manifest)<>1 OR(SELECT count(*) FROM fa3_draft_manifest)<>1 OR(SELECT count(*) FROM b2b_invoice_upgrade)<>1 OR(SELECT count(*) FROM b2b_credit_upgrade)<>1 THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM migrations WHERE name=''161_credit_source'') AND NOT credit_source_upgrade_context() THEN RETURN false;END IF;\n SELECT * INTO c FROM credit_source_upgrade_certificate WHERE id;\n RETURN coalesce(c.profile=''160-original-to161-empty-source/v1''\n AND c.original=jsonb_build_object(''157'',(SELECT to_jsonb(m) FROM local_invoice_manifest m WHERE id),''158'',(SELECT to_jsonb(m) FROM fa3_draft_manifest m WHERE id),''159'',(SELECT to_jsonb(m) FROM b2b_invoice_upgrade m WHERE id),''160'',(SELECT to_jsonb(m) FROM b2b_credit_upgrade m WHERE id))\n AND c.predecessors=jsonb_build_object(''157'',c.original#>>''{160,successor157}'',''158'',c.original#>>''{160,successor158}'',''159'',c.original#>>''{160,successor159}'',''160'',c.original#>>''{160,successor160}'')\n AND c.successors->>''157''=c.predecessors->>''157''\n AND c.successors=jsonb_build_object(''157'',local_invoice_fingerprint(),''158'',fa3_draft_fingerprint(),''159'',b2b_invoice_fingerprint(),''160'',b2b_credit_fingerprint(),''161'',credit_source_upgrade_fingerprint())\n AND jsonb_array_length(c.replaced_functions)=2\n AND(c.original#>''{160,original157}'')=c.original->''157'' AND(c.original#>''{160,original158}'')=c.original->''158'' AND(c.original#>''{160,original159}'')=c.original->''159''\n AND c.original#>''{160,original014_indexes}''=(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indexrelid IN(''public.document_order_mode''::regclass,''public.document_return_mode''::regclass)),false);\nEND$function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},"stocktake_adjustment_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"stocktake_adjustment_guards()","definition":"CREATE OR REPLACE FUNCTION public.stocktake_adjustment_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE n text;rel regclass;ownerid oid;BEGIN\n IF to_regprocedure(''public.warehouse_inventory_policy_guards()'') IS NULL OR to_regprocedure(''public.warehouse_inventory_policy(uuid,uuid)'') IS NULL\n OR to_regprocedure(''public.warehouse_inventory_policy_lock(uuid,uuid)'') IS NULL THEN RETURN false;END IF;\n IF NOT public.warehouse_inventory_policy_guards() THEN RETURN false;END IF;\n FOREACH n IN ARRAY ARRAY[''series'',''series_commands'',''counters'',''previews'',''preview_rows'',''admissions'',''receipts'',''documents'',''document_rows''] LOOP\n rel:=to_regclass(''public.stocktake_adjustment_''||n);IF rel IS NULL THEN RETURN false;END IF;\n SELECT relowner INTO ownerid FROM pg_class WHERE oid=rel;\n IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=rel AND relrowsecurity AND relforcerowsecurity AND relkind=''r'')\n OR(SELECT count(*) FROM pg_policy WHERE polrelid=rel)<>1\n OR NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=rel AND polname=''stocktake_adjustment_tenant'' AND polcmd=''*'')\n OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) x WHERE c.oid=rel AND(x.grantee<>ownerid OR x.is_grantable))\n OR EXISTS(SELECT 1 FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x WHERE a.attrelid=rel AND(x.grantee<>ownerid OR x.is_grantable))\n OR NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=rel AND attname=''tenant_id'' AND attnotnull AND NOT attisdropped)\n OR EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=rel AND NOT convalidated) THEN RETURN false;END IF;\n END LOOP;\n IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=''public.stocktake_adjustment_receipts''::regclass AND tgname=''stocktake_adjustment_complete'' AND tgfoid=''public.stocktake_adjustment_complete()''::regprocedure AND tgtype=5 AND tgdeferrable AND tginitdeferred AND tgenabled=''O'')\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=''public.stocktake_adjustment_counters''::regclass AND tgname=''stocktake_adjustment_counter_guard'' AND tgtype=27 AND tgenabled=''O'') THEN RETURN false;END IF;\n FOREACH n IN ARRAY ARRAY[''series'',''series_commands'',''previews'',''preview_rows'',''receipts'',''documents'',''document_rows''] LOOP\n IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass(''public.stocktake_adjustment_''||n) AND tgname=''stocktake_adjustment_immutable'' AND tgfoid=''public.stocktake_adjustment_immutable()''::regprocedure AND tgtype=27 AND tgenabled=''O'') THEN RETURN false;END IF;END LOOP;\n IF EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) x WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''stocktake_adjustment_%'' AND(x.grantee<>p.proowner OR x.is_grantable)) THEN RETURN false;END IF;\n IF EXISTS(SELECT 1 FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''stocktake_adjustment_%'' AND p.proowner<>(SELECT relowner FROM pg_class WHERE oid=''public.stocktake_adjustment_series''::regclass)) THEN RETURN false;END IF;\n IF public.stocktake_adjustment_metadata() IS DISTINCT FROM public.stocktake_adjustment_manifest() THEN RETURN false;END IF;\n RETURN true;\nEND $function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"catalog_stock_control_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"catalog_stock_control_guards()","definition":"CREATE OR REPLACE FUNCTION public.catalog_stock_control_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$ DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid=''public.catalog_stock_control_guards()''::regprocedure);BEGIN\n IF (SELECT count(*) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND p.pronamespace=''public''::regnamespace AND p.proname IN(''catalog_stock_control_xid_claim_guard'',''catalog_stock_control_capture_xid_birth''))<>13 OR\n  to_regprocedure(''public.catalog_stock_control_owns_xmin(xid)'') IS NULL OR\n  to_regprocedure(''public.catalog_stock_control_prune_xid_claims()'') IS NULL THEN RETURN false; END IF;\n IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_return_guards() OR NOT public.catalog_stock_count_guards() OR NOT public.product_catalog_guards() OR NOT public.warehouse_inventory_policy_guards() OR(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname LIKE ''catalog_stock_control_%'' AND relkind=''r'')<>14 THEN RETURN false;END IF;\n IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace=''public''::regnamespace AND c.relname LIKE ''catalog_stock_control_%'' AND c.relkind=''r'' AND(c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner)))a WHERE a.grantee<>ownerid) OR EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner)))a WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''catalog_stock_control_%'' AND(p.proowner<>ownerid OR a.grantee<>ownerid)) THEN RETURN false;END IF;\n RETURN public.manual_inventory_off_valid();END $function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"product_rule_schedule_guards":{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"product_rule_schedule_guards()","definition":"CREATE OR REPLACE FUNCTION public.product_rule_schedule_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$DECLARE signature text;n text;BEGIN\n FOREACH n IN ARRAY ARRAY[''product_rule_schedule_previews'',''product_rule_schedules'',''product_rule_schedule_occurrences'',''product_rule_schedule_manifest''] LOOP IF to_regclass(''public.''||n) IS NULL THEN RETURN false;END IF;END LOOP;\n FOREACH signature IN ARRAY ARRAY[''public.product_rule_schedule_pin(uuid)'',''public.product_rule_schedule_binding()'',''public.product_rule_schedule_preview_guard()'',''public.product_rule_schedule_config_guard()'',''public.product_rule_schedule_fingerprint()'',''public.product_rule_price_tags_guards()''] LOOP IF to_regprocedure(signature) IS NULL THEN RETURN false;END IF;END LOOP;\n RETURN public.product_rule_price_tags_guards() AND(SELECT fingerprint=public.product_rule_schedule_fingerprint() FROM public.product_rule_schedule_manifest WHERE id);\nEND $function$\n","volatility":"v","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"allegro_oauth_recovery_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"sql","parallel":"u","arguments":"","leakproof":false,"signature":"allegro_oauth_recovery_guards()","definition":"CREATE OR REPLACE FUNCTION public.allegro_oauth_recovery_guards()\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT EXISTS(SELECT 1 FROM public.migrations WHERE name=''153_allegro_oauth_recovery'')\n AND (SELECT count(*)=2 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n WHERE n.nspname=''public'' AND c.relname IN (''allegro_oauth_recovery_attempts'',''allegro_oauth_recovery_manifest'')\n AND c.relkind=''r'' AND c.relrowsecurity AND c.relforcerowsecurity AND pg_get_userbyid(c.relowner)=''postgres'')\n AND NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace,\n LATERAL aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) a\n WHERE n.nspname=''public'' AND c.relname IN (''allegro_oauth_recovery_attempts'',''allegro_oauth_recovery_manifest'')\n AND a.grantee<>c.relowner)\n AND NOT EXISTS(SELECT 1 FROM pg_attribute x JOIN pg_class c ON c.oid=x.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace,\n LATERAL aclexplode(x.attacl) a WHERE n.nspname=''public''\n AND c.relname IN (''allegro_oauth_recovery_attempts'',''allegro_oauth_recovery_manifest'') AND a.grantee<>c.relowner)\n AND NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace,\n LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a\n WHERE n.nspname=''public'' AND p.proname LIKE ''allegro_oauth_recovery_%'' AND a.grantee<>p.proowner)\n AND (SELECT count(*)=8 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace\n WHERE n.nspname=''public'' AND p.proname LIKE ''allegro_oauth_recovery_%'' AND pg_get_userbyid(p.proowner)=''postgres'')\n AND (SELECT fingerprint=public.allegro_oauth_recovery_fingerprint() FROM public.allegro_oauth_recovery_manifest WHERE singleton);\n$function$\n","volatility":"s","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":false},"competitor_observation_guards":{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"competitor_observation_guards()","definition":"CREATE OR REPLACE FUNCTION public.competitor_observation_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE predecessor record; original jsonb; portability jsonb; actual_functions jsonb; saved_function jsonb; actual_function jsonb; function_name text; expected_hashes jsonb:=''{\"competitor_observation_available\":\"a48ac8fe33588b7b4fc317c4c8c8e303bbb48fc81c46a24217161d04dda7a3bf\",\"competitor_observation_complete\":\"887cca9418516522c5ad736b59d8edb06f52062f83be89ead868b9c2763c7593\",\"competitor_observation_fingerprint\":\"ac1356982160955e490d130006f6f5a0d73f28343d78dfd5236e8adda51923f4\",\"competitor_observation_guards\":\"f2bd683607433aeb40c4ccd7a185adb7c18ec45f812d11192e47ec934d9a4852\",\"competitor_observation_identity\":\"f85516b1016ce888c4d8a1b74f6099301e6fb0f90aa6055ffbb9f9dd7d6bebf9\",\"competitor_observation_immutable\":\"067fff6f8a7ab5569d03f157ab74ae71e9762d92bf655b58899c50b85ec452c7\",\"competitor_observation_profile_guard\":\"bd61adc6b7fc19065442bfeeb64644b4f5937d5084edf7c032e2f9ebbd204597\",\"competitor_observation_rank_terminal\":\"98c4333f885396e1161e4a0268c92bf1c52831b0d7f2251e026ae985a933efac\",\"competitor_observation_rows_match_request\":\"434288d849bbbf27ebeaf1a4400ab33b196b9c8289639ab4b5723773fb47ba92\",\"competitor_observation_terminal\":\"379399eb4aec1fcc097d55a6421e0eeaf78ff8ba24917aa9389d060a32839f55\",\"competitor_observation_worker_identity\":\"8bec6824cf2423aee46f20ef8c76d027c0b209ceca63acb54f7aa7b7208a2bec\",\"competitor_observation_worker_terminal\":\"be106f8be1ff3ca08e318d1a3f226a6dd48677cd72f6558c6f1bcc168f905b04\"}''::jsonb; manifest record; certificate jsonb; basis record; basis_relation oid; owner_name text; installed boolean;\nBEGIN\n IF to_regclass(''public.competitor_observation_manifest'') IS NULL\n  OR to_regclass(''public.competitor_observation_batches'') IS NULL\n  OR to_regclass(''public.competitor_observations'') IS NULL\n  OR to_regclass(''public.migrations'') IS NULL\n  OR to_regprocedure(''public.competitor_observation_fingerprint()'') IS NULL\n  OR to_regprocedure(''public.competitor_observation_complete()'') IS NULL\n  OR to_regprocedure(''public.competitor_observation_immutable()'') IS NULL\n  OR to_regprocedure(''public.competitor_observation_rows_match_request()'') IS NULL\n  OR NOT EXISTS(SELECT FROM pg_attribute WHERE attrelid=to_regclass(''public.competitor_observation_manifest'') AND attname=''scale_upgrade'' AND NOT attisdropped)\n  OR NOT EXISTS(SELECT FROM pg_attribute WHERE attrelid=to_regclass(''public.competitor_observation_manifest'') AND attname=''portability_upgrade'' AND NOT attisdropped)\n THEN RETURN false;END IF;\n IF(SELECT count(*) FROM public.competitor_observation_manifest)<>1 THEN RETURN false;END IF;\n SELECT * INTO manifest FROM public.competitor_observation_manifest;\n\n portability:=manifest.portability_upgrade; original:=portability->''original_manifest'';\n IF jsonb_typeof(portability) IS DISTINCT FROM ''object'' OR jsonb_typeof(original) IS DISTINCT FROM ''object'' THEN RETURN false;END IF;\n IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(portability) keys(key)) IS DISTINCT FROM ARRAY[''original_manifest'',''predecessor_fingerprint'',''predecessor_functions'',''predecessor_triggers'',''profile'',''successor_fingerprint'']::text[]\n  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(original) keys(key)) IS DISTINCT FROM ARRAY[''fingerprint'',''installed_at'',''profile'',''scale_upgrade'',''singleton'']::text[]\n  OR portability->>''profile'' IS DISTINCT FROM ''164-original-to165-portable-constraints/v1''\n  OR (to_jsonb(manifest)-''portability_upgrade'') IS DISTINCT FROM original\n  OR portability->>''predecessor_fingerprint'' IS DISTINCT FROM original->>''fingerprint''\n  OR NOT coalesce(portability->>''predecessor_fingerprint'' ~ ''^[a-f0-9]{64}$'',false)\n  OR portability->>''successor_fingerprint'' IS DISTINCT FROM public.competitor_observation_fingerprint()\n  OR jsonb_typeof(portability->''predecessor_functions'') IS DISTINCT FROM ''object''\n  OR jsonb_typeof(portability->''predecessor_triggers'') IS DISTINCT FROM ''object''\n THEN RETURN false;END IF;\n actual_functions:=(SELECT jsonb_object_agg(p.proname,jsonb_build_object(''definition'',pg_get_functiondef(p.oid),''body'',p.prosrc,''body_sha256'',encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex''),''owner'',pg_get_userbyid(p.proowner),''acl'',(SELECT jsonb_agg(jsonb_build_object(''grantee'',CASE WHEN a.grantee=0 THEN ''PUBLIC'' ELSE pg_get_userbyid(a.grantee) END,''grantor'',pg_get_userbyid(a.grantor),''privilege'',a.privilege_type,''grantable'',a.is_grantable) ORDER BY a.grantee=0,pg_get_userbyid(a.grantee),pg_get_userbyid(a.grantor),a.privilege_type) FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a),''app_execute'',has_function_privilege(''dyna_app'',p.oid,''EXECUTE''))) FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''competitor_observation%'');\n IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(actual_functions) keys(key)) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(expected_hashes) keys(key))\n  OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(portability->''predecessor_functions'') keys(key)) IS DISTINCT FROM (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(expected_hashes) keys(key))\n  OR portability->''predecessor_triggers'' IS DISTINCT FROM (SELECT jsonb_object_agg(t.tgname,pg_get_triggerdef(t.oid)) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgname LIKE ''competitor_observation%'')\n THEN RETURN false;END IF;\n FOR function_name IN SELECT jsonb_object_keys(expected_hashes) LOOP\n  saved_function:=portability->''predecessor_functions''->function_name;\n  actual_function:=actual_functions->function_name;\n  IF jsonb_typeof(saved_function) IS DISTINCT FROM ''object'' THEN RETURN false;END IF;\n  IF (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(saved_function) keys(key)) IS DISTINCT FROM ARRAY[''acl'',''app_execute'',''body'',''body_sha256'',''definition'',''owner'']::text[]\n   OR saved_function->>''body_sha256'' IS DISTINCT FROM expected_hashes->>function_name\n   OR encode(sha256(convert_to(saved_function->>''body'',''UTF8'')),''hex'') IS DISTINCT FROM expected_hashes->>function_name\n   OR (saved_function-''definition''-''body''-''body_sha256'') IS DISTINCT FROM (actual_function-''definition''-''body''-''body_sha256'')\n  THEN RETURN false;END IF;\n  IF function_name=''competitor_observation_fingerprint'' THEN\n   IF replace(saved_function->>''body'',''pg_get_constraintdef(c.oid)'',''pg_get_constraintdef(c.oid,true)'') IS DISTINCT FROM actual_function->>''body''\n    OR replace(saved_function->>''definition'',''pg_get_constraintdef(c.oid)'',''pg_get_constraintdef(c.oid,true)'') IS DISTINCT FROM actual_function->>''definition''\n   THEN RETURN false;END IF;\n  ELSIF function_name=''competitor_observation_guards'' THEN\n   IF replace(actual_function->>''definition'',actual_function->>''body'',saved_function->>''body'') IS DISTINCT FROM saved_function->>''definition'' THEN RETURN false;END IF;\n  ELSIF saved_function IS DISTINCT FROM actual_function THEN RETURN false;\n  END IF;\n END LOOP;\n SELECT * INTO predecessor FROM jsonb_populate_record(NULL::public.competitor_observation_manifest,original);\n certificate:=predecessor.scale_upgrade;\n IF manifest.profile IS DISTINCT FROM ''local-explicit-observations/v1''\n  OR manifest.singleton IS DISTINCT FROM true\n  OR jsonb_typeof(certificate) IS DISTINCT FROM ''object''\n  OR(SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(certificate) AS certificate_keys(key)) IS DISTINCT FROM ARRAY[''original_manifest'',''predecessor_fingerprint'',''predecessor_functions'',''predecessor_triggers'',''profile'',''successor_fingerprint'']::text[]\n  OR certificate->>''profile'' IS DISTINCT FROM ''163-original-to164-batch-scale/v1''\n  OR certificate->''original_manifest'' IS DISTINCT FROM jsonb_build_object(''singleton'',manifest.singleton,''profile'',manifest.profile,''fingerprint'',certificate->>''predecessor_fingerprint'',''installed_at'',predecessor.installed_at)\n  OR NOT coalesce(certificate->>''predecessor_fingerprint'' ~ ''^[a-f0-9]{64}$'',false)\n  OR certificate->>''successor_fingerprint'' IS DISTINCT FROM predecessor.fingerprint\n  OR certificate->''predecessor_functions''->''competitor_observation_complete''->>''body_sha256'' IS DISTINCT FROM ''887cca9418516522c5ad736b59d8edb06f52062f83be89ead868b9c2763c7593''\n  OR certificate->''predecessor_functions''->''competitor_observation_immutable''->>''body_sha256'' IS DISTINCT FROM ''067fff6f8a7ab5569d03f157ab74ae71e9762d92bf655b58899c50b85ec452c7''\n  OR certificate->''predecessor_functions''->''competitor_observation_guards''->>''body_sha256'' IS DISTINCT FROM ''6aa13d57a08fe6d62f150ec1a3ef5193833a665da2b9d10791c49f22681fea1f''\n  OR certificate->''predecessor_functions''->''competitor_observation_complete''->>''definition'' IS DISTINCT FROM pg_get_functiondef(''public.competitor_observation_complete()''::regprocedure)\n  OR certificate->''predecessor_functions''->''competitor_observation_immutable''->>''definition'' IS DISTINCT FROM pg_get_functiondef(''public.competitor_observation_immutable()''::regprocedure)\n  OR certificate->''predecessor_triggers''->>''competitor_observation_batch_complete'' IS DISTINCT FROM(SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid=''public.competitor_observation_batches''::regclass AND tgname=''competitor_observation_batch_complete'' AND NOT tgisinternal)\n  OR certificate->''predecessor_triggers''->>''competitor_observation_manifest_immutable'' IS DISTINCT FROM(SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid=''public.competitor_observation_manifest''::regclass AND tgname=''competitor_observation_manifest_immutable'' AND NOT tgisinternal)\n  OR EXISTS(SELECT FROM pg_trigger WHERE NOT tgisinternal AND tgname=''competitor_observation_rows_complete'')\n THEN RETURN false;END IF;\n SELECT EXISTS(SELECT FROM public.migrations WHERE name=''165_competitor_observation_portability'') INTO installed;\n IF NOT EXISTS(SELECT FROM public.migrations WHERE name=''164_competitor_observation_batch_scale'') THEN RETURN false;END IF;\n IF NOT EXISTS(SELECT FROM public.migrations WHERE name=''163_competitor_observations'') THEN RETURN false;END IF;\n IF installed THEN RETURN true;END IF;\n -- Only the genuine owner transaction that captured the validated predecessor\n -- may verify before the managed migration loop appends the 165 ledger row.\n basis_relation:=to_regclass(''pg_temp.competitor_observation_portability_basis'');\n SELECT pg_get_userbyid(proowner) INTO owner_name FROM pg_proc WHERE oid=''public.competitor_observation_guards()''::regprocedure;\n IF basis_relation IS NULL OR current_user IS DISTINCT FROM owner_name OR session_user IS DISTINCT FROM owner_name\n  OR current_setting(''role'') NOT IN(''none'',owner_name)\n  OR NOT EXISTS(SELECT FROM pg_class WHERE oid=basis_relation AND relkind=''r'' AND pg_get_userbyid(relowner)=owner_name)\n THEN RETURN false;END IF;\n EXECUTE ''SELECT count(*) count FROM pg_temp.competitor_observation_portability_basis'' INTO basis;\n IF basis.count<>1 THEN RETURN false;END IF;\n EXECUTE ''SELECT * FROM pg_temp.competitor_observation_portability_basis'' INTO basis;\n RETURN basis.root_xid IS NOT DISTINCT FROM pg_current_xact_id_if_assigned()::text\n  AND basis.start_at IS NOT DISTINCT FROM transaction_timestamp()\n  AND basis.backend_pid IS NOT DISTINCT FROM pg_backend_pid()\n  AND basis.owner_name IS NOT DISTINCT FROM owner_name\n  AND basis.original_manifest IS NOT DISTINCT FROM portability->''original_manifest''\n  AND basis.predecessor_fingerprint IS NOT DISTINCT FROM portability->>''predecessor_fingerprint''\n  AND basis.predecessor_functions IS NOT DISTINCT FROM portability->''predecessor_functions''\n  AND basis.predecessor_triggers IS NOT DISTINCT FROM portability->''predecessor_triggers''\n  AND basis.certificate IS NOT DISTINCT FROM portability;\nEND $function$\n","volatility":"s","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":null,"security_definer":true},"warehouse_automatic_wz_guards":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"warehouse_automatic_wz_guards()","definition":"CREATE OR REPLACE FUNCTION public.warehouse_automatic_wz_guards()\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE expected text;\nBEGIN\n IF to_regprocedure(''public.warehouse_inventory_policy_guards()'') IS NULL OR NOT public.warehouse_inventory_policy_guards() THEN RETURN false;END IF;\n IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) a\n  WHERE c.relnamespace=''public''::regnamespace AND c.relkind=''r'' AND c.relname LIKE ''warehouse_automatic_wz_%'' AND a.grantee<>c.relowner)\n OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_attribute b ON b.attrelid=c.oid CROSS JOIN LATERAL aclexplode(b.attacl) a\n  WHERE c.relnamespace=''public''::regnamespace AND c.relkind=''r'' AND c.relname LIKE ''warehouse_automatic_wz_%'' AND a.grantee<>c.relowner)\n OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a\n  WHERE p.pronamespace=''public''::regnamespace AND p.proname LIKE ''warehouse_automatic_wz_%'' AND a.grantee<>p.proowner) THEN RETURN false;END IF;\n SELECT fingerprint INTO expected FROM public.warehouse_automatic_wz_manifest WHERE singleton;\n RETURN expected IS NOT NULL AND expected=public.warehouse_automatic_wz_fingerprint();\nEXCEPTION WHEN undefined_table OR undefined_column OR undefined_function THEN RETURN false;\nEND $function$\n","volatility":"s","returns_set":false,"configuration":["search_path=pg_catalog, public"],"argument_modes":null,"argument_names":null,"security_definer":true},"financial_return_upgrade_valid":{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"boolean","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"","leakproof":false,"signature":"financial_return_upgrade_valid()","definition":"CREATE OR REPLACE FUNCTION public.financial_return_upgrade_valid()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE c record;tab text;sig text;BEGIN\n IF current_setting(''session_replication_role'')<>''origin'' THEN RETURN false;END IF;\n FOREACH tab IN ARRAY ARRAY[''migrations'',''local_invoice_manifest'',''fa3_draft_manifest'',''b2b_invoice_upgrade'',''b2b_credit_upgrade'',''credit_source_upgrade_certificate'',''financial_return_admissions'',''financial_return_receipts'',''financial_return_upgrade_certificate''] LOOP IF to_regclass(''public.''||tab) IS NULL THEN RETURN false;END IF;END LOOP;\n FOREACH sig IN ARRAY ARRAY[''local_invoice_fingerprint()'',''fa3_draft_fingerprint()'',''b2b_invoice_fingerprint()'',''b2b_credit_fingerprint()'',''credit_source_upgrade_fingerprint()'',''credit_source_upgrade_valid()'',''b2b_credit_basis(uuid,uuid)'',''b2b_credit_calculate(jsonb)'',''b2b_credit_previous(uuid)'',''b2b_credit_preview(jsonb,jsonb,jsonb,uuid,uuid,text)'',''b2b_credit_issue(uuid,jsonb,jsonb,jsonb,uuid,uuid,text)'',''b2b_credit_record_guard()'',''b2b_credit_source_seal()'',''credit_source_upgrade_valid()'',''financial_return_identity(uuid,uuid,text,uuid,boolean)'',''financial_return_original(uuid)'',''financial_return_physical(uuid)'',''financial_return_frame(uuid,uuid,text,uuid,jsonb)'',''financial_return_claim(uuid,uuid,text,uuid,jsonb,jsonb)'',''financial_return_received(uuid)'',''financial_return_expected(uuid)'',''financial_return_projection(jsonb,jsonb,jsonb)'',''financial_return_finish(uuid,uuid,text,uuid)'',''financial_return_history(uuid)'',''financial_return_capture(uuid,uuid,text,uuid,jsonb)'',''financial_return_replay(uuid,uuid,text,uuid,jsonb)'',''financial_return_admission_guard()'',''financial_return_receipt_guard()'',''financial_return_complete()'',''financial_return_source_seal()'',''financial_return_terminal(uuid,uuid,text,uuid[])'',''financial_return_credit_parent(uuid,uuid,uuid,uuid)'',''financial_return_upgrade_context()'',''financial_return_fingerprint()'',''financial_return_upgrade_valid()'',''financial_return_upgrade_guard()'',''financial_return_guards()''] LOOP IF to_regprocedure(''public.''||sig) IS NULL THEN RETURN false;END IF;END LOOP;\n IF to_regclass(''public.document_order_mode'') IS NULL OR to_regclass(''public.document_return_mode'') IS NULL THEN RETURN false;END IF;\n IF(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''financial_return_''))<>12\n OR EXISTS(SELECT FROM pg_class relation_index WHERE relation_index.relnamespace=''public''::regnamespace AND starts_with(relation_index.relname,''financial_return_'') AND relation_index.relkind=''i'' AND NOT EXISTS(SELECT FROM pg_index ix JOIN pg_class rel ON rel.oid=ix.indrelid WHERE ix.indexrelid=relation_index.oid AND rel.relnamespace=''public''::regnamespace AND rel.relname IN(''financial_return_admissions'',''financial_return_receipts'',''financial_return_upgrade_certificate'')))\n OR(SELECT count(*) FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''financial_return_'') AND relkind IN(''r'',''p''))<>3\n OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''financial_return_'') AND relkind IN(''r'',''p'') AND NOT(relname=ANY(ARRAY[''financial_return_admissions'',''financial_return_receipts'',''financial_return_upgrade_certificate''])))\n OR EXISTS(SELECT FROM pg_class WHERE relnamespace=''public''::regnamespace AND starts_with(relname,''financial_return_'') AND relkind NOT IN(''r'',''p'',''i''))\n OR(SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND starts_with(proname,''financial_return_''))<>23\n OR(SELECT count(*) FROM pg_trigger tr JOIN pg_proc f ON f.oid=tr.tgfoid WHERE starts_with(tr.tgname,''financial_return_'') OR(f.pronamespace=''public''::regnamespace AND starts_with(f.proname,''financial_return_'')))<>6\n OR EXISTS(SELECT FROM(VALUES(''financial_return_admission_gua