CREATE OR REPLACE FUNCTION public.order_merge_delivery209_history_operative_valid(manual_basis jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE cert operative_delivery_certificate;basis record;o oid;n text;expected jsonb:='{"label_print_frame":"d191d4c1280acb4f6c5dec86c23ce72dfce2a5781ad0b0264ed544372454d0c4","order_parcel_source":"5d1ec193a5a147ca758682a3f15ca86c977797717642b833d657397bc4b80fec","packed_label_print_guards":"899a7420b798208ec7350370eb732b98984de00089ec534d7a73f83e1ffcfe0f"}'::jsonb;buyer319_source text;buyer319_definition text;buyer319_old_definition text;buyer319_meta jsonb;buyer319_entry jsonb;buyer319_functions jsonb;buyer319_fingerprint text;financial319_source text;financial319_definition text;financial319_old_definition text;financial319_meta jsonb;financial319_entry jsonb;financial319_functions jsonb;financial319_fingerprint text;packing_gate214 jsonb;predecessors323 jsonb;financial214 jsonb;tables214 jsonb;functions214 jsonb;BEGIN
 IF current_setting('session_replication_role')<>'origin' OR to_regclass('public.operative_delivery_certificate') IS NULL OR to_regclass('public.operative_delivery_evidence') IS NULL
 OR to_regclass('public.buyer_address_manifest') IS NULL OR to_regclass('public.packed_label_print_manifest') IS NULL
 OR to_regclass('public.migrations') IS NULL
 OR to_regprocedure('public.operative_delivery_fingerprint()') IS NULL OR to_regprocedure('public.operative_delivery_functions()') IS NULL
 OR to_regprocedure('public.packed_label_print_fingerprint()') IS NULL
 OR to_regprocedure('public.buyer_address_fingerprint()') IS NULL OR to_regprocedure('public.buyer_address_predecessors()') IS NULL
 OR NOT EXISTS(SELECT FROM migrations WHERE name='156_packed_label_print') OR NOT EXISTS(SELECT FROM migrations WHERE name='166_buyer_address_sidecar')
 OR (SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'operative_delivery_') AND relkind IN('r','p')) IS DISTINCT FROM ARRAY['operative_delivery_certificate','operative_delivery_evidence']::text[]
 OR (SELECT count(*) FROM operative_delivery_certificate)<>1 THEN RETURN false;END IF;
 SELECT * INTO cert FROM operative_delivery_certificate;
 IF jsonb_typeof(cert.predecessor_functions) IS DISTINCT FROM 'object' OR jsonb_typeof(cert.successor_functions) IS DISTINCT FROM 'object'
 OR jsonb_typeof(cert.original156_manifest) IS DISTINCT FROM 'object' OR jsonb_typeof(cert.original166_manifest) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 -- C26 fullNativeV7 boot admission remains required in the same context; this local gate preserves consumed full definition/header/ACL.
 SELECT public.partial_sale204_predecessor_definition(p.oid) INTO STRICT buyer319_definition FROM pg_proc p WHERE p.oid='public.buyer_address_guards()'::regprocedure;
 buyer319_source:=substring(buyer319_definition FROM 199 FOR 82225);
 IF (SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='buyer_address_guards')<>1
 OR encode(sha256(convert_to(buyer319_source,'UTF8')),'hex') IS DISTINCT FROM '05189f4743482990fd88f100613472051f5896aea40fcb033b8e7c22290f752a'
 OR encode(sha256(convert_to(buyer319_definition,'UTF8')),'hex') IS DISTINCT FROM '05d3465b7d9b5aaa85cf4e2444236cfa471410e605e9476db57202a4725c80f6'
 OR (public.pim_dictionary_function_metadata('public.buyer_address_guards()'::regprocedure)-'definition') IS DISTINCT FROM convert_from(decode('','hex'),'UTF8')::jsonb THEN RETURN false;END IF;
 buyer319_old_definition:=convert_from(decode('','hex'),'UTF8');
 IF replace(buyer319_definition,buyer319_source,convert_from(decode('','hex'),'UTF8')) IS DISTINCT FROM buyer319_old_definition THEN RETURN false;END IF;
