DECLARE r jsonb:=actual;rels jsonb:=''[]'';fs jsonb:=''[]'';rel jsonb;oldrel jsonb;col jsonb;cols jsonb:=''[]'';k jsonb;ks jsonb:=''[]'';f jsonb;b jsonb;found integer:=0;BEGIN
