  FOR guard_name IN SELECT unnest(ARRAY['allegro_oauth_recovery_guards','b2b_credit_guards','b2b_invoice_guards','buyer_address_guards','catalog_stock_control_guards','competitor_observation_guards','fa3_draft_guards','financial_return_upgrade_valid','local_invoice_guards','packed_label_print_guards','parcel_physical_wz_valid','product_rule_schedule_guards','stocktake_adjustment_guards','warehouse_automatic_wz_guards','warehouse_wz_issuer_guards']) LOOP IF guard_name='catalog_stock_control_guards' THEN guard_ok:=public.ordinary181_catalog_guards(manual_basis);ELSIF guard_name='financial_return_upgrade_valid' THEN guard_ok:=public.ordinary181_financial_valid(manual_basis);ELSIF guard_name='credit_source_upgrade_valid' THEN guard_ok:=public.ordinary181_credit_source_valid(manual_basis);ELSIF guard_name='warehouse_wz_issuer_guards' THEN guard_ok:=public.ordinary181_warehouse_issuer_guards(wave_ok);ELSIF guard_name='fa3_draft_guards' THEN guard_ok:=public.ordinary181_fa3_guards(manual_basis);ELSIF guard_name='b2b_invoice_guards' THEN guard_ok:=public.ordinary181_invoice_guards(manual_basis);ELSIF guard_name='buyer_address_guards' THEN guard_ok:=public.order_merge_delivery209_buyer_guards(manual_basis);ELSIF guard_name='b2b_credit_guards' THEN guard_ok:=public.ordinary181_credit_guards(manual_basis);ELSIF guard_name='packed_label_print_guards' THEN guard_ok:=public.ordinary181_packed_guards(wave_ok);ELSIF guard_name='parcel_physical_wz_valid' THEN guard_ok:=public.ordinary181_parcel_valid(wave_ok);ELSE EXECUTE format('SELECT public.%I()',guard_name) INTO guard_ok;END IF;IF guard_ok IS DISTINCT FROM true THEN RETURN false;END IF;END LOOP;
