D api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind IS DISTINCT FROM ''''upload'''' OR client0 IS NULL THEN RAISE EXCEPTION ''''Absent reconciliation upload not owned'''' USING ERRCODE=''''42501'''';END IF;\n IF b.state=''''retained'''' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''''event:upload-absent-close:''''||client0::text AND state=''''settled'''';\n  IF NOT FOUND OR b.outcome IS DISTINCT FROM ''''absent'''' OR old.payload_text::jsonb->''''receipt''''->>''''client_key'''' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''''Absent reconciliation original key conflict'''' USING ERRCODE=''''23505'''';END IF;\n  RETURN jsonb_build_object(''''reused'''',true,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',old.payload_text::jsonb->''''receipt'''');\n END IF;\n IF b.state IS DISTINCT FROM ''''unknown'''' THEN RAISE EXCEPTION ''''Absent reconciliation requires committed unknown writer fence'''' USING ERRCODE=''''40001'''';END IF;\n -- UPDATE conflicts with every mandatory writer SHARE pin. A prior writer completes before this cut;\n -- strengthened publication_pin requires OPEN, so no later writer may publish while/after UNKNOWN.\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n prefix0:=t::text||''''/''''||u::text||''''/''''||CASE WHEN k IS NULL THEN ''''sessions'''' ELSE ''''key-''''||k::text END;\n paths0:=ARRAY[t::text,t::text||''''/''''||u::text,prefix0,prefix0||''''/uploads'''',prefix0||''''/uploads/''''||b.request_id::text];\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''''[]''''::jsonb) INTO resources0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(resources0)<>5 THEN RAISE EXCEPTION ''''Absent reconciliation requires exact five-directory prefix'''' USING ERRCODE=''''23514'''';END IF;\n FOR x IN SELEC