NOT FOUND OR x.state=''''released'''' OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha THEN RAISE EXCEPTION ''''Publication allocation changed/terminal'''' USING ERRCODE=''''40001'''';END IF;\nEND $function$\n","volatility":"v","body_sha256":"f012443a27ade40482d3ac47fd2a43ef55a84061f2067fbd78ec39a0c5293062","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","n","sha"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"void","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_publication_pin_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_publication_pin_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;v jsonb;seen text[]:=ARRAY[]::text[];\nBEGIN\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n IF q IS NULL OR token IS NULL OR token !~ ''''^[a-f0-9]{64}$'''' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''Publication group shape'''' USING ERRCODE=''''22023'''';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>65536 THEN RAISE EXCEPTION ''''Publication group bound'''' USING ERRCODE=''''22023'''';END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''''object'''' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''''byte_count'''',''''key'''',''''sha256'''']::text[] OR jsonb_typeof(v->''''key'''') IS DISTINCT FROM ''''string'''' OR (v->>''''key'''') !~ ''''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'''' OR jsonb_typeof(v->''''sha256'''') IS DISTINCT FROM ''''string'''' OR (v->>''''sha256'''') !~ ''''^[a-f0-9]{64}$'''' OR jsonb_typeof(v->''''byte_count'''') IS DISTINCT FROM ''''number'''' OR (v->>''''byte_count'''') !~ ''''^(0|[1-9][0-9]{0,15})$'''' OR (v->>''''byte_count'''')::numeric>9007199254740991 OR (v->>''''key'''')=ANY(seen) THEN RAISE EXCEPTION ''''Publication group item'''' USING ERRCODE=''''22023'''';END IF;\n  seen:=array_append(seen,v->>''''key'''');\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND OR b.state IS DISTINCT FROM ''''open'''' THEN RAISE EXCEPTION ''''Publication reservation is not active/owned'''' USING ERRCODE=''''42501'''';END IF;\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR SHARE;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \"C\" LOOP\n  SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''''key'''';\n  IF NOT FOUND OR x.state=''''released'''' OR x.byte_count IS DISTINCT FROM (v->>''''byte_count'''')::bigint OR x.sha256 IS DISTINCT FROM v->>''''sha256'''' THEN RAISE EXCEPTION ''''Publication allocation changed/terminal'''' USING ERRCODE=''''40001'''';END IF;\n END LOOP;\n -- Full fresh currentIAM/graph still present on both sides of pins; FS transaction caller also\n -- retains its original late checkpoint AFTER actual writes. There is no cached schema verdict.\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\nEND $function$\n","volatility":"v","body_sha256":"3e8e0c6adedf6290770084ef82ff4bf3fa14f12fbcbab33970ba5f26f6bb6786","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, request uuid, token text, kind0 text, raw0 bigint, metadata0 bigint, objects0 bigint","leakproof":false,"signature":"large_import_quota_reserve173(uuid,uuid,uuid,text,text,uuid,uuid,text,text,bigint,bigint,bigint)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_reserve173(u uuid, t uuid, k uuid, r text, h text, q uuid, request uuid, token text, kind0 text, raw0 bigint, metadata0 bigint, objects0 bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE old record;p record;x record;today date:=(clock_timestamp() AT TIME ZONE ''''UTC'''')::date;deadline timestamptz;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR request IS NULL OR token IS NULL OR token !~ ''''^[a-f0-9]{64}$'''' OR kind0 IS NULL OR kind0 NOT IN(''''upload'''',''''job'''',''''review'''') OR raw0 IS NULL OR raw0<0 OR metadata0 IS NULL OR metadata0<0 OR objects0 IS NULL OR objects0<1 THEN RAISE EXCEPTION ''''Quota reservation shape'''' USING ERRCODE=''''22023'''';END IF;\n SELECT * INTO old FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND request_id=request FOR UPDATE;\n IF FOUND THEN\n  IF old.id IS DISTINCT FROM q OR old.actor_id IS DISTINCT FROM u OR old.api_key_id IS DISTINCT FROM k OR old.token_hash IS DISTINCT FROM token OR old.kind IS DISTINCT FROM kind0 OR old.raw_ceiling IS DISTINCT FROM raw0 OR old.metadata_ceiling IS DISTINCT FROM metadata0 OR old.objects_ceiling IS DISTINCT FROM objects0 THEN RAISE EXCEPTION ''''Quota request identity conflict'''' USING ERRCODE=''''23505'''';END IF;\n  RETURN (to_jsonb(old)-''''token_hash'''')||jsonb_build_object(''''reused'''',true); -- Exact uncertain-ACK lookup. No new capacity, expiry extension, callback rerun or token rotation.\n END IF;\n FOR p IN SELECT * FROM public.large_import_quota_policies173 WHERE scope IN(''''global'''',''''tenant:''''||t::text) ORDER BY scope FOR SHARE LOOP\n  SELECT coalesce(sum(CASE WHEN state=''''retained'''' THEN raw_charge ELSE raw_ceiling END),0) raw_used,\n   coalesce(sum(CASE WHEN state=''''retained'''' THEN metadata_charge ELSE metadata_ceiling END),0) metadata_used,\n   coalesce(sum(CASE WHEN state=''''retained'''' THEN objects_charge ELSE objects_ceiling END),0) objects_used,\n   count(*) FILTER(WHERE (opened_at AT TIME ZONE ''''UTC'''')::date=today) daily_used INTO x\n  FROM public.large_import_quota_reservations173 WHERE p.scope=''''global'''' OR tenant_id=t;\n  IF x.raw_used+p.baseline_raw+raw0>p.raw_limit OR x.metadata_used+p.baseline_metadata+metadata0>p.metadata_limit OR x.objects_used+p.baseline_objects+objects0>p.objects_limit OR x.daily_used+(CASE WHEN p.baseline_day=today THEN p.baseline_daily ELSE 0 END)+1>p.daily_limit THEN RAISE EXCEPTION ''''Retained import quota exhausted'''' USING ERRCODE=''''54000'''';END IF;\n END LOOP;\n SELECT clock_timestamp()+lease_seconds*interval ''''1 second'''' INTO deadline FROM public.large_import_quota_policies173 WHERE scope=''''tenant:''''||t::text;\n INSERT INTO public.large_import_quota_reservations173(tenant_id,id,actor_id,api_key_id,request_id,token_hash,kind,raw_ceiling,metadata_ceiling,objects_ceiling,expires_at) VALUES(t,q,u,k,request,token,kind0,raw0,metadata0,objects0,deadline) RETURNING * INTO old;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN (to_jsonb(old)-''''token_hash'''')||jsonb_build_object(''''reused'''',false);\nEND $function$\n","volatility":"v","body_sha256":"5ce0bd45268272956a61fefe19cd00310b48cf1f8c1978e58c64dcfab01877da","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","request","token","kind0","raw0","metadata0","objects0"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text, quarantined boolean","leakproof":false,"signature":"large_import_quota_settle173(uuid,uuid,uuid,text,text,uuid,text,text,bigint,text,boolean)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_settle173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, n bigint, sha text, quarantined boolean)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;state0 text;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF token IS NULL OR key0 IS NULL OR n IS NULL OR n<0 OR sha IS NULL OR quarantined IS NULL THEN RAISE EXCEPTION ''''Quota settlement shape'''' USING ERRCODE=''''22023'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.state=''''retained'''' THEN RAISE EXCEPTION ''''Quota settlement ownership/state'''' USING ERRCODE=''''42501'''';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR UPDATE;\n IF NOT FOUND OR x.byte_count IS DISTINCT FROM n OR x.sha256 IS DISTINCT FROM sha THEN RAISE EXCEPTION ''''Quota inspected resource mismatch'''' USING ERRCODE=''''23514'''';END IF;\n IF x.state=''''released'''' THEN RAISE EXCEPTION ''''Terminal allocation cannot be settled as retained bytes'''' USING ERRCODE=''''23505'''';END IF;\n state0:=(CASE WHEN quarantined THEN ''''quarantined'''' ELSE ''''settled'''' END);\n IF x.state=''''quarantined'''' AND state0<>''''quarantined'''' THEN RAISE EXCEPTION ''''Quota settlement replay conflict'''' USING ERRCODE=''''23505'''';END IF;\n UPDATE public.large_import_quota_resources173 SET state=state0 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 RETURNING * INTO x;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(x);\nEND $function$\n","volatility":"v","body_sha256":"8bd28f5a3e55d52c64eeea3fd3086097f4a32979ef050465d83611138fa24569","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","n","sha","quarantined"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb","leakproof":false,"signature":"large_import_quota_settle_many173(uuid,uuid,uuid,text,text,uuid,text,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_settle_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;v jsonb;key0 text;kind0 text;n bigint;sha text;payload text;state0 text;seen text[]:=ARRAY[]::text[];result jsonb:=''''[]''''::jsonb;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n IF q IS NULL OR token IS NULL OR token !~ ''''^[a-f0-9]{64}$'''' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM ''''array'''' THEN RAISE EXCEPTION ''''Quota settlement group shape'''' USING ERRCODE=''''22023'''';END IF;\n IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>8388608 THEN RAISE EXCEPTION ''''Quota settlement group bound'''' USING ERRCODE=''''22023'''';END IF;\n FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP\n  IF jsonb_typeof(v) IS DISTINCT FROM ''''object'''' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY[''''byte_count'''',''''key'''',''''kind'''',''''payload_text'''',''''sha256'''',''''state'''']::text[] OR jsonb_typeof(v->''''key'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''kind'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''sha256'''') IS DISTINCT FROM ''''string'''' OR jsonb_typeof(v->''''byte_count'''') IS DISTINCT FROM ''''number'''' OR (v->>''''byte_count'''') !~ ''''^(0|[1-9][0-9]{0,15})$'''' OR jsonb_typeof(v->''''state'''') IS DISTINCT FROM ''''string'''' THEN RAISE EXCEPTION ''''Quota settlement item shape'''' USING ERRCODE=''''22023'''';END IF;\n  key0:=v->>''''key'''';kind0:=v->>''''kind'''';n:=(v->>''''byte_count'''')::bigint;sha:=v->>''''sha256'''';payload:=v->>''''payload_text'''';state0:=v->>''''state'''';\n  IF key0 !~ ''''^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$'''' OR kind0 NOT IN(''''raw'''',''''blob'''',''''batch'''',''''job'''',''''review'''',''''event'''') OR split_part(key0,'''':'''',1) IS DISTINCT FROM kind0 OR sha !~ ''''^[a-f0-9]{64}$'''' OR n>9007199254740991 OR key0=ANY(seen) OR state0 NOT IN(''''settled'''',''''quarantined'''') THEN RAISE EXCEPTION ''''Quota settlement item identity'''' USING ERRCODE=''''22023'''';END IF;\n  IF (kind0=''''raw'''' AND jsonb_typeof(v->''''payload_text'''') IS DISTINCT FROM ''''null'''') OR (kind0<>''''raw'''' AND (jsonb_typeof(v->''''payload_text'''') IS DISTINCT FROM ''''string'''' OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,''''UTF8'''')),''''hex'''') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION ''''Quota settlement exact payload'''' USING ERRCODE=''''23514'''';END IF;\n  seen:=array_append(seen,key0);\n END LOOP;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.state=''''retained'''' THEN RAISE EXCEPTION ''''Quota settlement ownership/state'''' USING ERRCODE=''''42501'''';END IF;\n PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE \"C\" FOR UPDATE;\n -- Complete readback group is checked before the first state update; native bindings include\n -- full kind/payload as well as bytes/hash. UNKNOWN may settle prior observed bytes exactly as\n -- old settle173; it never permits new publication, minting or terminal ABSENT reopening.\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \"C\" LOOP\n  SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''''key'''';\n  IF NOT FOUND OR x.kind IS DISTINCT FROM v->>''''kind'''' OR x.byte_count IS DISTINCT FROM (v->>''''byte_count'''')::bigint OR x.sha256 IS DISTINCT FROM v->>''''sha256'''' OR x.payload_text IS DISTINCT FROM v->>''''payload_text'''' THEN RAISE EXCEPTION ''''Quota inspected group mismatch'''' USING ERRCODE=''''23514'''';END IF;\n  IF x.state=''''released'''' OR (x.state=''''quarantined'''' AND v->>''''state''''<>''''quarantined'''') THEN RAISE EXCEPTION ''''Quota settlement replay conflict'''' USING ERRCODE=''''23505'''';END IF;\n END LOOP;\n FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>''''key'''') COLLATE \"C\" LOOP\n  -- Deliberately retains old settle173 DML semantics even for identical-state replay.\n  UPDATE public.large_import_quota_resources173 SET state=v->>''''state'''' WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>''''key'''' RETURNING * INTO x;\n  result:=result||jsonb_build_array(to_jsonb(x));\n END LOOP;\n PERFORM public.large_import173_admit(u,t,k,r,h,true);\n RETURN result;\nEND $function$\n","volatility":"v","body_sha256":"a4ea1839b0ed83787d295e397534678b4272d94a43179bcc28931445bdf29827","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","items"],"security_definer":true},{"acl":[["postgres","dyna_app","EXECUTE",false],["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text","leakproof":false,"signature":"large_import_quota_snapshot173(uuid,uuid,uuid,text,text,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_snapshot173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x jsonb;\nBEGIN\n PERFORM public.large_import_quota_authorize173(u,t,k,r,h);\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION ''''Quota snapshot not owned'''' USING ERRCODE=''''42501'''';END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''''[]''''::jsonb) INTO x FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n RETURN jsonb_build_object(''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resources'''',x);\nEND $function$\n","volatility":"v","body_sha256":"26649bcb6b833bb791e7d7d333635b2511a222ace3edb1c6de9a0a9e74e0ad99","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid","leakproof":false,"signature":"large_import_quota_terminal_begin173(uuid,uuid,uuid,text,text,uuid,text,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;x record;receipt record;classification text;policy_count integer;\nBEGIN\n IF current_setting(''''transaction_isolation'''') IS DISTINCT FROM ''''read committed'''' THEN RAISE EXCEPTION ''''Terminal writes require READ COMMITTED'''' USING ERRCODE=''''25000'''';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:global'''',0));PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:tenant:''''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''''global'''',''''tenant:''''||t::text) ORDER BY scope FOR SHARE;\n GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''''Terminal quota policy absent'''' USING ERRCODE=''''55000'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind<>''''upload'''' OR client0 IS NULL THEN RAISE EXCEPTION ''''Terminal upload reservation not owned'''' USING ERRCODE=''''42501'''';END IF;\n SELECT * INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0 FOR UPDATE;\n IF NOT FOUND OR x.kind<>''''blob'''' THEN RAISE EXCEPTION ''''Only exact upload cleanup allocations are terminal candidates'''' USING ERRCODE=''''22023'''';END IF;\n IF x.state=''''released'''' THEN\n  SELECT * INTO receipt FROM public.large_import_quota_terminal_receipts173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;\n  IF NOT FOUND OR receipt.client_key IS DISTINCT FROM client0 THEN RAISE EXCEPTION ''''Terminal exact-key recovery conflict'''' USING ERRCODE=''''23505'''';END IF;\n  RETURN jsonb_build_object(''''reused'''',true,''''receipt'''',to_jsonb(receipt)); -- Read original receipt; no FS callback, new evidence, time or key.\n END IF;\n IF b.state=''''retained'''' THEN RAISE EXCEPTION ''''Closed quota cannot be rewritten'''' USING ERRCODE=''''42501'''';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true); -- Refresh after reservation lock, before the private FS cut.\n IF key0 ~ ''''^blob:fs:blobs:[a-f0-9-]{36}:quarantine-json$'''' AND x.state=''''intent'''' THEN classification:=''''unused-quarantine'''';\n ELSIF key0 ~ ''''^blob:fs:(blobs|uploads|witnesses):[a-f0-9-]{36}:lock:[a-f0-9-]{36}$'''' AND x.state IN(''''intent'''',''''settled'''') THEN classification:=''''released-lock'''';\n ELSE RAISE EXCEPTION ''''Allocation is not a cancellable cleanup/lock'''' USING ERRCODE=''''22023'''';END IF;\n RETURN jsonb_build_object(''''reused'''',false,''''classification'''',classification,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resource'''',to_jsonb(x));\nEND $function$\n","volatility":"v","body_sha256":"7c7fc4e216bfe5d5488ae717d1e8167ecbcd15ea98daf917eb5a3d19e8e89a38","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","key0","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arguments":"u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid","leakproof":false,"signature":"large_import_quota_terminal_close_begin173(uuid,uuid,uuid,text,text,uuid,text,uuid)","definition":"CREATE OR REPLACE FUNCTION public.large_import_quota_terminal_close_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''''pg_catalog'''', ''''public''''\n SET \"TimeZone\" TO ''''UTC''''\nAS $function$\nDECLARE b record;policy_count integer;old record;snapshot0 jsonb;\nBEGIN\n IF current_setting(''''transaction_isolation'''') IS DISTINCT FROM ''''read committed'''' THEN RAISE EXCEPTION ''''Terminal writes require READ COMMITTED'''' USING ERRCODE=''''25000'''';END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:global'''',0));PERFORM pg_advisory_xact_lock(hashtextextended(''''large-import173:quota:tenant:''''||t::text,0));\n PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN(''''global'''',''''tenant:''''||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;\n IF policy_count<>2 THEN RAISE EXCEPTION ''''Terminal quota policy absent'''' USING ERRCODE=''''55000'''';END IF;\n SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;\n IF NOT FOUND OR b.kind<>''''upload'''' OR client0 IS NULL THEN RAISE EXCEPTION ''''Known-close upload not owned'''' USING ERRCODE=''''42501'''';END IF;\n IF b.state=''''retained'''' THEN\n  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=''''event:upload-known-close:''''||client0::text AND state=''''settled'''';\n  IF NOT FOUND OR b.outcome<>''''ready'''' OR old.payload_text::jsonb->''''receipt''''->>''''client_key'''' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION ''''Known-close original key conflict'''' USING ERRCODE=''''23505'''';END IF;\n  RETURN jsonb_build_object(''''reused'''',true,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''receipt'''',old.payload_text::jsonb->''''receipt''''); -- no fresh cut or callback on exact old-key recovery\n END IF;\n PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);\n SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE \"C\"),''''[]''''::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;\n IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>''''state''''=''''intent'''') THEN RAISE EXCEPTION ''''Known close has pending original allocations'''' USING ERRCODE=''''40001'''';END IF;\n RETURN jsonb_build_object(''''reused'''',false,''''reservation'''',to_jsonb(b)-''''token_hash'''',''''resources'''',snapshot0);\nEND $function$\n","volatility":"v","body_sha256":"40781129baeb2b9756351d74242ab2eaab9ba90060a1e7797c8ba0c7a2e78ccb","returns_set":false,"configuration":["search_path=pg_catalog, public","TimeZone=UTC"],"argument_modes":null,"argument_names":["u","t","k","r","h","q","token","client0"],"security_definer":true},{"acl":[["postgres","postgres","EXECUTE",false]],"cost":100,"kind":"f","rows":0,"owner":"postgres","result":"jsonb","strict":false,"defaults":null,"language":"plpgsql","parallel":"u","arg